window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q13"]=window.__LIBQ["the-gioi-hoan-my"]["q13"]||{};window.__LIBQ["the-gioi-hoan-my"]["q13"]["artifacts"]={"updatedAt":"2026-07-26","count":145,"artifacts":[{"id":"xanh-tham-giap-tru","name":"Xanh thẳm giáp trụ","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Giáp trụ","phamCap":"Tiên Cổ di bảo","soHuu":["Tiểu Thiên Vương","Thạch Hạo"],"trangThai":"Do Thạch Hạo tạm giữ","blurb":"Xanh thẳm giáp trụ là bộ giáp màu xanh vốn thuộc về Tiểu Thiên Vương. Sau khi đổi chủ, pháp bảo được Thạch Hạo tạm giữ để nghiên cứu với sự cho phép của lão quái vật Tiên viện @c1201.","detail":"Xanh thẳm giáp trụ ban đầu thuộc về Tiểu Thiên Vương, sau đó rơi vào tay Thạch Hạo như một chiến lợi phẩm. Nhị trưởng lão từng yêu cầu hoàn trả, nhưng lão quái vật Tiên viện cho phép Thạch Hạo tiếp tục tạm giữ để nghiên cứu, qua đó xác lập quyền nắm giữ của hắn tại thời điểm này @c1201. Khi yên tĩnh, giáp trụ chỉ tỏa hào quang xanh lam ảm đạm; khi được thần lực thúc giục, nó trở nên xán lạn chói mắt.","phanLoaiPhu":"Giáp trụ phòng hộ","hinhDang":"Giáp trụ màu xanh thẳm","uyLuc":"Khi được thần lực thúc giục, giáp trụ phát sáng xán lạn.","dacDiem":"Ở trạng thái yên tĩnh, giáp trụ chỉ tỏa hào quang xanh lam ảm đạm.","chuHienThoi":"Thạch Hạo","congNang":["Có thể được thần lực thúc giục để phát sáng xán lạn @c1201"],"chuSoHuu":[{"ten":"Tiểu Thiên Vương","tuChuong":"@c1201","denChuong":"@c1201","cachCoDuoc":"Chủ nhân ban đầu được xác nhận","trangThai":"Đã mất quyền nắm giữ"},{"ten":"Thạch Hạo","tuChuong":"@c1201","denChuong":"","cachCoDuoc":"Thu làm chiến lợi phẩm từ kẻ thù và được phép tạm giữ","trangThai":"Đang tạm giữ"}],"capNhatToi":"@c1201","tabs":{"tienTrinh":[{"chuong":"@c1201","loai":"đổi chủ","importance":"major","giaiDoan":"Thạch Hạo tạm giữ","phamCap":"Tiên Cổ di bảo","text":"Quyền nắm giữ xanh thẳm giáp trụ chuyển từ phía Tiểu Thiên Vương sang Thạch Hạo sau khi lão quái vật Tiên viện công nhận đây là chiến lợi phẩm và cho phép hắn nghiên cứu.","anchor":"vật này là một cái Tiên Cổ di bảo, xác thực rất bất phàm"}]},"nguon":["@c1201"]},{"id":"chien-ngau-set-danh","name":"Chiến ngẫu sét đánh","cn":"","aliases":[],"category":"khac","categoryLabel":"Chiến ngẫu","phamCap":"Hiếm thấy tinh phẩm","soHuu":["Ngũ Trưởng Lão"],"trangThai":"Nguyên vẹn","blurb":"Chiến ngẫu do Ngũ Trưởng Lão tế luyện nhiều năm, ban đầu chỉ lớn ba tấc nhưng có thể hóa thành võ sĩ mặc ô kim giáp. Nó được dùng để thăm dò thung lũng tại Âm Dương nhãn.","detail":"Chiến ngẫu được chế từ tượng gỗ sét đánh, có thực lực vượt xa Thiên Thần. Một tia Nguyên Thần dấu ấn của Ngũ Trưởng Lão có thể dung hợp với nó để truyền cảm nhận trong quá trình thăm dò.","phanLoaiPhu":"Chiến ngẫu thăm dò","hinhDang":"Tượng gỗ ba tấc, có thể lớn thành võ sĩ mặc ô kim giáp","vatLieu":"Tượng gỗ sét đánh","uyLuc":"Thực lực vượt xa Thiên Thần.","dacDiem":"Có thể dung hợp với một tia Nguyên Thần dấu ấn của chủ nhân.","chuHienThoi":"Ngũ Trưởng Lão","congNang":["Thăm dò khu vực nguy hiểm và chia sẻ cảm nhận qua Nguyên Thần dấu ấn."],"chuSoHuu":[{"ten":"Ngũ Trưởng Lão","tuChuong":"@c1202","denChuong":"","cachCoDuoc":"Đã tế luyện nhiều năm","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1202","tabs":{"tienTrinh":[{"chuong":"@c1202","loai":"dùng","importance":"normal","giaiDoan":"Thăm dò Âm Dương nhãn","text":"Ngũ Trưởng Lão đưa chiến ngẫu vào thung lũng và dùng Nguyên Thần dấu ấn để quan sát tình hình từ xa.","anchor":"Này con chiến ngẫu là hiếm thấy tinh phẩm, thực lực mạnh phi thường, vượt xa Thiên Thần","phamCap":"Hiếm thấy tinh phẩm"}]},"nguon":["@c1202"]},{"id":"dai-duoc-phuc-sinh-tien-vuong","name":"Đại dược phục sinh Tiên Vương","cn":"","aliases":["Thiên Chủng"],"category":"dan-duoc","categoryLabel":"Tiên gia đại dược","phamCap":"Tiên gia","soHuu":[],"trangThai":"Được cho là đã tới lúc ra lò","blurb":"Đại dược phục sinh Tiên Vương là tiên gia đại dược được nhắc đến trong di khắc tại khu vực phong ấn ở Âm Dương nhãn. Theo ghi chép, cổ nhân đã luyện nó suốt một kỷ nguyên và đại dược được cho là đã tới thời điểm ra lò, nhưng sự tồn tại thực tế vẫn chưa được kiểm chứng.","detail":"Theo văn khắc, cổ nhân lấy Ngũ hành đại lục làm lò, lấy năm tháng làm lửa để luyện chế đại dược trong suốt một kỷ nguyên tại khu vực phong ấn ở Âm Dương nhãn. Di khắc cho biết đây là tiên gia đại dược có thể phục sinh Tiên Vương và đã tới thời điểm ra lò; các trưởng lão còn suy đoán Thiên Chủng trong ghi chép có thể chính là đại dược này. Tuy nhiên, cách giải đọc văn khắc và sự tồn tại thực tế của đại dược vẫn chưa được kiểm chứng.","nguonGoc":"Được cổ nhân luyện tại khu vực phong ấn ở Âm Dương nhãn","uyLuc":"Được di khắc ghi lại là tiên gia đại dược có thể phục sinh Tiên Vương. @c1202","dacDiem":"Được cổ nhân luyện tại khu vực phong ấn ở Âm Dương nhãn bằng cách lấy Ngũ hành đại lục làm lò, lấy năm tháng làm lửa; quá trình luyện chế kéo dài suốt một kỷ nguyên và được cho là đã tới thời điểm ra lò. @c1202","congNang":["Có khả năng phục sinh Tiên Vương theo nội dung di khắc. @c1202"],"capNhatToi":"@c1202","tabs":{"tienTrinh":[{"chuong":"@c1202","loai":"xuất hiện","importance":"major","giaiDoan":"Được cho là sắp ra lò","text":"Di khắc hé lộ một tiên gia đại dược có thể phục sinh Tiên Vương và được cho là đã tới thời điểm ra lò.","anchor":"bởi vì cái kia đan dược là tiên gia đồ vật, có thể phục sinh Tiên Vương","phamCap":"Tiên gia"}]},"nguon":["@c1202"]},{"id":"hat-giong-hoan-my-phoi-hop-phong-an","name":"Hạt giống hoàn mỹ phối hợp phong ấn","cn":"","aliases":[],"category":"khac","categoryLabel":"Hạt giống","phamCap":"Hoàn mỹ không tì vết","soHuu":[],"trangThai":"Chưa xác nhận tung tích","blurb":"Hạt giống hoàn mỹ được nhắc tới trong di khắc tại thung lũng. Nó được lưu lại để phối hợp với phong ấn cự hung, nhưng sự tồn tại hiện thời chưa được xác nhận.","detail":"Các văn khắc cho biết một viên hạt giống hoàn mỹ không tì vết từng được để lại nhằm phối hợp phong ấn cự hung. Nhị Trưởng Lão và Ngũ Trưởng Lão chưa thể xác định ghi chép này có hoàn toàn đáng tin hay không.","congNang":["Phối hợp với phong ấn cự hung theo nội dung di khắc."],"dacDiem":"Được mô tả là hoàn mỹ không một tì vết.","capNhatToi":"@c1202","tabs":{"tienTrinh":[{"chuong":"@c1202","loai":"nhắc tới","importance":"normal","giaiDoan":"Manh mối trong di khắc","text":"Các trưởng lão phát hiện ghi chép về một hạt giống hoàn mỹ được lưu lại để phối hợp phong ấn cự hung.","anchor":"có một viên hoàn mỹ không một tì vết hạt giống, là vì phối hợp phong ấn cự hung lưu lại","phamCap":"Hoàn mỹ không tì vết"}]},"nguon":["@c1202"]},{"id":"can-khon-lo","name":"Càn Khôn lô","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Dược lô","phamCap":"Không rõ","soHuu":[],"trangThai":"Sắp được khai mở","blurb":"Càn Khôn lô là dược lô nằm trong khu vực phong ấn, gắn với việc luyện chế và chứa đại dược. Do hậu quả khi mở lò chưa thể dự đoán, Thiên Thần Thư Viện và Tiên Viện đã thỏa thuận liên thủ khai phong để ứng phó biến cố khó lường.","detail":"Càn Khôn lô được dùng trong quá trình luyện chế đại dược bằng Ngũ hành đại lục và năm tháng, đồng thời nằm tại khu vực phong ấn và được cho là chứa đại dược. Trước nguy cơ phát sinh biến cố chưa rõ khi mở lò, Thiên Thần Thư Viện và Tiên Viện tạm thời hợp tác, cùng tiến hành khai phong tại @c1202.","congNang":["Luyện chế và chứa đại dược tại khu vực phong ấn."],"dacDiem":"Hậu quả khi mở lò chưa thể dự đoán; việc khai phong đòi hỏi Thiên Thần Thư Viện và Tiên Viện liên thủ để ứng phó biến cố khó lường. @c1202","capNhatToi":"@c1202","tabs":{"tienTrinh":[{"chuong":"@c1202","loai":"khai phong","importance":"major","giaiDoan":"Hai viện chuẩn bị mở lò","text":"Thiên Thần Thư Viện và Tiên Viện đạt thỏa thuận liên thủ mở Càn Khôn lô để ứng phó biến cố khó lường.","anchor":"ai cũng không nói được một khi mở ra dược lô sẽ phát sinh cái gì","phamCap":"Không rõ"}]},"nguon":["@c1202"]},{"id":"canh-phuong-tien-kim-dang","name":"Cánh phượng tiên kim đảng","cn":"","aliases":[],"category":"than-khi","categoryLabel":"Thần binh","phanLoaiPhu":"Binh khí hạng nặng","phamCap":"Không rõ","soHuu":["Nữ đệ tử Tiên Viện cầm cánh phượng tiên kim đảng"],"chuHienThoi":"Nữ đệ tử Tiên Viện cầm cánh phượng tiên kim đảng","trangThai":"Hoàn hảo","vatLieu":"Pha quang minh tiên kim","uyLuc":"Tạo ra lưỡi gió có thể cắt đứt hư không.","dacDiem":"Tỏa ánh sáng trắng thịnh liệt như một vầng mặt trời.","congNang":["Tạo lưỡi gió cắt đứt hư không khi được vung lên."],"chuSoHuu":[{"ten":"Nữ đệ tử Tiên Viện cầm cánh phượng tiên kim đảng","tuChuong":"@c1204","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"blurb":"Thần binh hạng nặng pha quang minh tiên kim của một nữ đệ tử Tiên Viện. Binh khí tỏa ánh sáng trắng mãnh liệt và tạo lưỡi gió cắt hư không.","detail":"Nữ đệ tử Tiên Viện dùng cánh phượng tiên kim đảng tấn công trực tiếp khi bảo thuật bị pháp lực miễn dịch hóa giải. Thạch Hạo vận dụng Côn Bằng lực đối đầu và đánh binh khí rung mạnh.","tabs":{"tienTrinh":[{"chuong":"@c1204","loai":"dùng","importance":"normal","giaiDoan":"Tranh đoạt Dẫn Hồn Liên","text":"Nữ đệ tử Tiên Viện dùng cánh phượng tiên kim đảng tấn công trực tiếp Thạch Hạo.","anchor":"Tiên Viện nữ tử la thất thanh, nàng vung lên cánh phượng tiên kim đảng, không dùng tới bảo thuật, trực tiếp lấy binh khí công kích.","phamCap":"Không rõ"}]},"capNhatToi":"@c1204","nguon":["@c1204"]},{"id":"than-kiem-cua-vuong-hi","name":"Thần kiếm của Vương Hi","cn":"","aliases":[],"category":"than-khi","categoryLabel":"Thần binh","phamCap":"Không rõ","soHuu":["Vương Hi"],"chuHienThoi":"Vương Hi","trangThai":"Hoàn hảo","vatLieu":"Chứa tiên kim","uyLuc":"Là thần kiếm tuyệt thế sắc bén và có thể dẫn động Bình Loạn Quyết.","dacDiem":"Dâng lên ráng lành khi được rút ra.","congNang":["Làm vật dẫn để Vương Hi thi triển Bình Loạn Quyết."],"chuSoHuu":[{"ten":"Vương Hi","tuChuong":"@c1204","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"blurb":"Thần kiếm chứa tiên kim do Vương Hi sử dụng. Nó tuyệt thế sắc bén, tỏa ráng lành và có thể làm vật dẫn cho Bình Loạn Quyết.","detail":"Vương Hi rút thần kiếm khi ngăn Thạch Hạo tiếp cận Dẫn Hồn Liên. Thạch Hạo dùng ngón tay đánh trúng thân kiếm, khiến binh khí rung động.","tabs":{"tienTrinh":[{"chuong":"@c1204","loai":"dùng","importance":"normal","giaiDoan":"Chặn Thạch Hạo","text":"Vương Hi dùng thần kiếm chứa tiên kim để thi triển Bình Loạn Quyết tấn công Thạch Hạo.","anchor":"Vương Hi rút ra một thanh kiếm thần, lấy ẩn chứa tiên kim, tuyệt thế sắc bén, dâng lên ráng lành.","phamCap":"Không rõ"}]},"capNhatToi":"@c1204","nguon":["@c1204"]},{"id":"phuong-hoang-thao","name":"Phượng Hoàng thảo","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Thần dược","phamCap":"Thần dược","soHuu":["Thiếu niên thanh tú Tiên Viện đoạt Phượng Hoàng thảo"],"trangThai":"Đã bị đoạt","blurb":"Phượng Hoàng thảo là một cây thần dược xuất hiện giữa khu vực hỗn chiến. Nó bị thiếu niên thanh tú của Tiên Viện đoạt lấy sau khi người này đánh lui đối thủ, trước khi Thạch Hạo tới.","detail":"Trong một cuộc hỗn chiến, Phượng Hoàng thảo trở thành mục tiêu tranh đoạt. Thiếu niên thanh tú của Tiên Viện trở nên cuồng dã khi giao chiến, đánh lui đối thủ và đoạt được cây thần dược này trước lúc Thạch Hạo xuất hiện. @c1206","chuHienThoi":"Thiếu niên thanh tú Tiên Viện đoạt Phượng Hoàng thảo","chuSoHuu":[{"ten":"Thiếu niên thanh tú Tiên Viện đoạt Phượng Hoàng thảo","tuChuong":"@c1206","denChuong":"","cachCoDuoc":"Đánh lui đối thủ và đoạt lấy","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1206","loai":"đổi chủ","importance":"major","giaiDoan":"Bị đoạt","phamCap":"Thần dược","text":"Phượng Hoàng thảo bị thiếu niên thanh tú của Tiên Viện đoạt sau khi hắn đánh lui đối thủ.","anchor":"đẩy lùi địch thủ, cướp đi Phượng Hoàng thảo"}]},"capNhatToi":"@c1206","nguon":["@c1206"],"dacDiem":"Một cây thần dược."},{"id":"nghiet-long-duoc","name":"Nghiệt Long dược","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Thần dược","phamCap":"Thần dược cao cấp","soHuu":["Thập Quan Vương"],"trangThai":"Đã bị thu lấy","blurb":"Nghiệt Long dược là thần dược cao cấp mang hình dáng Nghiệt Long màu tím, có linh tính và biết độn thổ. Sau khi bị phong tỏa giữa cuộc hỗn chiến, nó được Thập Quan Vương phá vòng vây đoạt lấy để chuẩn bị rèn luyện song quyền.","detail":"Nghiệt Long dược có hình dáng Nghiệt Long màu tím, mang sáu bảy lá giống vuốt rồng, đồng thời có linh tính và khả năng độn thổ. Nó từng bị trận pháp phong tỏa giữa cuộc hỗn chiến, sau đó được Thập Quan Vương phá vòng vây bắt giữ, dự định phối hợp với Chân Long bảo thuật để rèn luyện song quyền. @c1206","phanLoaiPhu":"Thần dược hình rồng","hinhDang":"Nghiệt Long màu tím với sáu bảy lá giống vuốt rồng","dacDiem":"Mang hình dáng Nghiệt Long màu tím, có sáu bảy lá giống vuốt rồng, có linh tính và biết độn thổ.","congNang":["Có thể được Thập Quan Vương dùng phối hợp với Chân Long bảo thuật để rèn luyện song quyền. @c1206"],"chuHienThoi":"Thập Quan Vương","chuSoHuu":[{"ten":"Thập Quan Vương","tuChuong":"@c1206","denChuong":"","cachCoDuoc":"Phá vòng vây và bắt lấy giữa cuộc hỗn chiến","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1206","loai":"đổi chủ","importance":"major","giaiDoan":"Thuộc về Thập Quan Vương","phamCap":"Thần dược cao cấp","text":"Thập Quan Vương phá vòng vây và bắt được Nghiệt Long dược để chuẩn bị rèn luyện song quyền.","anchor":"Thập Quan Vương đắc thủ, một phát bắt được nghiệt Long dược"}]},"capNhatToi":"@c1206","nguon":["@c1206"]},{"id":"mau-vang-cua-doc-co-van","name":"Máu vàng của Độc Cô Vân","cn":"","category":"nguyen-lieu","categoryLabel":"Huyết mạch và vật dẫn","phamCap":"Không rõ","soHuu":["Độc Cô Vân"],"trangThai":"Đã nhỏ lên vách đá","blurb":"Máu vàng từ Độc Cô Vân được dùng làm vật dẫn trên vách đá cổ, trực tiếp kích phát dị biến phía sau hình khắc cánh cửa.","detail":"Độc Cô Vân cắn ngón giữa rồi nhỏ dòng máu màu vàng óng lên vách đá. Ngay sau đó, tiếng gào cổ xưa vang lên, bóng người hung bạo phía sau cánh cửa tiến lại và đưa một bàn tay đầy lông ra ngoài.","phanLoaiPhu":"Máu huyết mạch","hinhDang":"Dòng máu màu vàng óng","nguonGoc":"Độc Cô Vân, hậu nhân người bảo vệ","dacDiem":"Có thể kích phát phản ứng từ hình khắc cánh cửa và sinh vật phía sau vách đá.","congNang":["Kích phát dị biến ở vách đá, khiến sinh vật sau cánh cửa tiến tới."],"chuHienThoi":"Độc Cô Vân","chuSoHuu":[{"ten":"Độc Cô Vân","tuChuong":"@c1207","denChuong":"","cachCoDuoc":"Máu thuộc huyết mạch của chính mình","trangThai":"Đã sử dụng một phần trên vách đá"}],"capNhatToi":"@c1207","tabs":{"tienTrinh":[{"chuong":"@c1207","loai":"dùng","importance":"normal","giaiDoan":"Kích phát cửa đá","phamCap":"Không rõ","text":"Độc Cô Vân nhỏ máu vàng lên vách đá, khiến tiếng gào vang lên và sinh vật phía sau cánh cửa đưa tay ra ngoài.","anchor":"hướng về cái kia vách đá nhỏ xuống một ít dòng máu màu vàng óng"}]},"nguon":["@c1207"]},{"id":"cua-da-khac-tren-vach-da","name":"Cửa đá khắc trên vách đá","cn":"","aliases":[],"category":"khac","categoryLabel":"Cổng phong ấn","phamCap":"Chưa rõ","soHuu":[],"trangThai":"Đã được kích hoạt @c1208","blurb":"Cửa đá vốn tồn tại dưới dạng hình khắc trên vách đá, nhưng có thể hóa thành một đường thông hành thực sự sau khi được kích hoạt. Nó từng ngăn chặn đòn đánh của cây non Thế Giới Thụ và mở lối cho sinh linh lông đỏ vượt sang bên này.","detail":"Sau khi hấp thu máu vàng của Độc Cô Vân và được pháp ấn kích hoạt, các đường khắc cùng phù văn trên cửa đá phát sáng, khiến toàn bộ cánh cửa trở nên gần như trong suốt. Cửa đá sau đó biến thành đường thông hành, cho phép sinh linh lông đỏ ở bên trong vách đá vượt qua, đồng thời trực tiếp chặn đòn đánh từ cây non Thế Giới Thụ. @c1208","phanLoaiPhu":"Cổng phong ấn","hinhDang":"Cánh cửa được khắc trên vách đá","congNang":["Biến thành đường thông hành sau khi hấp thu máu vàng và được pháp ấn kích hoạt. @c1208","Chặn đòn đánh từ cây non Thế Giới Thụ. @c1208","Cho phép sinh linh bên trong vách đá vượt sang bên này. @c1208"],"uyLuc":"Có thể trực tiếp chặn đòn đánh của cây non Thế Giới Thụ. @c1208","dacDiem":"Tồn tại dưới dạng hình khắc trên vách đá; sau khi hấp thu máu vàng, các đường khắc và phù văn phát sáng, khiến cửa đá trở nên gần như trong suốt. @c1208","capNhatToi":"@c1208","tabs":{"tienTrinh":[{"chuong":"@c1208","loai":"khai phong","importance":"major","giaiDoan":"Mở đường thông hành","text":"Cửa đá hấp thu máu vàng, phát sáng và mở đường cho sinh linh lông đỏ vượt qua.","anchor":"Cái kia vách đá đang phát sáng, mặt trên hiện lên rất nhiều phù văn, đặc biệt là dòng máu vàng chảy xuôi","phamCap":"Chưa rõ"}]},"nguon":["@c1208"]},{"id":"than-soc-cua-sinh-linh-long-do","name":"Thần sóc của sinh linh lông đỏ","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Đạo khí","phanLoaiPhu":"Thần sóc","phamCap":"Đạo khí","soHuu":["Sinh linh lông đỏ mắt bạc trong vách đá"],"chuHienThoi":"Sinh linh lông đỏ mắt bạc trong vách đá","trangThai":"Đang được sử dụng @c1209","blurb":"Đạo khí hình thần sóc của sinh linh lông đỏ, nặng tựa trường mâu nhưng có thế công hung mãnh hơn. Nó đối đầu trực diện với thiên mâu của Độc Cô Vân.","detail":"Thần sóc mang theo thần thông và đại đạo thần âm khi va chạm, làm hư không vỡ nát và khiến những tu sĩ ở xa bị chấn thương.","uyLuc":"Va chạm với thiên mâu làm vỡ hư không và chấn thương những tu sĩ quan chiến ở xa. @c1209","dacDiem":"Là Đạo khí đồng hành cùng người sử dụng trưởng thành. @c1209","congNang":["Phối hợp với thần thông và phát ra đại đạo thần âm khi giao chiến. @c1209"],"chuSoHuu":[{"ten":"Sinh linh lông đỏ mắt bạc trong vách đá","tuChuong":"@c1209","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1209","loai":"dùng","importance":"normal","giaiDoan":"Đối đầu thiên mâu","text":"Sinh linh lông đỏ triệu thần sóc và dùng nó đối đầu thiên mâu của Độc Cô Vân.","anchor":"ở cái kia lông đỏ sinh linh trong tay, xuất hiện một cây thần sóc","phamCap":"Đạo khí"}]},"capNhatToi":"@c1209","nguon":["@c1209"]},{"id":"thien-mau-cua-doc-co-van","name":"Thiên mâu của Độc Cô Vân","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Đạo khí","phanLoaiPhu":"Thiên mâu","phamCap":"Đạo khí","soHuu":["Độc Cô Vân"],"chuHienThoi":"Độc Cô Vân","trangThai":"Đang được sử dụng @c1209","blurb":"Đạo khí hình thiên mâu do Độc Cô Vân sử dụng. Binh khí này đối đầu trực diện với thần sóc của sinh linh lông đỏ.","detail":"Khi được thúc giục, lưỡi binh tăng vọt hàng trăm trượng, mang theo thần thông và đại đạo thần âm nghiền nát hư không.","uyLuc":"Phối hợp với thần thông để nghiền nát hư không trong cuộc va chạm với thần sóc. @c1209","dacDiem":"Là Đạo khí đồng hành cùng người sử dụng trưởng thành. @c1209","congNang":["Lưỡi binh có thể tăng vọt hàng trăm trượng khi giao chiến. @c1209","Mang theo thần thông và đại đạo thần âm trong lúc va chạm. @c1209"],"chuSoHuu":[{"ten":"Độc Cô Vân","tuChuong":"@c1209","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1209","loai":"dùng","importance":"normal","giaiDoan":"Đối đầu thần sóc","text":"Độc Cô Vân triệu thiên mâu và dùng nó giao chiến quyết liệt với sinh linh lông đỏ.","anchor":"Thủ Hộ giả hậu nhân Độc Cô Vân trong tay xuất hiện một cây thiên mâu","phamCap":"Đạo khí"}]},"capNhatToi":"@c1209","nguon":["@c1209"]},{"id":"chat-long-phong-an-cua-bat-huu-gia","name":"Chất lỏng phong ấn của Bất Hủ giả","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm phong ấn","phanLoaiPhu":"Chất lỏng phong ấn","phamCap":"Do Bất Hủ giả tế luyện","soHuu":[],"trangThai":"Đã đông kết thành các mảnh và bong khỏi sinh linh lông đỏ @c1209","blurb":"Chất lỏng do Bất Hủ giả tế luyện, từng bao bọc và phong ấn sinh linh lông đỏ. Sau khi hắn thoát vây, vật chất này đông kết thành những mảnh bong khỏi cơ thể.","detail":"Mạc Đạo xác định vật chất này có khả năng phong ấn vạn vật qua năm tháng dài đằng đẵng và là nguyên nhân giúp sinh linh lông đỏ duy trì trạng thái trẻ tuổi tới hiện đời.","nguonGoc":"Do Bất Hủ giả tế luyện. @c1209","uyLuc":"Có thể duy trì vật được phong ấn qua năm tháng dài đằng đẵng. @c1209","dacDiem":"Sau thời gian dài phong ấn, chất lỏng đông kết thành từng mảnh vật chất thần thánh. @c1209","congNang":["Phong ấn vạn vật và duy trì chúng qua thời gian dài. @c1209","Giúp sinh linh bị phong ấn duy trì trạng thái thanh niên. @c1209"],"tabs":{"tienTrinh":[{"chuong":"@c1209","loai":"xuất hiện","importance":"normal","giaiDoan":"Bong khỏi vật bị phong ấn","text":"Những mảnh vật chất đông kết bong khỏi sinh linh lông đỏ và được Mạc Đạo nhận diện là chất lỏng do Bất Hủ giả tế luyện.","anchor":"Đó là Bất Hủ giả tế luyện ra chất lỏng, có thể phong ấn vạn vật bất hủ","phamCap":"Do Bất Hủ giả tế luyện"}]},"capNhatToi":"@c1209","nguon":["@c1209"]},{"id":"thien-loai-tai-ngu-ma-phong","name":"Thiên loại tại Ngũ Ma phong","cn":"","aliases":[],"category":"khac","categoryLabel":"Đạo chủng","phanLoaiPhu":"Thiên loại","phamCap":"Thiên loại","soHuu":[],"trangThai":"Chưa xuất thế rõ ràng @c1209","blurb":"Một viên đạo chủng phi thường được cho là nằm tại Ngũ Ma phong và có thể là mục tiêu khiến hoàng tộc dị vực tới đây. Nó từng khiến một bá chủ Bất Hủ tiếc nuối vì bỏ lỡ.","detail":"Mạc Đạo cho biết nếu dùng thiên loại này thành đạo thì thành tựu có thể đạt tới mức khó tưởng tượng. Thạch Hạo liên hệ nó với truyền thuyết Ngũ Ma phong thiên loại.","uyLuc":"Có thể khiến thành tựu của người dùng nó thành đạo trở nên đáng sợ hơn. @c1209","dacDiem":"Từng được một bá chủ Bất Hủ đánh giá cao và tiếc nuối vì bỏ lỡ. @c1209","congNang":["Có thể được dùng làm đạo chủng để thành đạo. @c1209"],"tabs":{"tienTrinh":[{"chuong":"@c1209","loai":"xuất hiện","importance":"normal","giaiDoan":"Giá trị được hé lộ","text":"Mạc Đạo tiết lộ thiên loại tại đây từng khiến một bá chủ Bất Hủ tiếc nuối và có thể đem lại thành tựu khó tưởng tượng cho người dùng nó thành đạo.","anchor":"nếu như lấy nó thành đạo, thành tựu sẽ càng kinh khủng, không thể nào tưởng tượng được","phamCap":"Thiên loại"}]},"capNhatToi":"@c1209","nguon":["@c1209"]},{"id":"thien-loai-trong-bao-binh","name":"Thiên loại trong bảo bình","cn":"","aliases":[],"category":"khac","categoryLabel":"Thiên loại","phamCap":"Không rõ","soHuu":[],"trangThai":"Nằm trong thế giới sau vách đá","blurb":"Một viên thiên loại được cất trong bảo bình phía sau vách đá, có liên hệ trực tiếp với phong ấn cao thủ dị vực.","detail":"Theo sinh vật lông đỏ, chỉ cần dịch chuyển viên thiên loại này là có thể giải phong các cao thủ trong bộ tộc nó. Đây cũng là kỳ vật mà một bá chủ vô thượng từng tiếc nuối vì không lấy được.","phanLoaiPhu":"Thiên loại","hinhDang":"Viên thiên loại nằm trong bảo bình","nguonGoc":"Thế giới sau vách đá","uyLuc":"Có thể tác động đến phong ấn đang giam giữ các cao thủ thuộc bộ tộc sinh vật lông đỏ.","dacDiem":"Là kỳ vật từng khiến bá chủ vô thượng tiếc nuối vì không đạt được.","congNang":["Dịch chuyển thiên loại để giải phong cao thủ của bộ tộc sinh vật lông đỏ @c1210"],"capNhatToi":"@c1210","tabs":{"tienTrinh":[{"chuong":"@c1210","loai":"xuất hiện","importance":"normal","giaiDoan":"Được tiết lộ sau vách đá","text":"Sinh vật lông đỏ tiết lộ thiên loại trong bảo bình có thể được dịch chuyển để giải phong cao thủ bộ tộc nó.","anchor":"có một viên thiên loại, chỉ cần dịch chuyển nó, liền có thể cứu ra bộ tộc ta những cao thủ","phamCap":"Không rõ"}]},"nguon":["@c1210"]},{"id":"bao-huyet-giai-phong","name":"Bảo huyết giải phong","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Vật liệu nghi thức","phamCap":"Không rõ","soHuu":["Sinh vật lông đỏ"],"trangThai":"Đang được thu thập","blurb":"Các loại bảo huyết được sinh vật lông đỏ thu thập để phục vụ việc giải phong cao thủ bộ tộc.","detail":"Sinh vật lông đỏ yêu cầu kim huyết của Độc Cô Vân và lấy máu Vương Hi để nếm thử. Nó xác nhận máu của Vương Hi có thể dùng làm một loại bảo huyết giải phong.","phanLoaiPhu":"Vật liệu giải phong","nguonGoc":"Máu của những thiên kiêu có huyết mạch hoặc khí tức đặc biệt","congNang":["Làm vật liệu cho nghi thức giải phong @c1210"],"chuHienThoi":"Sinh vật lông đỏ","capNhatToi":"@c1210","chuSoHuu":[{"ten":"Sinh vật lông đỏ","tuChuong":"@c1210","denChuong":"","cachCoDuoc":"Lấy máu Vương Hi và yêu cầu kim huyết của Độc Cô Vân","trangThai":"Đang thu thập"}],"tabs":{"tienTrinh":[{"chuong":"@c1210","loai":"xuất hiện","importance":"normal","giaiDoan":"Xác nhận vật liệu giải phong","text":"Sinh vật lông đỏ nếm máu Vương Hi và xác nhận nó có thể dùng làm bảo huyết giải phong.","anchor":"có thể cũng có thể đem làm giải phong, xem như là một loại bảo huyết","phamCap":"Không rõ"}]},"nguon":["@c1210"]},{"id":"tam-chan-ngu-sac","name":"Tấm chắn ngũ sắc","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Cổ thuẫn","phanLoaiPhu":"Bảo cụ phòng ngự","phamCap":"Bảo cụ tiên kim","soHuu":["Sinh linh lông đỏ"],"trangThai":"Bị chém mở và mất tinh hoa","blurb":"Tấm chắn ngũ sắc là pháp bảo bằng tiên kim, từng bảo vệ mi tâm của sinh linh lông đỏ. Nó tự bay ra ngăn Đại La tiên kiếm thai nhưng bị chém mở, sau đó tinh hoa bị kiếm thai hấp thu.","detail":"Tấm chắn ngũ sắc được đúc bằng tiên kim và nằm tại mi tâm của sinh linh lông đỏ. Khi Đại La tiên kiếm thai chém tới, tấm chắn tự bay ra bảo vệ mi tâm và cản kiếm, song cuối cùng vẫn bị chém mở; phần tinh hoa của nó sau đó bị kiếm thai hấp thu. @c1211","vatLieu":"Tiên kim","congNang":["Tự bay ra bảo vệ mi tâm và ngăn cản kiếm chém. @c1211"],"dacDiem":"Có màu ngũ sắc và được đúc bằng tiên kim.","chuHienThoi":"Sinh linh lông đỏ","chuSoHuu":[{"ten":"Sinh linh lông đỏ","tuChuong":"@c1211","denChuong":"@c1211","cachCoDuoc":"Chưa rõ","trangThai":"Mất tinh hoa sau khi bị chém mở"}],"tabs":{"tienTrinh":[{"chuong":"@c1211","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị Đại La tiên kiếm thai chém phá","phamCap":"Bảo cụ tiên kim","text":"Tấm chắn ngũ sắc bảo vệ mi tâm sinh linh lông đỏ nhưng bị Đại La tiên kiếm thai chém mở và hấp thu tinh hoa.","anchor":"Tấm chắn ảm đạm, đốm lửa văng khắp nơi, cuối cùng bị mở ra"}]},"capNhatToi":"@c1211","nguon":["@c1211"]},{"id":"dai-dao-bao-binh","name":"Đại Đạo Bảo Bình","cn":"","category":"phap-bao","categoryLabel":"Bảo bình đá kiêm lò phong ấn","phamCap":"Không rõ","soHuu":[],"trangThai":"Đang phong ấn sinh linh dị vực","blurb":"Đại Đạo Bảo Bình là bảo bình bằng đá lớn như núi, có từ thời Tiên cổ và nằm giữa quần sơn. Pháp bảo vừa là lò luyện, vừa là trung tâm phong ấn Hoàng tộc dị vực; kim huyết của Độc Cô Vân từng kích hoạt biến hóa của bảo bình cùng cơ cấu quần sơn.","detail":"Có từ thời Tiên cổ, Đại Đạo Bảo Bình được bố trí giữa quần sơn, dùng một bình nhỏ chứa thiên loại làm nút miệng. Đây là trung tâm của cơ cấu phong ấn và luyện hóa các sinh linh dị vực, trong đó có Hoàng tộc dị vực. Khi tiếp xúc với kim huyết của Độc Cô Vân, bảo bình cùng cơ cấu quần sơn phát sinh biến hóa và được kích hoạt. @c1212","phanLoaiPhu":"Bảo bình kiêm lò phong ấn","hinhDang":"Bảo bình bằng đá lớn như núi","nguonGoc":"Có từ thời Tiên cổ","dacDiem":"Bảo bình bằng đá lớn như núi, nằm giữa quần sơn và dùng một bình nhỏ chứa thiên loại làm nút miệng; đồng thời là lò luyện và trung tâm của cơ cấu phong ấn.","congNang":["Phong ấn các sinh linh dị vực, bao gồm Hoàng tộc dị vực. @c1212","Luyện hóa các sinh linh dị vực từ thời Tiên cổ."],"tabs":{"tienTrinh":[{"chuong":"@c1212","loai":"khai phong","importance":"major","giaiDoan":"Kim huyết kích hoạt","text":"Đại Đạo Bảo Bình được phát hiện là trung tâm phong ấn Hoàng tộc dị vực và bị kim huyết của Độc Cô Vân kích hoạt.","anchor":"Nó nếu là bảo bình, lại là lò lớn, phong ấn Tiên cổ dị vực","phamCap":"Không rõ"}]},"dinhDanh":"goc","capNhatToi":"@c1212","nguon":["@c1212"]},{"id":"binh-nho-chua-thien-loai","name":"Bình nhỏ chứa thiên loại","cn":"","category":"phap-bao","categoryLabel":"Nút phong ấn","phamCap":"Không rõ","soHuu":[],"trangThai":"Đang nằm tại miệng Đại Đạo Bảo Bình","blurb":"Bình nhỏ được đặt tại miệng Đại Đạo Bảo Bình, bên trong chứa thiên loại. Pháp bảo này là bộ phận then chốt duy trì cơ cấu phong ấn.","detail":"Bình nhỏ nằm ở miệng Đại Đạo Bảo Bình và đóng vai trò như nút miệng của bảo bình. Tới mốc khai phong, nó được xác nhận chứa thiên loại, đồng thời giữ vai trò mấu chốt trong việc duy trì phong ấn. @c1212","phanLoaiPhu":"Nút miệng bảo bình","dacDiem":"Chứa thiên loại, được đặt tại miệng Đại Đạo Bảo Bình và là mấu chốt duy trì phong ấn.","congNang":["Chứa thiên loại. @c1212","Làm nút miệng Đại Đạo Bảo Bình và duy trì cơ cấu phong ấn. @c1212"],"tabs":{"tienTrinh":[{"chuong":"@c1212","loai":"khai phong","importance":"major","giaiDoan":"Lộ mấu chốt phong ấn","text":"Bình nhỏ tại miệng Đại Đạo Bảo Bình được xác nhận chứa thiên loại và giữ vai trò mấu chốt trong phong ấn.","anchor":"Miệng bình nút lọ là một cái bình nhỏ","phamCap":"Không rõ"}]},"dinhDanh":"goc","capNhatToi":"@c1212","nguon":["@c1212"]},{"id":"dau-an-tien-binh-cua-dai-dao-bao-binh","name":"Dấu ấn Tiên Binh của Đại Đạo Bảo Bình","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Dấu ấn binh khí","phamCap":"Tiên Binh dấu ấn","soHuu":[],"trangThai":"Do Đại Đạo Bảo Bình ngưng tụ","blurb":"Dấu ấn binh khí mông lung mang hình thái gần như đại kích hoặc chiến mâu, được Đại Đạo Bảo Bình ngưng tụ để trấn áp sinh vật cổ.","detail":"Dấu ấn phát thần quang quét ngang thiên địa và đánh rơi hàng loạt sinh vật mạnh đang tràn ngập quần sơn.","phanLoaiPhu":"Dấu ấn binh khí","hinhDang":"Mông lung như đại kích hoặc chiến mâu","nguonGoc":"Do Đại Đạo Bảo Bình ngưng tụ","uyLuc":"Một đòn thần quang đánh rơi nhiều sinh vật cổ mạnh mẽ.","dacDiem":"Không phải Tiên Binh nguyên bản mà là dấu ấn binh khí do bảo bình tạo ra.","congNang":["Phát thần quang quét ngang thiên địa và trấn áp hàng loạt sinh vật cổ."],"capNhatToi":"@c1213","tabs":{"tienTrinh":[{"chuong":"@c1213","loai":"dùng","importance":"normal","giaiDoan":"Trấn áp sinh vật cổ","text":"Dấu ấn Tiên Binh phát thần quang quét ngang và đánh rơi hàng loạt sinh vật cổ trong quần sơn.","phamCap":"Tiên Binh dấu ấn","anchor":"thần quang quét ra, đem đầy trời sinh linh mạnh mẽ đánh rơi"}]},"nguon":["@c1213"]},{"id":"dau-an-tien-kiem-cua-dai-dao-bao-binh","name":"Dấu ấn tiên kiếm của Đại Đạo Bảo Bình","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Dấu ấn binh khí","phamCap":"Tiên kiếm dấu ấn","soHuu":[],"trangThai":"Do Đại Đạo Bảo Bình ngưng tụ","blurb":"Dấu ấn tiên kiếm được Đại Đạo Bảo Bình ngưng tụ để tiếp tục chém giết các sinh vật cổ trong quần sơn.","detail":"Tiên kiếm lao xuyên hư không nhanh như chớp và chém giết địch thủ trên phạm vi rộng khắp mười phương.","phanLoaiPhu":"Dấu ấn binh khí","hinhDang":"Một khẩu tiên kiếm","nguonGoc":"Do Đại Đạo Bảo Bình ngưng tụ","uyLuc":"Có thể lao qua hư không và chém giết địch thủ trên phạm vi rộng.","dacDiem":"Di chuyển trong hư không giống như một tia chớp.","congNang":["Bay xuyên hư không và chém giết diện rộng."],"capNhatToi":"@c1213","tabs":{"tienTrinh":[{"chuong":"@c1213","loai":"dùng","importance":"normal","giaiDoan":"Quét sạch địch thủ","text":"Dấu ấn tiên kiếm lao qua hư không như chớp và chém giết các sinh vật cổ khắp mười phương.","phamCap":"Tiên kiếm dấu ấn","anchor":"làm một khẩu tiên kiếm, giống như là một tia chớp ở trong hư không bay vụt"}]},"nguon":["@c1213"]},{"id":"mau-can-hanh","name":"Mẫu Căn Hành","cn":"","aliases":["Mẫu Căn Hành của Mẫu Sào dị vực"],"category":"khac","categoryLabel":"Cổ vật sống","phamCap":"Không rõ","soHuu":[],"trangThai":"Bị thiêu hủy","blurb":"Mẫu Căn Hành là phần rễ khổng lồ còn lại của Mẫu Sào dị vực, nối liền toàn bộ quần sơn và từng sinh dưỡng vô tận sinh linh. Nó từng thoát khỏi lòng đất, quấn lấy Đại Đạo Bảo Bình để tiếp nhận bảo huyết, hỗ trợ sinh linh dị vực bị phong ấn tái sinh, trước khi bị tàn niệm hình người thiêu hủy.","detail":"Là phần còn lại của Mẫu Sào dị vực, Mẫu Căn Hành có quy mô khổng lồ, nối liền toàn bộ quần sơn và mang năng lực sinh dưỡng vô tận sinh linh. Tại @c1213, nó thoát khỏi lòng đất rồi quấn lấy Đại Đạo Bảo Bình, tìm cách tiếp nhận bảo huyết nhằm tạo điều kiện cho Bất Hủ bị phong ấn tái sinh. Sau đó, tàn niệm hình người dùng kiếm cùng ánh lửa thiêu hủy Mẫu Căn Hành.","phanLoaiPhu":"Cơ thể mẹ","hinhDang":"Hệ rễ khổng lồ nối liền nhiều ngọn núi","nguonGoc":"Phần còn lại của Mẫu Sào dị vực","uyLuc":"Có thể quấn lấy Đại Đạo Bảo Bình và sinh dưỡng vô tận sinh linh.","dacDiem":"Phần rễ khổng lồ còn lại của Mẫu Sào dị vực, nối liền toàn bộ quần sơn và có thể tiếp nhận bảo huyết để tạo điều kiện cho sinh linh bị phong ấn tái sinh.","congNang":["Sinh dưỡng vô tận sinh linh.","Tiếp nhận bảo huyết để hỗ trợ quá trình tái sinh của sinh linh dị vực bị phong ấn.","Thoát khỏi lòng đất và quấn lấy Đại Đạo Bảo Bình. @c1213"],"capNhatToi":"@c1213","tabs":{"tienTrinh":[{"chuong":"@c1213","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Thoát đất rồi bị hủy","text":"Mẫu Căn Hành thoát khỏi lòng đất, quấn lấy Đại Đạo Bảo Bình nhưng cuối cùng bị tàn niệm hình người dùng kiếm và ánh lửa thiêu hủy.","phamCap":"Không rõ","anchor":"Cổ đại thì, nó từng dựng dục ra vô tận sinh linh, là một cái Mẫu Sào"}]},"nguon":["@c1213"]},{"id":"thien-loai","name":"Thiên loại","cn":"","aliases":[],"category":"khac","categoryLabel":"Hạt giống bí ẩn","phamCap":"Không rõ","soHuu":[],"trangThai":"Đang được nuôi dưỡng","blurb":"Thiên loại là một hạt giống bí ẩn được nuôi dưỡng bằng sinh linh dị vực để dần thành thục. Tàn niệm trên Đại Đạo Bảo Bình cho biết khi thiên loại đạt tới đại viên mãn, sẽ có người đến thu hoạch, nhưng thân phận người đó và công dụng cuối cùng vẫn chưa được tiết lộ.","detail":"Nguồn gốc của thiên loại không rõ. Nó nằm trong một bố cục nuôi dưỡng kéo dài nhiều năm tháng, lấy sinh linh dị vực, kể cả sinh linh thuộc Hoàng tộc, làm chất dinh dưỡng để tiến tới thành thục. Tàn niệm trên Đại Đạo Bảo Bình xác nhận thiên loại cần đạt tới đại viên mãn và trong tương lai sẽ có người đến thu hoạch, song không cho biết ai là người hưởng lợi hay thiên loại sẽ được dùng vào việc gì sau cùng. @c1213","phanLoaiPhu":"Hạt giống","nguonGoc":"Không rõ","dacDiem":"Hạt giống bí ẩn dùng sinh linh dị vực làm chất dinh dưỡng, được nuôi dưỡng để tiến tới đại viên mãn rồi chờ người đến thu hoạch.","congNang":["Hấp thu sinh linh dị vực làm chất dinh dưỡng để thành thục và tiến tới đại viên mãn. @c1213"],"capNhatToi":"@c1213","tabs":{"tienTrinh":[{"chuong":"@c1213","loai":"khai phong","importance":"major","giaiDoan":"Hé lộ mục đích nuôi dưỡng","text":"Tàn niệm xác nhận sinh linh dị vực là chất dinh dưỡng giúp thiên loại thành thục và sẽ có người tới thu hoạch nó.","phamCap":"Không rõ","anchor":"chỉ có thể trở thành là thiên loại chất dinh dưỡng, để nó thành thục"}]},"nguon":["@c1213"]},{"id":"chuan-the-gioi-thu-hoang-kim","name":"Chuẩn Thế Giới Thụ hoàng kim","cn":"","aliases":["Hoàng kim cổ thụ"],"category":"khac","categoryLabel":"Thần thụ","phamCap":"Chuẩn Thế Giới Thụ","soHuu":[],"trangThai":"Đang tiếp tục tiến hóa","blurb":"Chuẩn Thế Giới Thụ hoàng kim là một cổ thụ có khả năng hấp thu Ngũ hành tinh khí để tiếp tục tiến hóa về hướng Thế Giới Thụ. Sau khi tiến hóa sâu hơn, nó tự nhổ rễ và rời khỏi đại lục Ngũ hành.","detail":"Mỗi chiếc lá của cổ thụ nâng hình ảnh Nhật, Nguyệt và sao trời, đồng thời tỏa ra sức sống kinh người. Tại đại lục Ngũ hành, nó hấp thu Ngũ hành tinh khí để tiến hóa sâu hơn về hướng Thế Giới Thụ, sau đó tự nhổ rễ bay đi; những vùng đất được nó lựa chọn được các trưởng lão xem là thánh thổ có cơ duyên. @c1214","phanLoaiPhu":"Thần thụ tiến hóa","hinhDang":"Cổ thụ màu hoàng kim, lá nâng Nhật Nguyệt Sao trời","uyLuc":"Có thể hấp thu Ngũ hành tinh khí để tiếp tục tiến hóa sâu hơn về hướng Thế Giới Thụ. @c1214","dacDiem":"Hoàng kim cổ thụ có mỗi chiếc lá nâng hình ảnh Nhật, Nguyệt và sao trời, tỏa ra sức sống kinh người; có thể tự nhổ rễ bay đi.","congNang":["Hấp thu Ngũ hành tinh khí để tiến hóa sâu hơn về hướng Thế Giới Thụ. @c1214","Tự nhổ rễ và bay tới những vùng đất thần bí. @c1214"],"capNhatToi":"@c1214","tabs":{"tienTrinh":[{"chuong":"@c1214","loai":"nâng cấp","importance":"major","giaiDoan":"Tiến hóa sâu hơn","text":"Chuẩn Thế Giới Thụ hoàng kim hấp thu Ngũ hành tinh khí, tiến hóa sâu hơn rồi nhổ rễ rời đại lục Ngũ hành.","anchor":"lần này ở chỗ này vặt hái Ngũ hành tinh khí, để nó được cấp độ càng sâu tiến hóa"}]},"nguon":["@c1214"]},{"id":"dao-tac-hat-giong","name":"Đạo tắc hạt giống","cn":"","aliases":[],"category":"khac","categoryLabel":"Đạo chủng","phamCap":"Không rõ","soHuu":[],"trangThai":"Đã bị đoàn thiên tài hái sạch","blurb":"Những trái cây do đạo tắc biến thành, mọc trên một cây trong vùng pháp tắc. Hàng chục trái nhanh chóng bị đoàn thiên tài thu lấy.","detail":"Mỗi trái là một hạt giống do đạo tắc biến thành. Cây mang chúng được phát hiện tại vùng do quy tắc thế giới xây dựng.","hinhDang":"Trái cây do đạo tắc biến thành","dacDiem":"Một cây có hàng chục trái đạo tắc.","congNang":["Dùng làm đạo chủng cho người tu hành."],"capNhatToi":"@c1214","tabs":{"tienTrinh":[{"chuong":"@c1214","loai":"xuất hiện","importance":"normal","giaiDoan":"Được phát hiện và thu hái","text":"Đoàn thiên tài phát hiện hàng chục trái cây do đạo tắc biến thành rồi nhanh chóng hái sạch.","anchor":"mọi người cấp tốc phóng đi, đem trái cây hái mà quang."}]},"nguon":["@c1214"]},{"id":"van-dao-thu","name":"Vạn Đạo Thụ","cn":"","aliases":[],"category":"khac","categoryLabel":"Thần thụ truyền thuyết","phamCap":"Thần thụ","soHuu":[],"trangThai":"Chỉ được nhắc trong truyền thuyết","blurb":"Thần thụ truyền thuyết có thể kết hơn vạn trái chứa các loại đại đạo. Giá trị của nó được đặt cạnh hạt giống mô hình vũ trụ và Cây non Thế Giới Thụ.","detail":"Mỗi trái của Vạn Đạo Thụ được mô tả là chứa một loại đại đạo. Cây trên Huyền Không đảo mới chỉ bị nghi là thần thụ này, chưa được xác nhận.","nguonGoc":"Thần thụ được lưu truyền trong lời kể về các hạt giống hoàn mỹ","uyLuc":"Có thể kết hơn vạn trái chứa nhiều loại đại đạo.","dacDiem":"Số trái theo truyền thuyết vượt hơn một vạn.","congNang":["Kết trái chứa các loại đại đạo."],"capNhatToi":"@c1214","tabs":{"tienTrinh":[{"chuong":"@c1214","loai":"nhắc tới","importance":"bridge","giaiDoan":"Truyền thuyết được nhắc lại","text":"Vạn Đạo Thụ được nhắc tới như thần thụ có hơn vạn trái chứa các loại đại đạo.","anchor":"có tới hơn vạn viên, chứa đựng các loại đại đạo"}]},"nguon":["@c1214"]},{"id":"cay-nghi-la-van-dao-thu-tren-huyen-khong-dao","name":"Cây nghi là Vạn Đạo Thụ trên Huyền Không đảo","cn":"","aliases":[],"category":"khac","categoryLabel":"Thần thụ chưa xác định","phamCap":"Không rõ","soHuu":[],"trangThai":"Chưa xác định danh tính","blurb":"Cây thần bí giống cây trà, mang ít nhất hàng nghìn trái đại đạo và ẩn hiện trong khe nứt hư không trên Huyền Không đảo. Nó mới chỉ được nghi là Vạn Đạo Thụ.","detail":"Cây dường như không được quy tắc thiên địa dung nạp nên liên tục ẩn hiện trong vết nứt hư không. Một cổ nhân bị xích được phát hiện ngồi gần cây.","hinhDang":"Giống một cây trà, mọc đầy trái đại đạo","dacDiem":"Mang ít nhất hàng nghìn trái và ẩn hiện trong khe nứt hư không.","congNang":["Kết số lượng lớn trái đại đạo."],"capNhatToi":"@c1214","tabs":{"tienTrinh":[{"chuong":"@c1214","loai":"xuất hiện","importance":"normal","giaiDoan":"Được đoàn hai viện phát hiện","text":"Cây giống cây trà mang hàng nghìn trái đại đạo được phát hiện trong khe nứt hư không trên Huyền Không đảo.","anchor":"Như là một cây cây trà, nhưng cũng mọc đầy đại đạo trái cây"}]},"nguon":["@c1214"]},{"id":"xich-sat-giam-sinh-linh-ben-van-dao-thu","name":"Xích sắt giam sinh linh bên Vạn Đạo Thụ","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm giam cầm","phanLoaiPhu":"Xích giam cầm","phamCap":"Không rõ","soHuu":[],"trangThai":"Đang giam giữ sinh linh","blurb":"Những dây xích đen xuyên qua xương thịt của sinh linh canh Vạn Đạo Thụ.","detail":"Xích đã tồn tại rất lâu và rỉ sét dù bị nghi chứa lượng lớn hắc ám Tiên kim. Chúng xuyên xương, mọc sâu vào thịt và giữ sinh linh ở gần Vạn Đạo Thụ.","vatLieu":"Nghi pha lượng lớn hắc ám Tiên kim","hinhDang":"Xích sắt đen đã rỉ sét","congNang":["Xuyên thủng thân thể và giam cầm sinh linh canh Vạn Đạo Thụ tại @c1215."],"dacDiem":"Rỉ sét dù nghi được đúc với lượng lớn hắc ám Tiên kim.","capNhatToi":"@c1215","tabs":{"tienTrinh":[{"chuong":"@c1215","loai":"xuất hiện","importance":"normal","giaiDoan":"Lộ vật liệu","text":"Xích sắt xuyên thân người canh giữ được nhận định có thể chứa lượng lớn hắc ám Tiên kim nhưng vẫn bị rỉ sét.","anchor":"nghi tự lẫn lộn có lượng lớn hắc ám Tiên kim đúc thành, có thể như trước rỉ sắt","phamCap":"Không rõ"}]},"nguon":["@c1215"]},{"id":"bi-bao-tiep-can-huyen-khong-dao","name":"Bí bảo tiếp cận Huyền Không đảo","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bí bảo","phamCap":"Không rõ","soHuu":["Trưởng lão đoàn thám hiểm"],"trangThai":"hong","blurb":"Bí bảo được một trưởng lão dùng để thử sức vùng quy tắc trên Huyền Không đảo.","detail":"Khi tiến vào khu vực đảo trung tâm, bí bảo lặng lẽ bị sức mạnh nơi đây nung thành chất lỏng kim loại.","congNang":["Được dùng để thử tiếp cận khu vực trung tâm Huyền Không đảo tại @c1215."],"dacDiem":"Không chịu nổi quy tắc trên đảo và bị nung chảy hoàn toàn.","capNhatToi":"@c1215","tabs":{"tienTrinh":[{"chuong":"@c1215","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Bị nung chảy","text":"Bí bảo được đưa tới gần đảo trung tâm nhưng lập tức bị nung thành chất lỏng kim loại.","anchor":"kết quả cái này bảo cụ ở đảo trung tâm vô thanh vô tức hóa thành chất lỏng kim loại, bị nung nấu","phamCap":"Không rõ"}]},"nguon":["@c1215"]},{"id":"huyet-chung","name":"Huyết Chủng","cn":"","aliases":[],"category":"khac","categoryLabel":"Đạo chủng","phamCap":"Không rõ","soHuu":["Hơn mười thành viên đoàn thám hiểm"],"trangThai":"Đã được thu lấy một phần","blurb":"Đạo chủng do tinh huyết bất diệt của Tiên Thiên Thần Ma tử trận thông linh hóa thành.","detail":"Huyết Chủng hình thành giữa chiến trường cổ, hấp thu sát khí và cổ huyết. Hơn mười người thu được loại đạo chủng này, nhưng máu bạc và thi khí trong khu vực cũng gây nhiều cái chết.","nguonGoc":"Tinh huyết bất diệt của Tiên Thiên Thần Ma tử trận thông linh hóa thành","dacDiem":"Hấp thu sát khí và cổ huyết tại chiến trường cổ.","congNang":["Dùng làm đạo chủng cho người tìm được tại @c1215."],"capNhatToi":"@c1215","tabs":{"tienTrinh":[{"chuong":"@c1215","loai":"xuất hiện","importance":"normal","giaiDoan":"Được đoàn thám hiểm thu lấy","text":"Huyết Chủng được xác định là tinh huyết Tiên Thiên Thần Ma thông linh hóa thành và hơn mười người đã có thu hoạch.","anchor":"Ngày xưa vô thượng Tiên Thiên Thần Ma chết trận, trong thân thể tinh huyết bất diệt, có thông linh, bốc hơi mà ra, hóa thành Huyết Chủng.","phamCap":"Không rõ"}]},"nguon":["@c1215"]},{"id":"anh-linh-hat-giong","name":"Anh linh hạt giống","cn":"","aliases":["Linh hồn đạo chủng"],"category":"khac","categoryLabel":"Đạo chủng","phamCap":"Không rõ","soHuu":[],"trangThai":"Tồn tại trong quần thể kiến trúc cổ","blurb":"Đạo chủng được hình thành từ tàn hồn thông linh của cường giả cổ đại.","detail":"Anh linh hạt giống xuất hiện trong quần thể kiến trúc cổ trôi nổi tại Giới Phần. Loại đạo chủng này có thể phản phệ người tìm cách thu lấy.","nguonGoc":"Tàn hồn cường giả cổ đại thông linh hóa thành","dacDiem":"Có khả năng phản phệ người tìm kiếm.","congNang":["Có thể được thu làm linh hồn đạo chủng, nhưng tồn tại nguy cơ phản phệ tại @c1215."],"capNhatToi":"@c1215","tabs":{"tienTrinh":[{"chuong":"@c1215","loai":"xuất hiện","importance":"normal","giaiDoan":"Được phát hiện","text":"Đoàn thám hiểm phát hiện anh linh hạt giống do tàn hồn cường giả cổ đại thông linh hóa thành.","anchor":"Nơi này có anh linh hạt giống, là cổ đại cường giả tàn hồn thông linh, hóa thành hạt giống!","phamCap":"Không rõ"}]},"nguon":["@c1215"]},{"id":"thoi-gian-hat-giong","name":"Thời gian hạt giống","cn":"","aliases":[],"category":"khac","categoryLabel":"Đạo chủng","phamCap":"Quý giá dị thường","soHuu":[],"trangThai":"Tồn tại bên dòng sông thời gian","blurb":"Đạo chủng quý hiếm gắn với sức mạnh thời gian nồng đậm.","detail":"Thời gian hạt giống xuất hiện bên một dòng sông phát sáng trong Giới Phần. Việc tiếp cận vô cùng nguy hiểm vì dòng sông có thể cuốn người đi và làm thân thể khô kiệt, vỡ vụn.","thuocTinh":"Thời gian","dacDiem":"Gắn với sức mạnh thời gian nồng đậm.","congNang":["Cung cấp cơ duyên đạo chủng liên quan đến sức mạnh thời gian tại @c1215."],"capNhatToi":"@c1215","tabs":{"tienTrinh":[{"chuong":"@c1215","loai":"xuất hiện","importance":"normal","giaiDoan":"Được trưởng lão xác nhận","text":"Các trưởng lão xác nhận dòng sông phát sáng chứa thời gian hạt giống quý giá nhưng rất khó thu lấy.","anchor":"Nơi này có thời gian hạt giống, quý giá dị thường, liền xem ai số may có thể được.","phamCap":"Quý giá dị thường"}]},"nguon":["@c1215"]},{"id":"te-dan-xuong","name":"Tế đàn xương","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí truyền tống","phamCap":"Không rõ","soHuu":["Các trưởng lão Thiên Thần Thư Viện"],"trangThai":"Đang sử dụng","blurb":"Tế đàn làm từ xương cốt, được dùng để đưa đoàn Giới Phần trở lại Thiên Thần Thư Viện.","detail":"Các trưởng lão lấy tế đàn ra sau khi đoàn thoát khỏi Giới Phần. Nó xé mở hư không, giúp mọi người vượt Càn Khôn và truyền tống đường dài.","congNang":["Xé mở hư không và truyền tống đường dài tại @c1216"],"chuSoHuu":[{"ten":"Các trưởng lão Thiên Thần Thư Viện","tuChuong":"@c1216","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1216","loai":"dùng","importance":"normal","giaiDoan":"Đưa đoàn trở về","text":"Tế đàn xương xé mở hư không, đưa đoàn Giới Phần trở lại Thiên Thần Thư Viện.","anchor":"mấy vị trưởng lão lấy ra một toà xương cốt tế đàn, nó xé ra hư không"}]},"capNhatToi":"@c1216","nguon":["@c1216"]},{"id":"cay-non-gioi-thu","name":"Cây non Giới Thụ","cn":"","aliases":["Giới Thụ cây non"],"category":"khac","categoryLabel":"Đạo chủng","phamCap":"Hiếm có","soHuu":[],"trangThai":"Đã có người nắm giữ","blurb":"Đạo chủng hiếm có phục vụ con đường tu luyện cổ pháp. Một người trong đoàn Giới Phần đã lấy được nó nhưng danh tính chưa được tiết lộ.","detail":"Nhị Trường Lão xác nhận cây non Giới Thụ đã có chủ trong số những người trở về từ Giới Phần.","congNang":["Làm thiên loại phục vụ con đường tu luyện cổ pháp tại @c1216"],"tabs":{"tienTrinh":[{"chuong":"@c1216","loai":"xuất hiện","importance":"normal","giaiDoan":"Xác nhận đã có chủ","text":"Nhị Trường Lão công bố một người trong đoàn đang nắm giữ cây non Giới Thụ.","anchor":"trong các ngươi, có người nắm giữ giới thụ cây non"}]},"capNhatToi":"@c1216","nguon":["@c1216"]},{"id":"am-duong-loai","name":"Âm Dương loại","cn":"","aliases":[],"category":"khac","categoryLabel":"Vô thượng bảo loại","phamCap":"Vô thượng bảo loại","soHuu":[],"trangThai":"Đã có người nắm giữ","blurb":"Hạt giống do âm dương giao thái sinh thành, thể hiện sự đối lập và thống nhất của âm dương. Một người trong đoàn Giới Phần đã lấy được nó nhưng chưa lộ danh tính.","detail":"Âm Dương loại là hạt giống do đất trời sinh ra từ sự giao thái âm dương, được xem là một đạo chủng đặc biệt cho con đường cổ pháp.","nguonGoc":"Do âm dương giao thái và đất trời sinh thành.","dacDiem":"Thể hiện huyền bí đối lập và thống nhất của âm dương.","tabs":{"tienTrinh":[{"chuong":"@c1216","loai":"xuất hiện","importance":"normal","giaiDoan":"Xác nhận đã có chủ","text":"Nhị Trường Lão xác nhận một người trong đoàn đã nắm giữ Âm Dương loại.","anchor":"Âm dương loại, là âm dương giao thái kết quả, là đất trời sinh ra hạt giống"}]},"capNhatToi":"@c1216","nguon":["@c1216"]},{"id":"vo-thuong-co-loai-cua-tien-vien","name":"Vô thượng cổ loại của Tiên Viện","cn":"","aliases":[],"category":"khac","categoryLabel":"Đạo chủng","phamCap":"Vô thượng","soHuu":["Tiên Viện"],"trangThai":"Chưa được xác nhận","blurb":"Những đạo chủng mạnh nhất được suy đoán đang được Tiên Viện cất giữ sau khi khai quật các Tiên tích. Chúng có thể tái ngưng tụ sau khi người từng dung hợp chết đi.","detail":"Sự tồn tại cụ thể của các cổ loại này tại Tiên Viện mới là suy đoán của Nhị Trường Lão. Chúng được mô tả là khó hủy diệt và có khả năng tái ngưng tụ sau khi chủ nhân cũ qua đời.","nguonGoc":"Được suy đoán là khai quật từ các Tiên tích.","dacDiem":"Khó hủy diệt và có thể tái ngưng tụ sau khi người dung hợp chết đi.","congNang":["Có thể dung hợp với người tu cổ pháp và tái ngưng tụ sau khi chủ nhân chết tại @c1216"],"tabs":{"tienTrinh":[{"chuong":"@c1216","loai":"nhắc tới","importance":"bridge","giaiDoan":"Suy đoán còn được cất giữ","text":"Nhị Trường Lão suy đoán Tiên Viện còn giữ những cổ loại có thể tái ngưng tụ sau khi chủ nhân chết.","anchor":"khi (làm) người kia chết đi sau, nó cũng sẽ lần thứ hai ngưng tụ ra"}]},"capNhatToi":"@c1216","nguon":["@c1216"]},{"id":"tinh-cau-da-phap-thuyen","name":"Tinh cầu đá pháp thuyền","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí phi hành","phamCap":"Không rõ","soHuu":["Tiên Viện"],"trangThai":"Đang sử dụng","blurb":"Một tinh cầu chất đá khổng lồ được Tiên Viện dùng làm pháp thuyền vượt tinh không. Nó chuyên chở đoàn đệ tử tinh anh đến Thiên Thần Thư Viện.","detail":"Tinh cầu đá được dùng như một pháp thuyền quy mô lớn. Bên trong được suy đoán khắc nhiều phù văn và có năng lực công kích mạnh.","hinhDang":"Tinh cầu chất đá khổng lồ.","dacDiem":"Được dùng làm pháp thuyền và được suy đoán có lượng lớn phù văn bên trong.","congNang":["Vượt tinh không và chuyên chở đoàn Tiên Viện tại @c1216"],"chuSoHuu":[{"ten":"Tiên Viện","tuChuong":"@c1216","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1216","loai":"dùng","importance":"normal","giaiDoan":"Đưa Tiên Viện giáng lâm","text":"Tiên Viện dùng một tinh cầu đá làm pháp thuyền để vượt tinh không đến Thiên Thần Thư Viện.","anchor":"lấy một viên hành tinh làm pháp thuyền, vượt qua tinh không"}]},"capNhatToi":"@c1216","nguon":["@c1216"]},{"id":"cuc-manh-co-chung","name":"Cực mạnh cổ chủng","cn":"","aliases":[],"category":"khac","categoryLabel":"Đạo chủng","phamCap":"Cực mạnh cổ chủng","soHuu":["Tiên Viện"],"trangThai":"Đang được chữa trị","blurb":"Cực mạnh cổ chủng là những đạo chủng được Tiên Viện đào từ động phủ tiên gia của kỷ nguyên trước, dùng trên con đường tu luyện tiên khí. Chúng từng vỡ nát, chịu tổn thương nặng trong đại chiến Tiên cổ rồi đoàn tụ trở lại, nhưng vẫn cần được bảo huyết tưới dưỡng để phục hồi thành mầm giống hoàn mỹ.","detail":"Tiên Viện nắm giữ nhiều cực mạnh cổ chủng có nguồn gốc từ các động phủ tiên gia thuộc kỷ nguyên trước. Sau khi bị vỡ nát và tổn thương nặng trong đại chiến Tiên cổ, chúng đã đoàn tụ trở lại nhưng cần tiếp tục được bảo huyết tẩm bổ. Tiên Viện từng cam kết dành ít nhất một hạt cho thiên tài của Thiên Thần thư viện. @c1217","phanLoaiPhu":"Đạo chủng","nguonGoc":"Được đào từ động phủ tiên gia của kỷ nguyên trước.","dacDiem":"Từng vỡ nát và bị thương nặng trong đại chiến Tiên cổ, sau đó đoàn tụ trở lại.","congNang":["Dùng làm đạo chủng trên con đường tu luyện tiên khí.","Có thể được bảo huyết tẩm bổ để khôi phục thành mầm giống hoàn mỹ. @c1217"],"chuHienThoi":"Tiên Viện","capNhatToi":"@c1217","tabs":{"tienTrinh":[{"chuong":"@c1217","loai":"xuất hiện","importance":"major","giaiDoan":"Chờ phục hồi hoàn mỹ","text":"Tiên Viện công bố có nhiều cực mạnh cổ chủng đã đoàn tụ sau tổn thương và cần bảo huyết tưới dưỡng trước khi phân phối cho thiên tài.","anchor":"có thể đoàn tụ đi ra sẽ không sai lầm rồi","phamCap":"Cực mạnh cổ chủng"}]},"nguon":["@c1217"]},{"id":"bao-huyet-chua-tri-co-chung","name":"Bảo huyết chữa trị cổ chủng","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Tài nguyên","phamCap":"Không rõ","soHuu":[],"trangThai":"Được yêu cầu","blurb":"Bảo huyết dùng làm chất tưới dưỡng cuối cùng cho các cực mạnh cổ chủng bị thương tổn.","detail":"Nguồn bảo huyết phù hợp có thể là chân long huyết, phượng hoàng huyết hoặc máu của tuổi trẻ chí tôn đã tu thành ba đạo tiên khí.","congNang":["Tẩm bổ và chữa trị cực mạnh cổ chủng."],"capNhatToi":"@c1217","tabs":{"tienTrinh":[{"chuong":"@c1217","loai":"xuất hiện","importance":"normal","giaiDoan":"Được Tiên Viện tìm kiếm","text":"Tử Anh nêu máu của tuổi trẻ chí tôn tu thành ba đạo tiên khí là một nguồn có thể dùng để chữa trị cổ chủng.","anchor":"tu ra ba đạo tiên khí tuổi trẻ chí tôn máu cũng không kém"}]},"nguon":["@c1217"]},{"id":"tinh-cau-da-cua-tien-vien","name":"Tinh cầu đá của Tiên Viện","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí vận chuyển","phamCap":"Không rõ","soHuu":["Tiên Viện"],"trangThai":"Đang sử dụng","blurb":"Tinh cầu bằng đá mang phong cách cổ xưa, tràn ngập hỗn độn khí và được Tiên Viện dùng làm pháp khí vượt đường xa.","detail":"Pháp khí chở đoàn Tiên Viện tới Thiên Thần thư viện và có thể mở kim quang đại đạo để tiếp đón người lên bên trong.","hinhDang":"Tinh cầu bằng đá có phong cách cổ xưa.","vatLieu":"Đá","dacDiem":"Bề mặt tràn ngập hỗn độn khí.","congNang":["Vượt qua Càn Khôn và vận chuyển tu sĩ.","Mở kim quang đại đạo để đón khách."],"chuHienThoi":"Tiên Viện","chuSoHuu":[{"ten":"Tiên Viện","tuChuong":"@c1217","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"capNhatToi":"@c1217","tabs":{"tienTrinh":[{"chuong":"@c1217","loai":"dùng","importance":"normal","giaiDoan":"Chở đoàn Tiên Viện","text":"Tinh cầu đá vượt Càn Khôn tới Thiên Thần thư viện và mở kim quang đại đạo tiếp đón Yêu Nguyệt.","anchor":"cư nhiên lấy một viên tinh cầu làm pháp khí, vượt qua Càn Khôn rất kinh người"}]},"nguon":["@c1217"]},{"id":"cot-ho-lo-cua-thanh-vien","name":"Cốt hồ lô của Thánh Viện","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí bạch cốt","phamCap":"Không rõ","soHuu":["Thánh Viện"],"trangThai":"Đang sử dụng","blurb":"Pháp khí bạch cốt khổng lồ hình hồ lô của Thánh Viện, có kích thước không kém một ngôi sao.","detail":"Cốt hồ lô chở đoàn Thánh Viện tới Thiên Thần thư viện và mở thông đạo tiếp nhận Vương Hi.","hinhDang":"Hồ lô bạch cốt lớn ngang ngôi sao.","vatLieu":"Xương của một sinh linh chưa rõ","congNang":["Vận chuyển đoàn tu sĩ Thánh Viện.","Mở thông đạo tiếp nhận người vào bên trong."],"chuHienThoi":"Thánh Viện","chuSoHuu":[{"ten":"Thánh Viện","tuChuong":"@c1217","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"capNhatToi":"@c1217","tabs":{"tienTrinh":[{"chuong":"@c1217","loai":"dùng","importance":"normal","giaiDoan":"Chở đoàn Thánh Viện","text":"Cốt hồ lô của Thánh Viện xuất hiện trên trời và mở thông đạo mời Vương Hi vào trong.","anchor":"đó là Thánh Viện pháp khí, so với ngôi sao cũng không nhỏ"}]},"nguon":["@c1217"]},{"id":"tram-lam-giap-tru","name":"Trạm Lam giáp trụ","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Giáp trụ","phamCap":"Không rõ","soHuu":["Tiểu Thiên Vương","Ngô Thái","Thạch Hạo"],"trangThai":"Trong tay Thạch Hạo","blurb":"Trạm Lam giáp trụ là bộ giáp màu xanh thẳm thuộc sở hữu của Tiểu Thiên Vương. Giáp từng được cho Ngô Thái mượn, sau đó bị Thạch Hạo đoạt tại Giới Phần và trở thành lý do để người Tiên Viện công khai yêu cầu chàng giao trả, lĩnh tội.","detail":"Trạm Lam giáp trụ vốn thuộc về Tiểu Thiên Vương và từng được giao cho Ngô Thái mượn. Sau khi Thạch Hạo đoạt lấy bộ giáp tại Giới Phần, người Tiên Viện đã nhân danh Tiểu Thiên Vương công khai buộc chàng hoàn trả pháp bảo và tới lĩnh tội. @c1217","dacDiem":"Mang màu xanh thẳm và được xác nhận thuộc Tiểu Thiên Vương.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Tiểu Thiên Vương","tuChuong":"@c1217","denChuong":"","cachCoDuoc":"Chủ sở hữu được xác nhận","trangThai":"chủ sở hữu danh nghĩa"},{"ten":"Ngô Thái","tuChuong":"@c1217","denChuong":"@c1217","cachCoDuoc":"Được Tiểu Thiên Vương cho mượn","trangThai":"đã mất"},{"ten":"Thạch Hạo","tuChuong":"@c1217","denChuong":"","cachCoDuoc":"Đoạt từ Ngô Thái tại Giới Phần","trangThai":"đang giữ"}],"capNhatToi":"@c1217","tabs":{"tienTrinh":[{"chuong":"@c1217","loai":"đổi chủ","importance":"major","giaiDoan":"Bị Tiên Viện đòi lại","text":"Việc Trạm Lam giáp trụ bị Thạch Hạo đoạt được người Tiên Viện công khai nêu ra để buộc chàng giao trả và lĩnh tội.","anchor":"cướp đi này Trạm Lam giáp trụ, cái người này hay không tại đây","phamCap":"Không rõ"}]},"nguon":["@c1217"]},{"id":"bao-binh-cua-co-gai-toc-bac","name":"Bảo bình của cô gái tóc bạc","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Không rõ","soHuu":["Cô gái tóc bạc"],"trangThai":"Đang được sử dụng","blurb":"Bảo bình được cô gái tóc bạc sử dụng trong Kim Cương Phục Ma trận.","detail":"Miệng bình phun ra liên tiếp ánh bạc chứa sát ý, phối hợp với Hàng Ma xử và các pháp khí khác công kích Thạch Hạo.","hinhDang":"Bảo bình có miệng phun ánh bạc.","uyLuc":"Phun ra liên miên ánh bạc để công kích mục tiêu.","dacDiem":"Có thể phối hợp cùng các pháp khí khác khi vận chuyển Kim Cương Phục Ma trận.","congNang":["Phun ánh bạc công kích đối thủ."],"chuHienThoi":"Cô gái tóc bạc","chuSoHuu":[{"ten":"Cô gái tóc bạc","tuChuong":"@c1218","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1218","loai":"dùng","importance":"normal","giaiDoan":"Tham gia Kim Cương Phục Ma trận","text":"Cô gái tóc bạc dùng bảo bình phun ánh bạc về phía Thạch Hạo khi trận pháp vận chuyển.","anchor":"tay cầm bảo bình, bình miệng nơi đó phun ra liên miên ánh bạc, đánh về Thạch Hạo","phamCap":"Không rõ"}]},"capNhatToi":"@c1218","nguon":["@c1218"]},{"id":"tu-kim-hang-ma-xu","name":"Tử Kim Hàng Ma Xử","cn":"","category":"than-khi","categoryLabel":"Phục ma thần binh","phanLoaiPhu":"Thần binh công kích","phamCap":"","soHuu":["Nam tử tóc tím"],"chuHienThoi":"Nam tử tóc tím","trangThai":"Hư hỏng, mất thần năng","blurb":"Tử Kim Hàng Ma Xử là phục ma thần binh có thể phát ra gợn sóng tím với sức phá hủy đủ để uy hiếp Thiên Thần. Trong cuộc đối đầu với Thạch Hạo, binh khí bị giẫm rạn nứt, biến dạng và mất đi thần năng vốn có.","detail":"Tử Kim Hàng Ma Xử từng được nam tử tóc tím dùng để tập kích Thạch Hạo, phát ra gợn sóng tím có sức phá hủy mạnh, nhưng công kích không thể xuyên qua duy nhất động thiên. Sau đó, Thạch Hạo dùng một chân giẫm binh khí rạn nứt và biến dạng, khiến cốt văn tiêu tán, thần năng hoàn toàn biến mất. @c1219","uyLuc":"Gợn sóng tím phát ra từ thần binh được nhận định có thể đánh giết Thiên Thần.","dacDiem":"Sau khi bị Thạch Hạo giẫm rạn nứt và biến dạng, cốt văn của binh khí tiêu tán, khiến nó mất đi thần năng vốn có. @c1219","congNang":["Phát tán gợn sóng tím có sức phá hủy mạnh, được nhận định đủ khả năng đánh giết Thiên Thần."],"chuSoHuu":[{"ten":"Nam tử tóc tím","tuChuong":"@c1219","denChuong":"","cachCoDuoc":"","trangThai":"Sở hữu khi tập kích Thạch Hạo"}],"tabs":{"tienTrinh":[{"chuong":"@c1219","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị phá hỏng","phamCap":"","text":"Tử Kim Hàng Ma Xử bị Thạch Hạo giẫm rạn nứt, biến dạng và mất thần năng.","anchor":"Hàng Ma Xử rạn nứt, mất đi nên có thần năng"}]},"capNhatToi":"@c1219","nguon":["@c1219"]},{"id":"than-cap-vo-dai","name":"Thần Cấp võ đài","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Võ đài quy tắc","phanLoaiPhu":"Chiến đài","phamCap":"Thần cấp","soHuu":[],"trangThai":"Được dùng để tổ chức cuộc tranh ngôi Thiên Thần cảnh đệ nhất nhân","blurb":"Võ đài có thể áp đặt quy tắc chiến đấu và hạn chế cảnh giới của những người tham chiến. Các lão quái vật đưa một võ đài khổng lồ phủ tiên vụ tới để tổ chức cuộc tranh ngôi Thiên Thần cảnh đệ nhất nhân.","detail":"Thần Cấp võ đài có thể được dùng cho sinh tử chiến hoặc trận đấu đồng cảnh giới. Quy tắc áp chế của võ đài không thể kéo cảnh giới Tiểu Thiên Vương xuống khi vô thượng bảo chủng vừa dung hợp của hắn chưa ổn định.","hinhDang":"Võ đài khổng lồ phủ tiên vụ","uyLuc":"Có thể áp đặt hạn chế và điều chỉnh điều kiện giao chiến.","dacDiem":"Có khả năng bảo đảm hai đối thủ giao chiến trong cùng cảnh giới khi quy tắc áp chế phát huy hiệu lực.","congNang":["Áp đặt quy tắc cho trận chiến.","Hạn chế cảnh giới của người tham chiến để tổ chức cuộc đấu đồng cấp."],"capNhatToi":"@c1221","tabs":{"tienTrinh":[{"chuong":"@c1221","loai":"dùng","importance":"normal","giaiDoan":"Tranh ngôi Thiên Thần cảnh đệ nhất","text":"Các lão quái vật đưa Thần Cấp võ đài tới giữa không trung và dùng nó làm chiến trường chính thức cho cuộc tranh ngôi.","anchor":"có thể bảo đảm cùng cảnh giới một trận chiến","phamCap":"Thần cấp"}]},"nguon":["@c1221"]},{"id":"vo-thuong-bao-chung-cua-tieu-thien-vuong","name":"Vô thượng bảo chủng của Tiểu Thiên Vương","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Đạo chủng","phamCap":"Vô thượng bảo chủng","soHuu":["Tiểu Thiên Vương"],"trangThai":"Đã dung hợp nhưng chưa ổn định","blurb":"Đạo chủng được Tiểu Thiên Vương dung hợp để tu luyện cổ pháp. Khi quá trình dung hợp chưa ổn định, mọi sự áp chế nhằm vào hắn đều mất hiệu lực.","detail":"Tiểu Thiên Vương đã dung hợp thành công vô thượng bảo chủng nhưng chưa hoàn toàn củng cố. Trạng thái này khiến ngay cả quy tắc của Thần Cấp võ đài cũng không thể áp chế cảnh giới của hắn.","nguonGoc":"Do Tiểu Thiên Vương đoạt được trước khi xuất hiện trong cuộc tranh chấp tại Thiên Thần Thư Viện.","dacDiem":"Hoàn mỹ nhưng chưa ổn định, có thể mang lại cơ duyên hoặc dẫn tới biến cố trong quá trình dung hợp.","congNang":["Dùng làm đạo chủng để tu luyện cổ pháp.","Trong thời gian chưa ổn định, khiến các quy tắc áp chế cảnh giới không có hiệu lực với người dung hợp."],"chuSoHuu":[{"ten":"Tiểu Thiên Vương","tuChuong":"@c1221","denChuong":"","cachCoDuoc":"Đoạt được và dung hợp","trangThai":"Đã dung hợp nhưng chưa ổn định"}],"capNhatToi":"@c1221","tabs":{"tienTrinh":[{"chuong":"@c1221","loai":"xuất hiện","importance":"normal","giaiDoan":"Dung hợp chưa ổn định","text":"Tiểu Thiên Vương hé lộ mình đã dung hợp vô thượng bảo chủng nhưng quá trình ổn định vẫn chưa hoàn tất.","anchor":"ta chiếm được một viên vô thượng bảo chủng","phamCap":"Vô thượng bảo chủng"}]},"nguon":["@c1221"]},{"id":"hoan-my-co-chung","name":"Hoàn mỹ cổ chủng","cn":"","aliases":[],"category":"khac","categoryLabel":"Đạo chủng tu hành","phamCap":"Hoàn mỹ","soHuu":[],"trangThai":"Chưa xác định người sở hữu","blurb":"Đạo chủng hoàn mỹ được Thạch Hạo đặt làm điều kiện then chốt khi cân nhắc gia nhập Tiên Viện.","detail":"Các cổ chủng vô thượng dùng để dung hợp tu hành của Tiên Viện đã có ứng viên được định trước, khiến đại diện của viện chưa thể bảo đảm ngay một hạt giống tương xứng cho Thạch Hạo.","phanLoaiPhu":"Cổ chủng vô thượng dùng để dung hợp tu hành","dacDiem":"Những cổ chủng hiện có của Tiên Viện đều đã được định chủ.","capNhatToi":"@c1226","tabs":{"tienTrinh":[{"chuong":"@c1226","loai":"xuất hiện","importance":"normal","giaiDoan":"Điều kiện chiêu mộ","text":"Hoàn mỹ cổ chủng trở thành điều kiện trọng tâm trong cuộc thương lượng giữa Thạch Hạo và Tiên Viện.","anchor":"Tiên Viện mấy viên cổ chủng đều bị dự định"}]},"nguon":["@c1226"]},{"id":"thanh-nguyet-vat-than-bi","name":"Thanh Nguyệt","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật thần bí","phamCap":"","soHuu":["Thanh Y"],"trangThai":"Đã dung hợp với Thanh Y","blurb":"Một vầng Thanh Nguyệt thần bí đã dung hợp với Thanh Y, khiến nàng bị nghi là Chân Tiên chuyển thế.","detail":"Sự dung hợp giữa Thanh Y và Thanh Nguyệt khiến Tiên Viện đặc biệt coi trọng nàng trong cuộc tranh giành thiên tài.","congNang":["Dung hợp với Thanh Y và làm xuất hiện nghi vấn nàng là Chân Tiên chuyển thế."],"chuHienThoi":"Thanh Y","chuSoHuu":[{"ten":"Thanh Y","tuChuong":"@c1226","denChuong":"","cachCoDuoc":"Đã dung hợp với Thanh Nguyệt","trangThai":"đang có"}],"capNhatToi":"@c1226","tabs":{"tienTrinh":[{"chuong":"@c1226","loai":"xuất hiện","importance":"normal","giaiDoan":"Đã dung hợp","text":"Thanh Nguyệt được xác nhận đã dung hợp với Thanh Y và khiến thân phận của nàng được hai viện đặc biệt chú ý.","anchor":"Thanh Y bởi vì cùng một vòng Thanh Nguyệt kết hợp lại, nghi tự Chân Tiên chuyển thế"}]},"nguon":["@c1226"]},{"id":"bach-cot-te-dan-lien-lac-vuc-ngoai","name":"Bạch cốt tế đàn liên lạc vực ngoại","cn":"","aliases":[],"category":"khac","categoryLabel":"Tế đàn","phamCap":"Không rõ","soHuu":["Tiên viện","Thánh viện"],"trangThai":"Đang sử dụng","blurb":"Tế đàn nhỏ bằng xương trắng dùng để gửi cốt thư và liên lạc với thế lực ở vực ngoại.","detail":"Đại diện Tiên viện và Thánh viện lần lượt dùng tế đàn để hỏi ý kiến thế lực ở xa và xin tài nguyên bồi dưỡng Thạch Hạo.","congNang":["Tế tự, truyền cốt thư và liên lạc vực ngoại."],"tabs":{"tienTrinh":[{"chuong":"@c1227","loai":"dùng","importance":"normal","giaiDoan":"Liên lạc xin tài nguyên","text":"Tiên viện và Thánh viện dùng tế đàn gửi cốt thư ra vực ngoại để hỏi khả năng cấp cổ chủng hoặc chân huyết cho Thạch Hạo.","anchor":"đây là cùng xa xôi vực ngoại câu thông"}]},"capNhatToi":"@c1227","nguon":["@c1227"]},{"id":"chan-long-tam-huyet","name":"Chân Long tâm huyết","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Chân huyết","phamCap":"Tài nguyên luyện thể hàng đầu","soHuu":["Thánh viện"],"trangThai":"Đã phân phối","blurb":"Tinh hoa huyết dịch cực hiếm của Chân Long, được xem là tài nguyên luyện thể hàng đầu.","detail":"Thánh viện từng tích lũy Chân Long tâm huyết nhưng phần lớn số chân huyết thích hợp đã được cấp cho người khác trước khi chiêu mộ Thạch Hạo.","dacDiem":"Tinh hoa huyết dịch cực hiếm của Chân Long.","tabs":{"tienTrinh":[{"chuong":"@c1227","loai":"nhắc tới","importance":"bridge","giaiDoan":"Tài nguyên đã có chủ","text":"Chân Long tâm huyết được nêu trong số tài nguyên luyện thể quý hiếm mà Thánh viện không còn có thể cấp cho Thạch Hạo.","anchor":"Chân long tâm huyết, Phượng Hoàng niết bàn máu huyết"}]},"capNhatToi":"@c1227","nguon":["@c1227"]},{"id":"thien-phuong-niet-ban-huyet","name":"Thiên Phượng niết bàn huyết","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Chân huyết","phamCap":"Tài nguyên quý hiếm","soHuu":["Thánh viện"],"trangThai":"Đã có người kế thừa","blurb":"Huyết dịch tinh hoa quý hiếm của Thiên Phượng do Thánh viện tích lũy.","detail":"Loại chân huyết này đã có người kế thừa nên không thể được dùng làm điều kiện chiêu mộ Thạch Hạo.","dacDiem":"Tinh hoa huyết dịch của Thiên Phượng.","tabs":{"tienTrinh":[{"chuong":"@c1227","loai":"nhắc tới","importance":"bridge","giaiDoan":"Đã có người kế thừa","text":"Thiên Phượng niết bàn huyết được xác nhận đã có người kế thừa.","anchor":"về phần Thiên phượng niết bàn máu huyết cũng có người kế thừa"}]},"capNhatToi":"@c1227","nguon":["@c1227"]},{"id":"thien-giac-nghi-cuc-tan-huyet","name":"Thiên Giác Nghĩ cực tẫn huyết","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Chân huyết","phamCap":"Tài nguyên luyện thể quý hiếm","soHuu":["Thánh viện"],"trangThai":"Đã được dự định hoặc phân phát","blurb":"Chân huyết của Thiên Giác Nghĩ được đề xuất dùng để tăng hiệu quả luyện thể cho Thạch Hạo.","detail":"Trưởng lão Thánh viện ban đầu cho rằng viện vẫn còn một ít chân huyết này, nhưng sau khi liên lạc mới biết số tài nguyên thích hợp đã được định trước hoặc phân phát.","congNang":["Hỗ trợ luyện thể và bồi dưỡng thân thể."],"tabs":{"tienTrinh":[{"chuong":"@c1227","loai":"nhắc tới","importance":"normal","giaiDoan":"Đề xuất rồi không lấy được","text":"Thiên Giác Nghĩ cực tẫn huyết được đề xuất cấp cho Thạch Hạo nhưng cuối cùng không thể điều động.","anchor":"Thiên sừng nghĩ lực chi cực tẫn huyết ở Thánh viện còn có một chút"}]},"capNhatToi":"@c1227","nguon":["@c1227"]},{"id":"co-quan-phong-an-ngoc-thach-thu","name":"Cổ quan phong ấn ngọc thạch thư","cn":"","aliases":[],"category":"khac","categoryLabel":"Cổ quan và bí thư","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang được cất giữ","blurb":"Cổ quan do Thạch Hạo mang từ ba nghìn châu, bên trong phong ấn một bộ ngọc thạch thư lấy tại di tích Tiên Cổ.","detail":"Thạch Hạo lấy cổ quan ra khi suy xét con đường tương lai, nhưng nội dung và công dụng của ngọc thạch thư chưa được giải đáp.","hinhDang":"Một cổ quan chứa ngọc thạch thư bị phong ấn.","nguonGoc":"Di tích Tiên Cổ tại ba nghìn châu.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1227","denChuong":"","cachCoDuoc":"Mang từ di tích Tiên Cổ tại ba nghìn châu.","trangThai":"Đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c1227","loai":"xuất hiện","importance":"normal","giaiDoan":"Được lấy ra suy xét","text":"Thạch Hạo lấy cổ quan chứa ngọc thạch thư ra để cân nhắc mối liên hệ của nó với con đường tương lai.","anchor":"ở giữa phong ấn ngọc thạch thư"}]},"capNhatToi":"@c1227","nguon":["@c1227"]},{"id":"thach-hap-than-bi","name":"Thạch hạp thần bí","cn":"","aliases":[],"category":"khac","categoryLabel":"Hộp đá","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang được cất giữ","blurb":"Hộp đá thần bí được Thạch Hạo lấy từ nơi sâu nhất của di tích Tiên Cổ.","detail":"Thạch Hạo cho rằng thạch hạp có thể quý hơn ngọc thạch thư trong cổ quan, nhưng bí mật và công dụng của nó vẫn chưa được làm rõ.","hinhDang":"Một hộp đá thần bí.","nguonGoc":"Nơi sâu nhất của di tích Tiên Cổ tại ba nghìn châu.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1227","denChuong":"","cachCoDuoc":"Lấy từ nơi sâu nhất của di tích Tiên Cổ.","trangThai":"Đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c1227","loai":"xuất hiện","importance":"normal","giaiDoan":"Được lấy ra suy xét","text":"Thạch Hạo lấy thạch hạp ra và nhận định nó có thể còn quý hơn ngọc thạch thư trong cổ quan.","anchor":"hẳn là so với Cổ quan chìm ngọc thạch thư hoàn trân quý"}]},"capNhatToi":"@c1227","nguon":["@c1227"]},{"id":"hat-giong-hon-don-chua-thanh-thuc","name":"Hạt giống hỗn độn chưa thành thục","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Tiên chủng","phamCap":"Chưa thành thục","soHuu":["Thạch Hạo"],"trangThai":"Chưa tới lúc xuất thế","blurb":"Hạt giống bất định hình mang hỗn độn khí và thần bí hi quang, được ví như cuống rốn của thiên địa.","detail":"Thạch Hạo lấy hạt giống từ cổ mỏ Thiên Nhân tộc. Nó có thể thay đổi kích thước, không mang hình dạng cố định và vẫn chưa thành thục.","hinhDang":"Không có hình dạng cố định và có thể biến đổi kích thước.","nguonGoc":"Cổ mỏ Thiên Nhân tộc.","dacDiem":"Mang hỗn độn khí và thần bí hi quang, được ví như cuống rốn thiên địa.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1227","denChuong":"","cachCoDuoc":"Thu được tại cổ mỏ Thiên Nhân tộc.","trangThai":"Đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c1227","loai":"xuất hiện","importance":"normal","giaiDoan":"Được lấy ra suy xét","text":"Thạch Hạo kiểm tra hạt giống hỗn độn chưa thành thục khi cân nhắc con đường tương lai.","anchor":"Loại này hạt giống như thiên địa cuống rốn"}]},"capNhatToi":"@c1227","nguon":["@c1227"]},{"id":"bat-tran-quy","name":"Bát trân quy","cn":"","category":"khac","categoryLabel":"Bát trân Thái Cổ","phamCap":"Kỳ trân quý hiếm","soHuu":["Thạch Hạo"],"trangThai":"Bị Thạch Hạo tạm giữ","blurb":"Bát Trân Quy là sinh linh quý hiếm có hình rùa trắng đầu hổ, đuôi dài như rắn, nổi danh với khả năng bổ huyết và tẩm bổ thân thể. Sau khi từng bị Đại trưởng lão câu lên rồi thả lại đầm lầy, nó được Thạch Hạo giải phóng khỏi hộp đá và tạm giữ để bổ sung huyết khí.","detail":"Bát Trân Quy từng bị Đại trưởng lão dùng thánh dược làm mồi câu lên tại vùng đầm lầy, nhưng được thả trở lại vì không phải sinh linh ông muốn tìm (@c1228). Về sau, Thạch Hạo phá hộp đá giải phóng nó, dùng thần niệm hỏi dò rồi tạm thời giữ lại nhằm bổ sung huyết khí (@c1257). Đây là một mỹ vị quý hiếm, đặc biệt hữu ích trong việc bù đắp khí huyết hao tổn, tẩm bổ tu sĩ già yếu và giúp Chí tôn có thân thể khô bại khôi phục tinh lực.","phanLoaiPhu":"Dược thiện","hinhDang":"Rùa trắng đầu hổ, đuôi dài như rắn.","uyLuc":"Có danh xưng bổ huyết đệ nhất.","dacDiem":"Sinh linh quý hiếm có hình rùa trắng đầu hổ, đuôi dài như rắn; đồng thời là mỹ vị có thể tẩm bổ thân thể.","chuHienThoi":"","congNang":["Bổ sung huyết khí hao tổn cho người sử dụng (@c1257).","Tẩm bổ thân thể của tu sĩ già yếu.","Giúp Chí tôn già yếu, thân thể khô bại khôi phục tinh lực."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1257","denChuong":"","cachCoDuoc":"Phá hộp đá và giải phong ấn cho Bát Trân Quy.","trangThai":"Tạm giữ"}],"capNhatToi":"@c1228","tabs":{"tienTrinh":[{"chuong":"@c1228","loai":"xuất hiện","importance":"normal","giaiDoan":"Bị câu rồi được thả","text":"Bát trân quy bị Đại trưởng lão câu lên bằng thánh dược nhưng được thả trở lại đầm lầy vì không phải sinh linh ông đang tìm kiếm.","anchor":"Ngoài ra, nó còn có bổ huyết đệ nhất danh xưng"},{"chuong":"@c1257","loai":"đổi chủ","importance":"major","giaiDoan":"Được giải phong ấn","phamCap":"Đại bổ dược quý hiếm","text":"Thạch Hạo phá hộp đá giải phóng Bát Trân Quy, hỏi dò bằng thần niệm rồi tạm giữ sinh linh này để bổ sung huyết khí.","anchor":"Nó được xưng bổ huyết số một, chính là cấp chí tôn nhân vật già đi, thân thể khô bại, cũng có thể dựa vào nó mà lại thu được tinh lực"}]},"dinhDanh":"goc","nguon":["@c1228","@c1257"]},{"id":"ngoc-thach-thu-ve-lay-than-lam-chung","name":"Ngọc thạch thư về lấy thân làm chủng","cn":"","aliases":[],"category":"khac","categoryLabel":"Điển tịch","phamCap":"Không rõ","soHuu":["Đại trưởng lão","Thạch Hạo"],"trangThai":"Được Thạch Hạo nghiên cứu","blurb":"Một chồng điển tịch do Đại trưởng lão trao cho Thạch Hạo để nghiên cứu con đường lấy thân làm chủng.","detail":"Các ngọc thạch thư được viết bằng tiên văn cổ đại, ghi lại suy diễn, kinh nghiệm và những điều cần chú ý khi lấy thân làm chủng. Nội dung mới chỉ dẫn phương hướng, chưa phải kinh văn chuyên dùng lúc chính thức dung hợp đạo quả.","phanLoaiPhu":"Điển tịch tu hành","dacDiem":"Được viết bằng tiên văn cổ đại và tổng hợp thành quả nghiên cứu của nhiều thế hệ.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c1229","congNang":["Chỉ dẫn phương hướng, kinh nghiệm và các điểm cần lưu ý khi chuẩn bị lấy thân làm chủng."],"chuSoHuu":[{"ten":"Đại trưởng lão","tuChuong":"@c1229","denChuong":"@c1229","cachCoDuoc":"Thu thập và tổng hợp từ các bí sách cùng thành quả nghiên cứu.","trangThai":"Đã trao cho Thạch Hạo"},{"ten":"Thạch Hạo","tuChuong":"@c1229","denChuong":"","cachCoDuoc":"Được Đại trưởng lão giao để nghiên cứu.","trangThai":"Đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c1229","loai":"xuất hiện","importance":"normal","giaiDoan":"Truyền thụ","text":"Đại trưởng lão trao một chồng ngọc thạch thư cho Thạch Hạo, người sau đó dành ba ngày đọc và suy ngẫm nội dung.","anchor":"Những sách này tịch ngươi cầm xem!"}]},"nguon":["@c1229"]},{"id":"hat-giong-ky-di-cua-thach-hao","name":"Hạt giống kỳ dị của Thạch Hạo","cn":"","aliases":[],"category":"khac","categoryLabel":"Đạo chủng phôi thai","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang được giữ","blurb":"Hạt giống đặc biệt được Đại trưởng lão đánh giá là một cuống rốn thiên địa.","detail":"Vật này có thể tẩm bổ bản thân Thạch Hạo rồi hóa thành đạo chủng, nhờ đó làm tăng hy vọng thành công khi hắn đi con đường lấy thân làm chủng.","phanLoaiPhu":"Hạt giống tu hành","dacDiem":"Mang đặc tính như cuống rốn thiên địa.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c1229","congNang":["Tẩm bổ bản thân người sở hữu và có khả năng hóa thành đạo chủng."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1229","denChuong":"","cachCoDuoc":"Đã sở hữu trước khi được Đại trưởng lão đánh giá.","trangThai":"Đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c1229","loai":"xuất hiện","importance":"normal","giaiDoan":"Xác định đặc tính","text":"Đại trưởng lão nhận định hạt giống của Thạch Hạo giống một cuống rốn thiên địa, có thể tẩm bổ bản thân rồi hóa thành đạo chủng.","anchor":"đây là một cái thiên địa cuống rốn có thể tẩm bổ bản thân, hóa thành đạo chủng"}]},"nguon":["@c1229"]},{"id":"thien-phuong-huyet","name":"Thiên Phượng huyết","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Thiên tài địa bảo","phamCap":"Thần phẩm","soHuu":["Thiên Thần thư viện"],"trangThai":"Đang được chuẩn bị","blurb":"Một trong những thần phẩm được chuẩn bị cho lần đột phá lấy thân làm chủng của Thạch Hạo.","detail":"Thiên Thần thư viện có hoàng huyết không tinh khiết và có thể tinh luyện một phần thành Thiên Phượng huyết. Vật này được dùng để hỗ trợ quá trình đột phá và tăng khả năng giữ mạng.","nguonGoc":"Có thể tinh luyện từ hoàng huyết do Thiên Thần thư viện lưu giữ.","dacDiem":"Nguồn hoàng huyết hiện có không tinh khiết nhưng vẫn có thể tinh luyện.","capNhatToi":"@c1229","congNang":["Hỗ trợ đột phá và bảo toàn sinh mệnh trong quá trình lấy thân làm chủng."],"tabs":{"tienTrinh":[{"chuong":"@c1229","loai":"nhắc tới","importance":"normal","giaiDoan":"Chuẩn bị tài nguyên","text":"Thiên Phượng huyết được đưa vào danh sách thần phẩm cần chuẩn bị cho lần đột phá của Thạch Hạo.","anchor":"Thiên Phượng huyết, cũng còn tốt ở thư viện bên trong còn có"}]},"nguon":["@c1229"]},{"id":"tru-ta-than-truc","name":"Trừ tà thần trúc","cn":"","aliases":["Ích Tà Thần Trúc"],"category":"nguyen-lieu","categoryLabel":"Thần dược","phamCap":"Thần phẩm","soHuu":[],"trangThai":"Chưa tìm được","blurb":"Một trong hai thần vật Thạch Hạo phải tự tìm để chuẩn bị cho con đường lấy thân làm chủng.","detail":"Cây trúc cần tìm phải là cổ trúc trắng như ngọc, có ít nhất hai mươi tiết, tương ứng thời gian sinh trưởng hơn mười nghìn năm.","hinhDang":"Cổ trúc trắng như ngọc, có ít nhất hai mươi tiết.","dacDiem":"Cực kỳ hiếm và phải đạt ít nhất hai mươi tiết mới đáp ứng yêu cầu.","capNhatToi":"@c1229","congNang":["Làm tài nguyên chuẩn bị cho lần đột phá lấy thân làm chủng."],"tabs":{"tienTrinh":[{"chuong":"@c1229","loai":"nhắc tới","importance":"normal","giaiDoan":"Tìm kiếm thần dược","text":"Đại trưởng lão yêu cầu Thạch Hạo tự tìm một cây Trừ tà thần trúc có ít nhất hai mươi tiết.","anchor":"Trừ tà thần trúc, cần hai mươi tiết trở lên cổ trúc."}]},"nguon":["@c1229"]},{"id":"hoang-tuyen-qua","name":"Hoàng tuyền quả","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Thần quả","phamCap":"Thần phẩm","soHuu":["Thạch Hạo"],"trangThai":"đã dùng","blurb":"Thần quả sinh trưởng lâu năm tại vùng cực âm, là một trong hai vật Thạch Hạo phải tự hái. (+) Một loại kỳ quả từng góp phần bồi dưỡng nguyên thần Thạch Hạo. [CAN-SOAT-GOP]","detail":"Hoàng tuyền quả cần sinh trưởng tại nơi cực âm trong hơn chín nghìn năm. Nó hiếm đến mức nhiều người cho rằng loại thần quả này không tồn tại.","nguonGoc":"Sinh trưởng tại vùng cực âm.","dacDiem":"Phải đạt tuổi sinh trưởng hơn chín nghìn năm.","capNhatToi":"@c1229","congNang":["Làm tài nguyên chuẩn bị cho lần đột phá lấy thân làm chủng.","Làm lớn mạnh và thúc đẩy lột xác Nguyên Thần @c1239","Xúc phát trạng thái ngộ đạo của Thạch Hạo @c1239"],"tabs":{"tienTrinh":[{"chuong":"@c1229","loai":"nhắc tới","importance":"normal","giaiDoan":"Tìm kiếm thần quả","text":"Đại trưởng lão yêu cầu Thạch Hạo tìm Hoàng tuyền quả sinh trưởng hơn chín nghìn năm tại nơi cực âm.","anchor":"Hoàng tuyền quả, ở cực âm nơi dài ra chín ngàn năm trở lên."},{"chuong":"@c1237","loai":"xuất hiện","importance":"normal","giaiDoan":"Được phát hiện","text":"Thạch Hạo tìm thấy Hoàng Tuyền Quả trên một cây thực vật màu vàng ở cuối dòng sông.","anchor":"Trong đó một cây kết trái cây, giống như cây mận, to nhỏ cũng gần gũi","phamCap":"Không rõ"},{"chuong":"@c1239","loai":"dùng","importance":"normal","giaiDoan":"Phát huy thần hiệu","text":"Dược lực của Hoàng Tuyền Quả làm lớn mạnh Nguyên Thần Thạch Hạo, xúc phát ngộ đạo và tiếp tục thúc đẩy quá trình lột xác.","anchor":"một viên Hoàng Tuyền Quả mà thôi, để Thạch Hạo Nguyên Thần ở cường tráng","phamCap":""}]},"nguon":["@c1229","@c1237","@c1239","@c1325"],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1237","denChuong":"@c1239","cachCoDuoc":"Tìm thấy tại cuối dòng sông vàng","trangThai":"đã dùng"}]},{"id":"hop-dao-hoa","name":"Hợp Đạo hoa","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Thiên địa kỳ hoa","phamCap":"Quý hơn Trường Sinh dược","soHuu":[],"trangThai":"Chưa tìm được","blurb":"Hợp Đạo hoa là kỳ hoa độc nhất, xưa nay chỉ có một cây, được đánh giá có giá trị vượt trên cả Trường Sinh dược. Hoa có thể trợ giúp người dùng chân chính hợp đạo, bảo đảm Thạch Hạo thành công trên con đường lấy thân làm chủng, thậm chí cứu người đã thất bại và tàn phế nếu vẫn còn một hơi sống.","detail":"Hợp Đạo hoa không phải Trường Sinh dược nhưng có thể còn quý giá hơn. Đại trưởng lão xác nhận nếu Thạch Hạo sử dụng kỳ hoa này, hắn chắc chắn thành công khi lấy thân làm chủng; kể cả trong trường hợp thất bại, thân thể tàn phế và chỉ còn một hơi, hoa vẫn có thể giúp hắn sống lại rồi hoàn thành hợp đạo. Công dụng hợp đạo của hoa cũng áp dụng đối với nhân vật cấp đại đế hoặc người thực sự thuộc Tiên đạo. @c1229","nguonGoc":"Xưa nay chỉ có một cây.","uyLuc":"Có thể bảo đảm thành công trên con đường lấy thân làm chủng, đồng thời cứu người đã thất bại và tàn phế khi vẫn còn một hơi để người đó sống lại rồi hoàn thành hợp đạo.","dacDiem":"Kỳ hoa độc nhất, xưa nay chỉ có một cây; không phải Trường Sinh dược nhưng giá trị có thể vượt trên Trường Sinh dược.","capNhatToi":"@c1229","congNang":["Giúp nhân vật cấp đại đế hoặc người thực sự thuộc Tiên đạo hợp đạo.","Bảo đảm Thạch Hạo thành công trên con đường lấy thân làm chủng. @c1229","Cứu người đã hợp đạo thất bại, thân thể tàn phế nhưng vẫn còn một hơi, giúp người đó sống lại và hoàn thành hợp đạo. @c1229"],"tabs":{"tienTrinh":[{"chuong":"@c1229","loai":"nhắc tới","importance":"major","giaiDoan":"Phương án bảo đảm thành công","text":"Đại trưởng lão xác nhận Hợp Đạo hoa có thể bảo đảm Thạch Hạo thành công khi lấy thân làm chủng, thậm chí cứu hắn sau khi thất bại và tàn phế.","anchor":"Thạch Hạo lấy thân là chủng, nếu như có thể ăn vào loại này hoa, nhất định sẽ thành công"}]},"nguon":["@c1229"]},{"id":"thanh-sac-cot","name":"Thanh sắc cốt","cn":"","category":"khac","categoryLabel":"Vật truyền thừa","phamCap":"Không rõ","soHuu":["Đại trưởng lão","Thạch Hạo"],"trangThai":"Được dùng để truyền pháp","blurb":"Khối xương màu xanh mang khoa đẩu văn và cốt văn dày đặc, lưu giữ Chuy Cốt Pháp.","detail":"Đại trưởng lão dùng thanh sắc cốt để truyền Chuy Cốt Pháp cho Thạch Hạo. Trên bề mặt có nhiều khoa đẩu văn cùng cốt văn đan dệt và phát sáng.","phanLoaiPhu":"Vật lưu giữ truyền thừa","hinhDang":"Khối xương màu xanh","vatLieu":"Xương","dacDiem":"Mang nhiều khoa đẩu văn và cốt văn phát sáng.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c1230","congNang":["Lưu giữ phần Chuy Cốt Pháp tương ứng Thiên Thần cảnh."],"chuSoHuu":[{"ten":"Đại trưởng lão","tuChuong":"@c1230","denChuong":"@c1230","cachCoDuoc":"Không nêu","trangThai":"Dùng để truyền pháp"},{"ten":"Thạch Hạo","tuChuong":"@c1230","denChuong":"","cachCoDuoc":"Được Đại trưởng lão truyền cho","trangThai":"Tiếp nhận truyền thừa"}],"tabs":{"tienTrinh":[{"chuong":"@c1230","loai":"xuất hiện","importance":"normal","giaiDoan":"Truyền Chuy Cốt Pháp","text":"Đại trưởng lão dùng thanh sắc cốt mang khoa đẩu văn và cốt văn để truyền Chuy Cốt Pháp cho Thạch Hạo.","anchor":"ở một khối thanh sắc cốt có rất nhiều khoa đẩu văn","phamCap":"Không rõ"}]},"nguon":["@c1230"]},{"id":"hoang-kim-cot","name":"Hoàng kim cốt","cn":"","category":"khac","categoryLabel":"Vật truyền thừa","phamCap":"Không rõ","soHuu":["Đại trưởng lão","Thạch Hạo"],"trangThai":"Được dùng để truyền pháp","blurb":"Khối xương màu vàng ghi Đoán Thần Pháp bằng văn tự của kỷ nguyên Tiên Cổ.","detail":"Đại trưởng lão dùng hoàng kim cốt để truyền Đoán Thần Pháp cho Thạch Hạo. Nội dung trên đó là văn tự từ kỷ nguyên Tiên Cổ.","phanLoaiPhu":"Vật lưu giữ truyền thừa","hinhDang":"Khối xương màu vàng","vatLieu":"Xương","nguonGoc":"Được khắc bằng văn tự kỷ nguyên Tiên Cổ","dacDiem":"Lưu giữ phần Đoán Thần Pháp đủ dùng ở Thiên Thần cảnh.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c1230","congNang":["Lưu giữ Đoán Thần Pháp dùng để rèn đúc nguyên thần."],"chuSoHuu":[{"ten":"Đại trưởng lão","tuChuong":"@c1230","denChuong":"@c1230","cachCoDuoc":"Không nêu","trangThai":"Dùng để truyền pháp"},{"ten":"Thạch Hạo","tuChuong":"@c1230","denChuong":"","cachCoDuoc":"Được Đại trưởng lão truyền cho","trangThai":"Tiếp nhận truyền thừa"}],"tabs":{"tienTrinh":[{"chuong":"@c1230","loai":"xuất hiện","importance":"normal","giaiDoan":"Truyền Đoán Thần Pháp","text":"Đại trưởng lão dùng hoàng kim cốt khắc văn tự Tiên Cổ để truyền Đoán Thần Pháp cho Thạch Hạo.","anchor":"là lấy Tiên Cổ kỷ nguyên thời đại văn tự khắc mà thành","phamCap":"Không rõ"}]},"nguon":["@c1230"]},{"id":"ngoc-bai-dan-duong-tien-khau","name":"Ngọc bài dẫn đường Tiên Khâu","cn":"","category":"phap-bao","categoryLabel":"Tín vật trận pháp","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang được sử dụng","blurb":"Tín vật do Đại trưởng lão ban, giúp người cầm tìm thấy và tiếp cận Tiên Khâu ẩn trong hư không.","detail":"Ngọc bài khắc trận pháp thần bí có thể phát sáng chỉ đường. Nếu không có nó, người đi đường không thể nhìn thấy hay chạm tới Tiên Khâu dù xuyên qua đúng vị trí ngọn núi.","phanLoaiPhu":"Tín vật dẫn đường","hinhDang":"Ngọc bài","nguonGoc":"Do Đại trưởng lão giao cho Thạch Hạo","dacDiem":"Khắc trận pháp thần bí và phát sáng khi tới gần Tiên Khâu.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c1230","congNang":["Chỉ đường tới Tiên Khâu và cho phép người cầm nhìn thấy, tiếp cận ngọn núi ẩn trong hư không."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1230","denChuong":"","cachCoDuoc":"Được Đại trưởng lão ban","trangThai":"Đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c1230","loai":"dùng","importance":"normal","giaiDoan":"Mở đường vào Tiên Khâu","text":"Thạch Hạo dùng ngọc bài để tìm thấy và tiếp cận Tiên Khâu đang ẩn trong hư không.","anchor":"chỉ có cầm khắc có thần bí trận pháp ngọc bài mới có thể tiếp cận","phamCap":"Không rõ"}]},"nguon":["@c1230"]},{"id":"bach-cot-phu","name":"Bạch cốt phù","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Phù khí","phanLoaiPhu":"Phù khí hỗ trợ","phamCap":"","soHuu":["Trưởng lão dẫn đội Tiên Viện","Đệ tử Tiên Viện"],"trangThai":"Được phát cho đệ tử Tiên Viện","hinhDang":"Một quả cốt phù trắng noãn.","blurb":"Phù khí được trưởng lão Tiên Viện phát cho các đệ tử khi lên đỉnh núi. Vật này làm áp lực quanh khu vực cổ miếu giảm nhanh.","detail":"Bạch cốt phù giúp những tu sĩ chưa đủ sức tự chống đỡ áp lực trên đỉnh núi có thể rời chiến thuyền và tiếp cận khu vực cơ duyên.","congNang":["Giảm mạnh áp lực trên đỉnh núi, hỗ trợ người mang tiếp cận khu vực cổ miếu."],"dacDiem":"Có màu trắng noãn.","chuHienThoi":"Các đệ tử Tiên Viện","chuSoHuu":[{"ten":"Trưởng lão dẫn đội Tiên Viện","tuChuong":"@c1231","denChuong":"@c1231","cachCoDuoc":"Nắm giữ trước khi phát cho đệ tử.","trangThai":"Đã phân phát"},{"ten":"Đệ tử Tiên Viện","tuChuong":"@c1231","denChuong":"","cachCoDuoc":"Được trưởng lão dẫn đội phát.","trangThai":"Đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1231","loai":"dùng","importance":"normal","giaiDoan":"Giảm áp lực đỉnh núi","text":"Trưởng lão Tiên Viện phát bạch cốt phù cho các đệ tử, khiến áp lực quanh họ giảm nhanh.","anchor":"tất cả mọi người đều cầm trong tay một quả trắng noãn cốt phù, áp lực nhất thời giảm nhanh"}]},"capNhatToi":"@c1231","nguon":["@c1231"]},{"id":"ich-ta-than-truc","name":"Ích Tà Thần Trúc","cn":"","aliases":["Trừ tà thần trúc","Tịch Tà Thần Trúc"],"category":"nguyen-lieu","categoryLabel":"Thần dược luyện thể","phanLoaiPhu":"Thần trúc","phamCap":"","soHuu":[],"trangThai":"Được Thạch Hạo lên đường tìm kiếm","blurb":"Thần trúc có tương dịch dùng để ngao luyện thân thể. Thạch Hạo được khuyên tìm cây cổ xưa nhất khi đạo cốt vừa tái tạo và chưa hoàn toàn khép lại.","detail":"Tương dịch của Ích Tà Thần Trúc có thể tiếp tục rèn luyện thân thể và đạo cốt. Sau khi hoàn tất mười ngày chịu Chiến thần lạc ấn, Thạch Hạo lập tức lên đường tìm thần trúc theo lời khuyên của các trưởng lão.","congNang":["Tương dịch có thể dùng để ngao luyện thân thể."],"dacDiem":"Có một cây cổ xưa nhất được kỳ vọng mang lại hiệu quả luyện thể đặc biệt.","tabs":{"tienTrinh":[{"chuong":"@c1231","loai":"nhắc tới","importance":"normal","giaiDoan":"Mục tiêu luyện thể","text":"Các trưởng lão khuyên Thạch Hạo tìm cây Ích Tà Thần Trúc cổ xưa nhất để ngao luyện thân thể khi đạo cốt chưa khép lại.","anchor":"nói không chừng thật có thể tìm được xưa nhất kia một cây, ngao luyện thân thể"}]},"capNhatToi":"@c1231","nguon":["@c1231"]},{"id":"than-mon-mau-vang","name":"Thần môn màu vàng","cn":"","aliases":["Bình phong màu vàng"],"category":"khac","categoryLabel":"Màn chắn","phamCap":"Không rõ","soHuu":[],"trangThai":"Bị Thạch Hạo phá vỡ","blurb":"Thần môn màu vàng là một tầng bình phong do hào quang màu vàng ngưng tụ, chắn cuối con đường trước sơn môn và ngăn lối vào nơi sâu trong Tiên khâu. Nó từng kháng cự được nhiều thiên tài đã tu thành ba đạo tiên khí, nhưng sau đó bị Thạch Hạo dùng một quyền đánh thủng.","detail":"Không rõ nguồn gốc của Thần môn màu vàng. Pháp bảo này hiện ra dưới hình thái một tầng bình phong màu vàng chắn cuối con đường trước sơn môn, có vai trò ngăn người vượt qua để tiến vào khu vực sâu hơn của Tiên khâu. Nhiều thiên tài tới sau, dù đã tu thành ba đạo tiên khí, vẫn không thể lay chuyển nó; trái lại, Thạch Hạo dùng một quyền đánh thủng bình phong và tiến vào bên trong. @c1232","phanLoaiPhu":"Cấm chế chắn đường","uyLuc":"Có thể kháng cự nỗ lực của nhiều thiên tài đã tu thành ba đạo tiên khí, nhưng bị Thạch Hạo dùng một quyền đánh thủng. @c1232","dacDiem":"Có hình thái một tầng bình phong do hào quang màu vàng ngưng tụ, chắn cuối con đường trước sơn môn.","congNang":["Tạo thành bình phong màu vàng ngăn người vượt qua sơn môn để tiến vào nơi sâu trong Tiên khâu. @c1232"],"capNhatToi":"@c1232","tabs":{"tienTrinh":[{"chuong":"@c1232","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị phá vỡ","text":"Thần môn màu vàng bị Thạch Hạo dùng một quyền đánh thủng, trong khi những thiên tài tới sau không thể lay chuyển phần bình phong chắn đường.","anchor":"Thạch Hạo ở vung đầu nắm đấm, nổ ra một tầng màu vàng bình phong","phamCap":"Không rõ"}]},"nguon":["@c1232"]},{"id":"khoi-loi-hac-am-tien-kim","name":"Khôi lỗi Hắc Ám tiên kim","cn":"","aliases":["Con rối Hắc Ám tiên kim hình người"],"category":"phap-bao","categoryLabel":"Khôi lỗi","phanLoaiPhu":"Khôi lỗi chiến đấu","phamCap":"Không rõ","soHuu":["Bất Hủ giả trong dấu ấn đá tím"],"trangThai":"Còn hoạt động dưới sự áp chế của khu vực","hinhDang":"Hình người","vatLieu":"Hắc Ám tiên kim không lẫn tạp chất","nguonGoc":"Thân thể của một sinh linh từ thế giới bờ bên kia bị tước sinh mệnh và luyện thành khôi lỗi.","uyLuc":"Sức mạnh nguyên bản đủ tung quyền xuyên thủng trời và đánh nổ đại tinh ngoài vực.","dacDiem":"Toàn thân mang dấu vết đại đạo và được tạo hoàn toàn từ Hắc Ám tiên kim.","chuHienThoi":"Không rõ","congNang":["Khôi lỗi chiến đấu có sức mạnh thể phách cực lớn."],"chuSoHuu":[{"ten":"Bất Hủ giả trong dấu ấn đá tím","tuChuong":"@c1233","denChuong":"","cachCoDuoc":"Khôi lỗi từng đi theo Bất Hủ giả tới khu vực thần trúc.","trangThai":"Quan hệ chủ sở hữu chưa được xác nhận đầy đủ"}],"blurb":"Một khôi lỗi hình người được luyện hoàn toàn từ Hắc Ám tiên kim. Sức mạnh nguyên bản của nó đủ đánh nổ đại tinh, nhưng bị quy tắc tại khu vực thần trúc áp chế xuống gần Thiên Thần cảnh.","detail":"Khôi lỗi mang tàn niệm của sinh linh đến từ thế giới bờ bên kia, từng theo một Bất Hủ giả tới nơi này rồi chết. Thân thể không lẫn tạp chất, toàn bộ được luyện từ Hắc Ám tiên kim và lưu giữ dấu vết đại đạo.","capNhatToi":"@c1233","tabs":{"tienTrinh":[{"chuong":"@c1233","loai":"xuất hiện","importance":"normal","giaiDoan":"Trấn giữ đỉnh núi","text":"Khôi lỗi Hắc Ám tiên kim xuất hiện trên đỉnh núi và để lại tàn niệm tiết lộ lai lịch từ thế giới bờ bên kia.","phamCap":"Không rõ","anchor":"toàn thân không hề có một chút tạp chất, toàn bộ là Hắc Ám tiên kim"}]},"nguon":["@c1233"]},{"id":"tang-da-xanh-ben-ao-than-truc","name":"Tảng đá xanh bên ao thần trúc","cn":"","category":"khac","categoryLabel":"Bia khắc","phamCap":"Không rõ","soHuu":[],"trangThai":"Còn lưu chữ và dấu ấn","blurb":"Tảng đá xanh đặt cạnh ao thần dịch, trên mặt có tiên văn cổ đại và dấu ấn của Hoàng tộc Dị Vực.","detail":"Bia ghi nhận một người trẻ tuổi Hoàng tộc Dị Vực từng vượt cửa ải vào cuối kỷ nguyên trước, lấy thần dịch luyện thể và lưu lại hình ảnh trong dấu ấn.","hinhDang":"Tảng đá xanh đặt cạnh ao thần dịch.","congNang":["Lưu tiên văn cổ đại.","Lưu dấu ấn hình ảnh của người trẻ tuổi Hoàng tộc Dị Vực."],"dacDiem":"Nét chữ cuối nguệch ngoạc và yếu ớt, phản ánh tình cảnh nguy hiểm của người để lại dấu tích.","capNhatToi":"@c1234","tabs":{"tienTrinh":[{"chuong":"@c1234","loai":"xuất hiện","importance":"normal","giaiDoan":"Phát hiện dấu tích Dị Vực","text":"Thạch Hạo phát hiện tiên văn và dấu ấn Hoàng tộc Dị Vực trên tảng đá xanh.","anchor":"mặt trên có một nhóm mơ hồ tự, lấy tiên văn tự cổ đại khắc","phamCap":"Không rõ"}]},"nguon":["@c1234"]},{"id":"hac-am-tien-kim","name":"Hắc Ám tiên kim","cn":"","category":"nguyen-lieu","categoryLabel":"Tiên kim","phamCap":"Vật liệu luyện binh của Chân Tiên","soHuu":[],"trangThai":"Được dùng cấu thành con rối","blurb":"Một loại tiên kim mang thuộc tính Tiên Đạo, có độ cứng vượt xa thân thể huyết nhục.","detail":"Hắc Ám tiên kim cấu thành thân thể con rối trấn giữ cửa ải. Vật liệu này có thể hóa lỏng, tái tổ hợp và tiếp tục chiến đấu sau khi hình thể ban đầu bị phá vỡ.","phanLoaiPhu":"Vật liệu luyện binh","vatLieu":"Hắc Ám tiên kim","uyLuc":"Thân thể cấu thành từ vật liệu này có độ cứng vượt xa huyết nhục.","dacDiem":"Mang thuộc tính Tiên Đạo, có thể hóa lỏng rồi tái tổ hợp.","congNang":["Dùng làm vật liệu luyện binh của Chân Tiên.","Cấu thành con rối có khả năng hóa lỏng và tái tổ hợp."],"capNhatToi":"@c1234","tabs":{"tienTrinh":[{"chuong":"@c1234","loai":"dùng","importance":"normal","giaiDoan":"Thân thể con rối","text":"Thân thể Hắc Ám tiên kim nhân hóa thành chất lỏng rồi tái tổ hợp để tiếp tục chiến đấu.","anchor":"Nó là Chân Tiên luyện binh vật liệu, tự có Tiên Đạo thuộc tính","phamCap":"Vật liệu luyện binh của Chân Tiên"}]},"nguon":["@c1234"]},{"id":"than-dich-ich-ta-than-truc","name":"Thần dịch Ích Tà Thần Trúc","cn":"","aliases":["Thần dịch trừ tà thần trúc","Chất lỏng Ích Tà Thần Trúc","Thần dịch trắng của Ích Tà Thần Trúc"],"category":"dan-duoc","categoryLabel":"Thần dịch","phamCap":"Không rõ","soHuu":[],"trangThai":"Đang tồn tại trong thần trì Ích Tà Thần Trúc","blurb":"Chất lỏng trắng thơm nồng do Ích Tà Thần Trúc tiết ra, có khả năng chữa thương và thúc đẩy thể chất tiến hóa.","detail":"Thần dịch nhanh chóng chữa các vết nứt ở bụng Thạch Hạo, rèn luyện xương, dung hợp với cốt tủy và thúc đẩy thể phách biến đổi. Khả năng hồi phục của nó giúp Thạch Hạo chịu đựng nhiều lần thử nghiệm sinh tử cùng sự phá hủy liên tục của thiên phạt.","phanLoaiPhu":"Thần dịch chữa thương và luyện thể","hinhDang":"Chất lỏng trắng","nguonGoc":"Tiết ra từ các lỗ ở đốt Ích Tà Thần Trúc và tích tụ trong thần trì","uyLuc":"Có thể chữa xương thịt bị phá hủy, dung hợp cốt tủy và thúc đẩy thể chất tiến hóa.","dacDiem":"Trắng noãn, tỏa hương thơm nồng và chảy ra nhiều hơn khi Thạch Hạo bị thiên phạt đánh nát thân thể.","congNang":["Chữa lành các vết nứt và thương tổn trên thân thể.","Rèn luyện xương và dung hợp với cốt tủy.","Thúc đẩy thể chất tiến hóa theo chiều hướng tốt."],"chuSoHuu":[],"capNhatToi":"@c1235","tabs":{"tienTrinh":[{"chuong":"@c1235","loai":"dùng","importance":"normal","giaiDoan":"Chữa thương và luyện xương","text":"Thần dịch chữa thương cho Thạch Hạo trong quá trình thử nghiệm sinh tử, rồi tiếp tục thấm vào xương vỡ và cốt tủy khi thiên phạt giáng xuống.","anchor":"thân thể của hắn đang phát sinh kịch liệt biến hóa, ở hướng về phương diện tốt cực tốc phát triển","phamCap":"Không rõ"}]},"nguon":["@c1235"]},{"id":"bi-bao-thien-than-cap-thu-man-sang","name":"Bí bảo Thiên Thần cấp thử màn sáng","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Thiên Thần cấp","soHuu":["Thạch Hạo"],"trangThai":"Hư hủy","blurb":"Một pháp khí cấp Thiên Thần được Thạch Hạo dùng để thăm dò màn sáng quanh thung lũng thi thể.","detail":"Bí bảo vừa tiến vào màn sáng đã sụp đổ và tan thành mảnh vụn dưới lực lượng thần thánh, qua đó cho thấy lớp bảo hộ có thể hủy diệt một Thiên Thần thông thường.","phanLoaiPhu":"Bí bảo thăm dò","uyLuc":"Bản thân đạt cấp Thiên Thần nhưng không chống nổi màn sáng thần thánh.","dacDiem":"Bị phá hủy ngay khi vừa tiến vào màn sáng.","chuHienThoi":"Không còn","capNhatToi":"@c1237","congNang":["Được dùng để thăm dò mức nguy hiểm của màn sáng quanh thung lũng thi thể."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1237","denChuong":"@c1237","cachCoDuoc":"Không rõ","trangThai":"Bị phá hủy khi thăm dò màn sáng"}],"tabs":{"tienTrinh":[{"chuong":"@c1237","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Bị phá hủy","text":"Thạch Hạo phóng bí bảo vào màn sáng để thăm dò, nhưng pháp khí lập tức sụp đổ.","anchor":"cái này bảo cụ mới vọt vào màn ánh sáng bên trong liền sụp đổ rồi","phamCap":"Thiên Thần cấp"}]},"nguon":["@c1237"]},{"id":"to-trang-cua-hoang-tuyen-trung","name":"Tơ trắng của Hoàng Tuyền Trùng","cn":"","category":"nguyen-lieu","categoryLabel":"Vật chất do sinh linh tạo ra","phamCap":"Không rõ","soHuu":[],"trangThai":"Không rõ","blurb":"Loại tơ trắng cực kỳ cứng cỏi do Hoàng Tuyền Trùng phun ra để kết lưới trói mục tiêu.","detail":"Ba Hoàng Tuyền Trùng phun tơ kết thành lưới, trói những chim thần do Pháp môn Côn Bằng diễn hóa. Thạch Hạo dùng sức kéo mạnh cũng chỉ làm đứt được hai sợi.","phanLoaiPhu":"Tơ trùng","hinhDang":"Những sợi tơ màu trắng có thể đan thành lưới.","uyLuc":"Có thể trói và luyện hóa mục tiêu bị mắc trong lưới.","dacDiem":"Tơ rất cứng cỏi và khó bị xé đứt bằng sức mạnh thông thường.","congNang":["Kết thành lưới để trói và luyện hóa mục tiêu."],"capNhatToi":"@c1238","tabs":{"tienTrinh":[{"chuong":"@c1238","loai":"xuất hiện","importance":"normal","giaiDoan":"Kết lưới trói chim thần","text":"Ba Hoàng Tuyền Trùng phun tơ trắng kết lưới, trói các chim thần do Pháp môn Côn Bằng diễn hóa và chống lại sức kéo của Thạch Hạo.","anchor":"phát hiện dị thường cứng cỏi, khó có thể xả đoạn"}]},"nguon":["@c1238"]},{"id":"luan-ban-chuyen-sinh","name":"Luân Bàn chuyển sinh","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm chuyển sinh","phamCap":"Không rõ","soHuu":[],"trangThai":"Không rõ","blurb":"Luân Bàn xuất hiện trong trải nghiệm Địa Ngục, mang theo Luân Hồi chi lực và đưa linh hồn sang những thế giới chuyển sinh.","detail":"Vật phẩm hiện lên từ biển nham thạch, được chia thành nhiều khu vực tượng trưng cho những nơi chuyển sinh khác nhau. Nó hút hồn hỏa của Thạch Hạo vào hắc động và đưa hắn bước vào các đời sống mới.","congNang":["Hút linh hồn vào hắc động và đưa linh hồn chuyển sinh sang thế giới khác."],"uyLuc":"Có thể đưa hồn hỏa của Thạch Hạo bước vào một vòng sinh, lão, bệnh, tử hoàn chỉnh.","dacDiem":"Mang Luân Hồi chi lực và được phân chia thành nhiều khu vực chuyển sinh.","dinhDanh":"goc","capNhatToi":"@c1241","tabs":{"tienTrinh":[{"chuong":"@c1241","loai":"xuất hiện","importance":"normal","giaiDoan":"Đưa Thạch Hạo chuyển sinh","text":"Luân Bàn xuất hiện từ biển nham thạch, hút hồn hỏa của Thạch Hạo vào hắc động và mở đầu cho nhiều đời chuyển thế.","anchor":"Sau đó, một cái Luân Bàn xuất hiện, tràn ngập Luân Hồi chi lực"}]},"nguon":["@c1241"]},{"id":"bon-dao-luan-hoi-an","name":"Bốn đạo Luân Hồi Ấn","cn":"","aliases":[],"category":"khac","categoryLabel":"Ấn ký","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Hiện hữu trong lòng bàn tay Thạch Hạo","blurb":"Bốn đạo Luân Hồi Ấn là bốn ấn ký nhỏ xuất hiện trong lòng bàn tay Thạch Hạo sau khi hắn tỉnh khỏi trải nghiệm Hoàng Tuyền. Mỗi đạo ấn tương ứng với một đời chuyển sinh, làm chứng cho tổng cộng bốn lần chuyển sinh mà hắn đã trải qua.","detail":"Sau trải nghiệm Hoàng Tuyền, Thạch Hạo phát hiện trong lòng bàn tay có bốn Luân Hồi Ấn, số lượng tương ứng chính xác với bốn đời chuyển sinh. Cổ thư của kỷ nguyên hiện tại và thiên thư bằng ngọc thời Tiên Cổ đều xem Luân Hồi Ấn là chứng cứ về khả năng chuyển thế của một số tuyệt đại thiên kiêu; tuy nhiên, sự xuất hiện của bốn ấn ký trên tay Thạch Hạo vẫn chưa đủ để phân định tính chất chân thực của trải nghiệm Hoàng Tuyền. @c1241","hinhDang":"Bốn đồ án rất nhỏ nhưng chân thực trong lòng bàn tay.","congNang":["Làm chứng cho bốn lần chuyển sinh mà Thạch Hạo đã trải qua trong trải nghiệm Hoàng Tuyền. @c1241"],"dacDiem":"Gồm bốn ấn ký nhỏ nằm trong lòng bàn tay Thạch Hạo; mỗi đạo ấn tương ứng với một đời chuyển sinh trong trải nghiệm Hoàng Tuyền.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1241","denChuong":"","cachCoDuoc":"Xuất hiện sau khi tỉnh khỏi bốn đời chuyển sinh do Hoàng Tuyền quả tạo ra.","trangThai":"dang-co"}],"dinhDanh":"goc","capNhatToi":"@c1241","tabs":{"tienTrinh":[{"chuong":"@c1241","loai":"xuất hiện","importance":"major","giaiDoan":"Bốn ấn hiện hình","text":"Sau khi tỉnh khỏi trải nghiệm Hoàng Tuyền, Thạch Hạo phát hiện bốn Luân Hồi Ấn trong lòng bàn tay, tương ứng với bốn đời chuyển sinh.","anchor":"Hiện tại, lòng bàn tay của hắn trong tổng cộng có bốn đạo, mà hắn ở đằng kia chân thật trong mộng cảnh, từng bốn thế Luân Hồi chuyển sinh."}]},"nguon":["@c1241"]},{"id":"to-giay-vang-chu-phong","name":"Tờ giấy vàng chữ Phong","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo phong ấn","phanLoaiPhu":"Tờ giấy cổ khắc Tiên văn","phamCap":"Không rõ","soHuu":[],"trangThai":"Đang duy trì phong ấn","blurb":"Tờ giấy cổ ố vàng khắc Tiên văn “Phong”, dùng để trấn áp toàn bộ biển anh linh tại Tiên khâu.","detail":"Tờ giấy trải qua thời gian dài vẫn ngăn vô số anh linh vượt qua ranh giới, kể cả những anh linh màu vàng mang Tiên Đạo khí tức. Phong ấn của nó có thể được người hữu duyên đời sau tháo bỏ.","hinhDang":"Một tờ giấy cổ ố vàng khắc Tiên văn “Phong”.","uyLuc":"Có thể trấn áp vô số anh linh trong cổ táng địa Tiên khâu.","dacDiem":"Duy trì hiệu lực qua thời gian dài và có thể được hậu thế giải phong.","congNang":["Duy trì phong ấn Tiên khâu và ngăn biển anh linh vượt giới."],"chuSoHuu":[],"capNhatToi":"@c1242","tabs":{"tienTrinh":[{"chuong":"@c1242","loai":"xuất hiện","importance":"normal","giaiDoan":"Trấn áp Tiên khâu","phamCap":"Không rõ","text":"Tờ giấy vàng khắc chữ Phong được phát hiện đang duy trì phong ấn đối với toàn bộ biển anh linh.","anchor":"dán vào một tấm giấy ố vàng, sinh diện khắc một cái Tiên văn tự cổ đại: Phong"}]},"nguon":["@c1242"]},{"id":"dai-dinh-vuot-dong-thoi-gian","name":"Đại đỉnh vượt dòng thời gian","cn":"","aliases":["Chiếc đỉnh cửu sắc đẫm máu"],"category":"phap-bao","categoryLabel":"Đỉnh thần bí","phamCap":"Không rõ","soHuu":[],"trangThai":"Không rõ","blurb":"Một chiếc đỉnh cửu sắc đẫm máu xuất hiện trong trải nghiệm luân hồi của Thái Âm Ngọc Thỏ. Nó vượt khỏi ràng buộc của thời gian và càn khôn giữa những cảnh đại chiến.","detail":"Chiếc đỉnh được hỗn đúc từ nhiều loại Tiên kim, tỏa cửu sắc hào quang và có Vạn Vật Mẫu khí lưu chuyển. Thái Âm Ngọc Thỏ nhìn thấy một bóng người quen thuộc ở bên trong nhưng chưa nhận ra danh tính.","phanLoaiPhu":"Đỉnh","hinhDang":"Chiếc đỉnh tỏa cửu sắc hào quang và dính đầy máu.","vatLieu":"Nhiều loại Tiên kim","dacDiem":"Có Vạn Vật Mẫu khí lưu chuyển, vượt khỏi ràng buộc thời gian và càn khôn.","congNang":["Vượt khỏi ràng buộc của thời gian và càn khôn."],"dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1243","loai":"xuất hiện","importance":"normal","giaiDoan":"Hiện trong trải nghiệm luân hồi","text":"Thái Âm Ngọc Thỏ nhìn thấy chiếc đỉnh cửu sắc đẫm máu vượt qua thời gian và càn khôn giữa những cảnh đại chiến.","anchor":"lấy các loại Tiên kim hỗn đúc mà thành, lóng lánh cửu sắc hào quang, còn có Vạn Vật Mẫu khí lưu chuyển"}]},"capNhatToi":"@c1243","nguon":["@c1243"]},{"id":"chuong-lon-cua-nam-tu-mo-ho","name":"Chuông lớn của nam tử mơ hồ","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Ba nam tử mơ hồ điều động đại đỉnh"],"trangThai":"Không rõ","blurb":"Chiếc chuông lớn do một trong ba nam tử mơ hồ sử dụng khi hộ tống đại đỉnh vượt dòng thời gian.","detail":"Một nam tử đứng trên chuông và thúc phát tiếng chuông, tạo ra gợn sóng thời gian mãnh liệt truyền vào đại đỉnh đang tiến về phía trước.","congNang":["Phát ra tiếng chuông và gợn sóng thời gian để hỗ trợ đại đỉnh tiến qua dòng thời gian."],"dacDiem":"Khi được thúc phát, chuông làm thời gian nổi lên những gợn sóng mênh mông.","chuSoHuu":[{"ten":"Ba nam tử mơ hồ điều động đại đỉnh","tuChuong":"@c1244","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sử dụng"}],"capNhatToi":"@c1244","tabs":{"tienTrinh":[{"chuong":"@c1244","loai":"dùng","importance":"normal","giaiDoan":"Hộ tống đại đỉnh","text":"Một nam tử mơ hồ đứng trên chuông, thúc phát tiếng chuông cùng gợn sóng thời gian truyền vào đại đỉnh.","anchor":"thúc ra tiếng chuông, thời gian liên y mênh mông"}]},"nguon":["@c1244"]},{"id":"tien-huyet-tinh-sa","name":"Tiên huyết tinh sa","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Khoáng liệu luyện thể","phamCap":"","soHuu":[],"trangThai":"Được dùng luyện thể","blurb":"Khoáng liệu hình thành từ mảnh sao từng bị Tiên huyết nhuộm, còn lưu lại tinh hoa và nhiệt độ rất cao.","detail":"Đại trưởng lão nung chảy Tiên huyết tinh sa thành chất lỏng đỏ thắm rồi tưới lên Thạch Hạo để chém luyện cơ thể. Vật liệu đã mất phần lớn sát khí của Tiên huyết nhưng phần tinh hoa còn lại vẫn mang nhiệt độ cực cao.","phanLoaiPhu":"Khoáng liệu","nguonGoc":"Tinh hoa từ mảnh sao từng bị Tiên huyết nhuộm.","congNang":["Nung chảy và tưới lên thân thể để hỗ trợ rèn luyện thể phách."],"dacDiem":"Có nhiệt độ cực cao nhưng đã mất phần lớn sát khí nguyên bản của Tiên huyết.","tabs":{"tienTrinh":[{"chuong":"@c1245","loai":"dùng","importance":"normal","giaiDoan":"Rèn thể trong dược trì","text":"Đại trưởng lão nung chảy Tiên huyết tinh sa rồi dùng chất lỏng đỏ thắm tưới lên Thạch Hạo để tôi luyện thân thể.","anchor":"này sa xác thực là lấy Tiên dòng máu nhuộm dần mà thành"}]},"capNhatToi":"@c1245","nguon":["@c1245"]},{"id":"la-thien-than-thu","name":"Lá Thiên Thần thụ","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Thần dược","phamCap":"","soHuu":[],"trangThai":"Được dùng trong dược trì","blurb":"Dược liệu quý hiếm lấy từ Thiên Thần thụ, được dùng trong dược trì luyện thể của Thạch Hạo.","detail":"Lá Thiên Thần thụ là một trong những thần dược giá trị liên thành được đưa vào dược trì thứ nhất để phối hợp tôi luyện thân thể Thạch Hạo.","phanLoaiPhu":"Lá thần dược","nguonGoc":"Thiên Thần thụ","congNang":["Phối hợp các dược liệu và khoáng liệu khác trong dược trì luyện thể."],"tabs":{"tienTrinh":[{"chuong":"@c1245","loai":"dùng","importance":"normal","giaiDoan":"Phối chế dược trì","text":"Lá Thiên Thần thụ được đưa vào dược trì thứ nhất để hỗ trợ tôi luyện thể phách Thạch Hạo.","anchor":"ở trong tất cả đều là các loại hi thế thần dược cùng khoáng liêu, nói thí dụ như Thiên Thần thụ lá cây"}]},"capNhatToi":"@c1245","nguon":["@c1245"]},{"id":"bach-ngoc-hat","name":"Bạch ngọc hạt","cn":"","aliases":[],"category":"khac","categoryLabel":"Độc trùng luyện thể","phamCap":"Nhiều cá thể đạt Thần cấp","soHuu":[],"trangThai":"Được dùng trong dược trì","blurb":"Loài bọ cạp trắng có huyết thống cao quý, quý giá và hiếm thấy, được dùng để lấy độc rèn thân.","detail":"Bạch ngọc hạt phủ kín thân thể Thạch Hạo trong dược trì thứ hai, dùng đuôi đâm xuyên da thịt và truyền kịch độc. Thạch Hạo chủ động không chống cự để độc lực tham gia quá trình tái luyện huyết, gân và xương.","phanLoaiPhu":"Độc trùng","hinhDang":"Bọ cạp màu trắng","dacDiem":"Có huyết thống cao quý, quý giá và hiếm thấy; nhiều cá thể đạt Thần cấp.","congNang":["Truyền kịch độc vào thân thể để hỗ trợ rèn huyết, gân và xương."],"tabs":{"tienTrinh":[{"chuong":"@c1245","loai":"dùng","importance":"normal","giaiDoan":"Dược trì độc trùng","text":"Bạch ngọc hạt phủ kín người Thạch Hạo, dùng đuôi đâm vào da thịt và truyền độc để rèn luyện thân thể.","anchor":"đây chính là bạch ngọc hạt, quý giá mà hiếm thấy, đều là huyết thống cao quý hi hữu sinh vật"}]},"capNhatToi":"@c1245","nguon":["@c1245"]},{"id":"ret-vang-co-canh","name":"Rết vàng có cánh","cn":"","aliases":[],"category":"khac","categoryLabel":"Độc trùng luyện thể","phamCap":"","soHuu":[],"trangThai":"Được dùng trong dược trì","blurb":"Loài rết màu vàng có cánh được dùng sau bạch ngọc hạt trong quá trình lấy độc rèn thân.","detail":"Một lượng lớn rết vàng có cánh được đổ lên toàn thân Thạch Hạo trong dược trì độc trùng, tiếp tục gây đau đớn và tôi luyện thể phách của hắn.","phanLoaiPhu":"Độc trùng","hinhDang":"Rết màu vàng có cánh","congNang":["Dùng độc lực và sự đâm cắn để hỗ trợ rèn luyện thân thể."],"tabs":{"tienTrinh":[{"chuong":"@c1245","loai":"dùng","importance":"normal","giaiDoan":"Dược trì độc trùng","text":"Rết vàng có cánh được đổ kín lên người Thạch Hạo để tiếp tục quá trình dùng độc tôi luyện thân thể.","anchor":"bởi vì lít nha lít nhít rết xuất hiện, đều là màu vàng, trường cánh"}]},"capNhatToi":"@c1245","nguon":["@c1245"]},{"id":"muoi-loai-doc-trung-luyen-the","name":"Mười loại độc trùng luyện thể","cn":"","aliases":[],"category":"khac","categoryLabel":"Bộ độc trùng","phamCap":"Gồm nhiều độc trùng Thần cấp","soHuu":[],"trangThai":"Được dùng luyện thể","blurb":"Bộ mười loại độc trùng đáng sợ được sử dụng liên tục trong mười ngày mười đêm để tôi luyện Thạch Hạo.","detail":"Mười loại độc trùng được lần lượt dùng trong dược trì, phối hợp với thần dược để rèn gân, xương, da và huyết của Thạch Hạo. Quá trình kéo dài mười ngày mười đêm và đem lại hiệu quả tăng cường thể chất rõ rệt.","phanLoaiPhu":"Bộ độc trùng luyện thể","laBo":true,"congNang":["Dùng độc lực của nhiều loài để rèn gân, xương, da và huyết."],"uyLuc":"Khiến người chịu luyện trải qua đau đớn dữ dội liên tục suốt mười ngày mười đêm.","tabs":{"tienTrinh":[{"chuong":"@c1245","loai":"dùng","importance":"normal","giaiDoan":"Mười ngày luyện độc","text":"Thạch Hạo chịu mười loại độc trùng tôi luyện liên tục trong mười ngày mười đêm để tăng cường toàn diện thể phách.","anchor":"ròng rã mười ngày mười đêm, Thạch Hạo bị mười loại đáng sợ nhất độc trùng dằn vặt"}]},"capNhatToi":"@c1245","nguon":["@c1245"]},{"id":"xich-kim-gian-muoi-tam-tiet","name":"Xích Kim giản mười tám tiết","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Hồn khí","phanLoaiPhu":"Hồn khí","phamCap":"Không rõ","soHuu":["Đại trưởng lão"],"chuSoHuu":[{"ten":"Đại trưởng lão","tuChuong":"@c1246","denChuong":"","cachCoDuoc":"","trangThai":"đang sở hữu"}],"hinhDang":"Một cây giản đỏ rực gồm mười tám tiết.","congNang":["Chuyên công kích linh hồn và giết nguyên thần."],"uyLuc":"Có thể trực tiếp đánh vào nguyên thần của mục tiêu.","dacDiem":"Đỏ rực như bàn ủi và có cấu tạo mười tám tiết.","chuHienThoi":"Đại trưởng lão","trangThai":"đang sử dụng","capNhatToi":"@c1246","blurb":"Hồn khí hình giản gồm mười tám tiết, chuyên dùng để công kích linh hồn và nguyên thần.","detail":"Đại trưởng lão dùng Xích Kim giản mười tám tiết liên tục công kích nguyên thần Thạch Hạo. Thạch Hạo lấy nguyên thần tay không chống đỡ để rèn khả năng kháng lại công kích Hồn khí.","tabs":{"tienTrinh":[{"chuong":"@c1246","loai":"dùng","importance":"normal","giaiDoan":"Tôi luyện nguyên thần","text":"Đại trưởng lão dùng Xích Kim giản mười tám tiết công kích trực tiếp nguyên thần Thạch Hạo trong quá trình bế quan.","anchor":"hình như Xích Kim giản, cùng sở hữu mười tám cái tiết, chuyên đánh người linh hồn","phamCap":"Không rõ"}]},"nguon":["@c1246"]},{"id":"lam-sac-chien-mau-hon-khi","name":"Lam sắc chiến mâu hồn khí","cn":"","category":"phap-bao","categoryLabel":"Hồn khí","phamCap":"Có thể tru diệt Thiên Thần","soHuu":[],"trangThai":"nguyên vẹn","blurb":"Hồn khí chuyên chém giết nguyên thần, được dùng để kiểm nghiệm Thạch Hạo.","detail":"Lam sắc chiến mâu có uy lực đủ dễ dàng tru diệt Thiên Thần và chuyên tấn công nguyên thần, nhưng bị quyền ấn từ nguyên thần Thạch Hạo đánh bay.","hinhDang":"Chiến mâu màu lam","uyLuc":"Có thể dễ dàng tru diệt Thiên Thần.","dacDiem":"Chuyên dùng để chém giết nguyên thần.","congNang":["Chém giết nguyên thần @c1247"],"tabs":{"tienTrinh":[{"chuong":"@c1247","loai":"dùng","importance":"normal","giaiDoan":"Kiểm nghiệm nguyên thần","text":"Lam sắc chiến mâu được dùng để tấn công nguyên thần Thạch Hạo nhưng bị quyền ấn đánh bay.","anchor":"thứ này chính là chuyên vì giết nguyên thần mà diêu ra","phamCap":"Có thể tru diệt Thiên Thần"}]},"capNhatToi":"@c1247","nguon":["@c1247"]},{"id":"ong-anh-tim-truong-dao-hon-khi","name":"Óng ánh tím trường đao hồn khí","cn":"","category":"phap-bao","categoryLabel":"Hồn khí","phamCap":"Đủ sức đe dọa nguyên thần Thiên Thần cực cảnh","soHuu":[],"trangThai":"nguyên vẹn","blurb":"Trường đao hồn khí được dùng để chém thẳng vào thần hồn Thạch Hạo.","detail":"Hồn khí hình trường đao màu tím có uy lực khiến Đại trưởng lão lo lắng, nhưng không thể chém vỡ nguyên thần đã hóa thành kiếm thần của Thạch Hạo.","hinhDang":"Trường đao óng ánh màu tím","uyLuc":"Có thể trực tiếp đe dọa nguyên thần Thạch Hạo.","dacDiem":"Chuyên chém giết thần hồn.","congNang":["Chém giết thần hồn @c1247"],"tabs":{"tienTrinh":[{"chuong":"@c1247","loai":"dùng","importance":"normal","giaiDoan":"Kiểm nghiệm nguyên thần","text":"Trường đao hồn khí chém thẳng vào thần hồn Thạch Hạo nhưng không phá được nguyên thần đã hóa thành kiếm thần.","anchor":"Lại một thanh hồn khí, óng ánh tím trường đao chém thẳng hư không, chém giết thần hồn","phamCap":"Đủ sức đe dọa nguyên thần Thiên Thần cực cảnh"}]},"capNhatToi":"@c1247","nguon":["@c1247"]},{"id":"bu-thien-duoc","name":"Bù thiên dược","cn":"","category":"khac","categoryLabel":"Vật chất chữa lành","phamCap":"","soHuu":["Đại trưởng lão"],"trangThai":"đã dùng","blurb":"Vật chất chữa lành do Đại trưởng lão cầu được từ Bổ Thiên Đạo.","detail":"Bù thiên dược là chất lỏng óng ánh có thể khép kín hoàn toàn vết cắt trên kỳ dị hạt giống, không để tinh hoa thất thoát và còn tẩm bổ hạt giống.","hinhDang":"Chất lỏng óng ánh","nguonGoc":"Được Đại trưởng lão cầu từ Bổ Thiên Đạo.","dacDiem":"Khép kín vật thể mà không để lại tỳ vết.","congNang":["Khép kín vết cắt trên kỳ dị hạt giống @c1247","Ngăn tinh hoa trong hạt giống thất thoát @c1247","Tẩm bổ kỳ dị hạt giống @c1247"],"chuSoHuu":[{"ten":"Đại trưởng lão","tuChuong":"@c1247","denChuong":"@c1247","cachCoDuoc":"Cầu từ Bổ Thiên Đạo","trangThai":"đã sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1247","loai":"dùng","importance":"normal","giaiDoan":"Phong kín hạt giống","text":"Đại trưởng lão dùng Bù thiên dược chữa lành hoàn toàn vết cắt trên kỳ dị hạt giống sau khi Thạch Hạo tiến vào.","anchor":"Đây là bù thiên dược, là ta từ bù thiên đạo cầu lấy mà đến","phamCap":""}]},"capNhatToi":"@c1247","nguon":["@c1247"]},{"id":"hong-mong-tu-khi-hat-giong","name":"Hồng Mông Tử Khí hạt giống","cn":"","aliases":["Hồng Mông Tử loại"],"category":"khac","categoryLabel":"Vô thượng cổ chủng","phamCap":"Vô thượng cổ chủng","soHuu":["Người dung hợp Hồng Mông Tử loại"],"trangThai":"đã dung hợp","blurb":"Hồng Mông Tử Khí hạt giống là vô thượng cổ chủng từng rực rỡ trong Tiên Cổ kỷ nguyên. Tại Tiên viện, một người chưa lộ danh tính đã dung hợp thành công hạt giống này, thực hiện cực điểm thăng hoa và trở thành chí tôn trẻ tuổi có tiềm lực quét ngang Cửu Thiên Thập Địa.","detail":"Hồng Mông Tử Khí hạt giống từng rực rỡ trong Tiên Cổ kỷ nguyên. Đến mốc mới nhất, nó được một người chưa lộ danh tính tại Tiên viện dung hợp thành công, giúp người này thực hiện cực điểm thăng hoa; quá trình dung hợp dẫn phát tử khí cùng khói tím Hồng Mông trải dài ba vạn dặm.","nguonGoc":"Từng rực rỡ trong Tiên Cổ kỷ nguyên.","uyLuc":"Tạo nên một chí tôn trẻ tuổi có tiềm lực quét ngang Cửu Thiên Thập Địa.","dacDiem":"Khi được dung hợp thành công sẽ dẫn phát tử khí và khói tím Hồng Mông quy mô lớn, từng trải dài ba vạn dặm.","congNang":["Giúp sinh linh dung hợp thực hiện cực điểm thăng hoa @c1247"],"chuHienThoi":"Người dung hợp Hồng Mông Tử loại","chuSoHuu":[{"ten":"Người dung hợp Hồng Mông Tử loại","tuChuong":"@c1247","denChuong":"","cachCoDuoc":"Dung hợp thành công tại Tiên viện","trangThai":"đã dung hợp"}],"tabs":{"tienTrinh":[{"chuong":"@c1247","loai":"đổi chủ","importance":"major","giaiDoan":"Dung hợp thành công","text":"Một người chưa lộ danh tính tại Tiên viện dung hợp thành công Hồng Mông Tử Khí hạt giống và thực hiện cực điểm thăng hoa.","anchor":"đây là khói tím Hồng Mông, là trong truyền thuyết vô thượng cổ chủng","phamCap":"Vô thượng cổ chủng"}]},"capNhatToi":"@c1247","nguon":["@c1247"]},{"id":"thien-dia-ky-di-hat-giong","name":"Thiên Địa kỳ dị hạt giống","cn":"","aliases":["Kỳ dị hạt giống","Hạt giống kỳ dị chứa nữ sinh linh","Hạt giống ngộ đạo kỳ dị"],"category":"khac","categoryLabel":"Đạo chủng","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang thai nghén nữ sinh linh","blurb":"Thiên Địa kỳ dị hạt giống là một đạo chủng có thể biến đổi kích thước, bên trong chứa không gian rộng lớn, tràn ngập tiên quang và hỗn độn khí. Hạt giống cộng hưởng với các quy tắc thiên địa, giúp người ở bên trong tiếp xúc vạn đạo, đồng thời thai nghén một nữ sinh linh sống.","detail":"Không gian nội bộ của Thiên Địa kỳ dị hạt giống cộng hưởng với nhật nguyệt, sơn hà và chư thiên quy tắc, tạo thành môi trường để người tiến vào tiếp xúc, quan sát vạn đạo. Khi Thạch Hạo tiến vào và ổn định lại, hắn phát hiện thứ đang được thai nghén không phải Tiên kim hay vật chất Tiên Đạo vô tri, mà là một nữ sinh linh mạnh mẽ đang sống. @c1248","phanLoaiPhu":"Đạo chủng kỳ dị","hinhDang":"Có thể biến đổi kích thước","dacDiem":"Có không gian nội bộ rộng lớn, tràn ngập tiên quang và hỗn độn khí; bên trong đang thai nghén một nữ sinh linh sống.","congNang":["Có thể biến đổi kích thước.","Chứa một không gian nội bộ rộng lớn, tràn ngập tiên quang và hỗn độn khí.","Cộng hưởng với nhật nguyệt, sơn hà và chư thiên quy tắc, giúp người ở bên trong tiếp xúc và quan sát vạn đạo.","Thai nghén một nữ sinh linh sống. @c1248"],"chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1248","denChuong":"","cachCoDuoc":"Mang theo để hỗ trợ con đường lấy thân làm chủng","trangThai":"Đang sử dụng"}],"capNhatToi":"@c1248","tabs":{"tienTrinh":[{"chuong":"@c1248","loai":"khai phong","importance":"major","giaiDoan":"Phát hiện sinh linh bên trong","text":"Thạch Hạo tiến vào không gian nội bộ của hạt giống và phát hiện nó đang thai nghén một nữ sinh linh sống, đảo ngược phán đoán trước đó rằng bên trong là Tiên kim hoặc vật chất Tiên Đạo vô tri.","anchor":"Có thể hiện tại Thạch Hạo chân chính tiến vào, đồng thời ổn định lại sau, cảnh giác phát hiện, đó là một cái sinh linh, là sống sót sinh vật mạnh mẽ!","phamCap":"Không rõ"}]},"nguon":["@c1248"]},{"id":"hoan-my-dao-chung","name":"Hoàn mỹ đạo chủng","cn":"","aliases":[],"category":"khac","categoryLabel":"Đạo chủng","phamCap":"Hoàn mỹ","soHuu":[],"trangThai":"Được các đạo thống coi trọng","blurb":"Đạo chủng hoàn mỹ là môi giới giúp người tu hành cảm nhận bản chất thế giới và dung hợp với đại thiên địa. Nó có thể gắn bó lâu dài với chủ nhân trên con đường tu đạo.","detail":"Người dung hợp hoàn mỹ đạo chủng có thêm cơ hội nhìn thấy thiên địa chí lý và hòa hợp với đại thiên địa. Quan niệm từ kỷ nguyên trước xem việc sở hữu loại hạt giống này như nắm giữ vận mệnh của chính mình.","phanLoaiPhu":"Môi giới tu hành","dacDiem":"Có thể vĩnh cửu hợp nhất với người tu hành.","congNang":["Hỗ trợ người tu hành cảm ngộ thiên địa chí lý và tăng cơ hội dung hợp với đại thiên địa."],"capNhatToi":"@c1248","tabs":{"tienTrinh":[{"chuong":"@c1248","loai":"nhắc tới","importance":"bridge","giaiDoan":"Giải thích giá trị","text":"Giá trị của hoàn mỹ đạo chủng được giải thích qua khả năng gắn bó với người tu hành và hỗ trợ họ cảm ngộ đại thiên địa.","anchor":"Nắm giữ một viên hoàn mỹ hạt giống liền bằng nắm giữ vận mạng mình, đây là trên một kỷ nguyên lời lẽ chí lý!","phamCap":"Hoàn mỹ"}]},"nguon":["@c1248"]},{"id":"thien-dia-thai-ban","name":"Thiên Địa Thai Bàn","cn":"","category":"khac","categoryLabel":"Kỳ vật tu hành","phamCap":"Tinh hoa của Thiên Địa kỳ dị hạt giống","soHuu":["Nữ nhân tóc dài trong hạt giống kỳ dị","Thạch Hạo"],"trangThai":"Được Thạch Hạo mượn tu hành","blurb":"Thiên Địa Thai Bàn là kỳ vật nằm tại trung tâm Thiên Địa kỳ dị hạt giống, đồng thời là phần tinh hoa của đạo chủng. Bảo vật có thể dẫn Chư Thiên vạn đạo hội tụ, trợ giúp người ngồi trên đó tu hành.","detail":"Thiên Địa Thai Bàn hiện thành một phiến đá cổ dài ba xích, nằm ở vị trí trung tâm bên trong Thiên Địa kỳ dị hạt giống và là phần tinh hoa của đạo chủng. Nữ Tiên Thai từng ngồi trên đó, sau nhường vị trí cho Thạch Hạo tu hành; khi hắn ngồi xuống, Chư Thiên vạn đạo lập tức hội tụ từ mọi phương, đồng thời vang lên tiếng kinh văn thần bí. @c1249","phanLoaiPhu":"Đạo chủng tinh hoa","hinhDang":"Phiến đá cổ dài ba xích","nguonGoc":"Tinh hoa của Thiên Địa kỳ dị hạt giống","congNang":["Dẫn Chư Thiên vạn đạo từ mọi phương hội tụ, bao phủ và trợ giúp người ngồi trên Thiên Địa Thai Bàn tu hành; trong quá trình đó còn có tiếng kinh văn thần bí vang lên. @c1249"],"dacDiem":"Hiện thành một phiến đá cổ dài ba xích, nằm tại trung tâm Thiên Địa kỳ dị hạt giống và là phần tinh hoa của đạo chủng.","chuHienThoi":"Nữ nhân tóc dài trong hạt giống kỳ dị","chuSoHuu":[{"ten":"Nữ nhân tóc dài trong hạt giống kỳ dị","tuChuong":"@c1249","denChuong":"","cachCoDuoc":"Gắn với nơi thai nghén của Tiên Thai","trangThai":"Chủ hiện thời"},{"ten":"Thạch Hạo","tuChuong":"@c1249","denChuong":"","cachCoDuoc":"Được cho mượn để tu hành","trangThai":"Đang mượn dùng"}],"tabs":{"tienTrinh":[{"chuong":"@c1249","loai":"đổi chủ","importance":"major","giaiDoan":"Cho Thạch Hạo mượn","text":"Nữ Tiên Thai cho Thạch Hạo ngồi lên Thiên Địa Thai Bàn để tu hành.","anchor":"Đây là cái này đạo chủng tinh hoa!","phamCap":"Tinh hoa của Thiên Địa kỳ dị hạt giống"}]},"capNhatToi":"@c1249","nguon":["@c1249"]},{"id":"phien-da-trung-tam-thien-dia-cuong-ron","name":"Phiến đá trung tâm thiên địa cuống rốn","cn":"","category":"khac","categoryLabel":"Vật phẩm thiên địa","phamCap":"Không rõ","soHuu":[],"trangThai":"Nguyên vẹn","blurb":"Phiến đá nằm tại trung tâm thiên địa cuống rốn, có khả năng ổn định quy tắc và che chở sinh linh ngồi trên nó. Vật này đã hóa giải sự cố sụp đổ không gian và chắn phần lớn đòn đánh từ binh khí đại đạo cho Thạch Hạo.","detail":"Phiến đá tạm thời công nhận Thạch Hạo như tiên thai đang được thiên địa thai nghén, nhờ đó che đậy thiên cơ và giúp hắn tiếp xúc với bí mật bản nguyên. Khi quy tắc tái tổ hợp mất kiểm soát, nó phát sáng để làm dịu biến động; lúc cây búa màu vàng giáng xuống, nó ngưng tụ thành tấm khiên đỡ phần lớn uy lực.","phanLoaiPhu":"Vật che chở tại thiên địa cuống rốn","hinhDang":"Phiến đá dùng làm chỗ ngồi tại vị trí trung tâm","nguonGoc":"Nằm ở trung tâm thiên địa cuống rốn bên trong hạt giống ngộ đạo.","uyLuc":"Có thể làm dịu quy tắc bạo động, hóa giải sụp đổ không gian và ngăn phần lớn công kích của binh khí đại đạo.","dacDiem":"Che đậy thiên cơ và tạm thời bảo vệ người được nó công nhận.","chuHienThoi":"","congNang":["Ổn định các quy tắc bị khuấy động trong quá trình tái tổ hợp.","Che chở người ngồi phía trên và che đậy thiên cơ.","Ngưng tụ tấm khiên để đỡ phần lớn công kích của cây búa đại đạo."],"chuSoHuu":[],"tabs":{"tienTrinh":[{"chuong":"@c1250","loai":"dùng","importance":"normal","giaiDoan":"Che chở Thạch Hạo","text":"Phiến đá ổn định biến động quy tắc, hóa giải sự cố sụp đổ không gian và ngưng tụ thành tấm khiên đỡ phần lớn công kích của cây búa đại đạo.","anchor":"dưới thân phiến đá phát sáng, vừa nãy ngưng tụ thành một cái tấm khiên, chặn lại rồi màu vàng cây búa phần lớn công kích","phamCap":"Không rõ"}]},"capNhatToi":"@c1250","nguon":["@c1250"]},{"id":"phien-da-bao-ho","name":"Phiến đá bảo hộ","cn":"","category":"khac","categoryLabel":"Vật phẩm bảo hộ","phamCap":"Chưa xác định","soHuu":[],"trangThai":"Đang phát huy tác dụng","blurb":"Phiến đá bảo vệ Thạch Hạo trước uy thế đại đạo và sự phá hủy của vô số quy tắc.","detail":"Phiến đá giữ cho sinh mệnh Thạch Hạo không bị dập tắt khi đại đạo và trật tự thần liên nghiền ép thân thể. Nó còn thúc đẩy máu thịt tan vỡ phục hồi và đánh thức hắn trước nguy cơ bị đốt thành than.","phanLoaiPhu":"Vật phẩm bảo hộ và phục hồi","nguonGoc":"Gắn với vị trí trung tâm bên trong Thiên Địa kỳ dị hạt giống.","uyLuc":"Có thể duy trì sinh mệnh và giúp thân thể Thạch Hạo phục hồi giữa sự phá hủy của vô số quy tắc.","dacDiem":"Liên tục phát huy tác dụng trong quá trình Thạch Hạo cầu tự thân đạo.","congNang":["Bảo hộ sinh mệnh trước uy thế đại đạo và sự phá hủy của quy tắc.","Thúc đẩy máu thịt tan vỡ phục hồi.","Đánh thức Thạch Hạo trước khi thân thể bị đốt thành than."],"chuSoHuu":[],"capNhatToi":"@c1251","tabs":{"tienTrinh":[{"chuong":"@c1251","loai":"dùng","importance":"normal","giaiDoan":"Bảo hộ ngộ đạo","phamCap":"Chưa xác định","text":"Phiến đá liên tục bảo vệ sinh mệnh và giúp thân thể Thạch Hạo phục hồi khi vô số quy tắc phá hủy máu thịt hắn.","anchor":"Đương nhiên, phiến đá phát huy tác dụng, trước sau bảo vệ Thạch Hạo, không cho hắn dập tắt."}]},"nguon":["@c1251"]},{"id":"doan-hoa-trong-dao-chi-ken","name":"Đoàn hỏa trong Đạo chi kén","cn":"","category":"khac","categoryLabel":"Dị hỏa","phamCap":"Chưa xác định","soHuu":[],"trangThai":"Đang nung đốt Đạo chi kén","blurb":"Một đoàn hỏa có thể hóa thành gương soi đạo tắc rồi biến thành tiên hỏa mang hỗn độn khí.","detail":"Đoàn hỏa lao ra từ Đạo chi kén, ban đầu hóa thành gương để soi sáng hàm nghĩa của vô tận đạo tắc. Sau đó nó hóa thành tiên hỏa phóng thích hỗn độn khí, nung chiếc kén đến cháy đen và dần phá diệt.","phanLoaiPhu":"Dị hỏa chưa rõ tên","hinhDang":"Có thể hóa thành gương và tiên hỏa","uyLuc":"Nung đốt Đạo chi kén đến cháy đen, khiến các sợi quy tắc siết vào thân thể rồi đứt ra.","dacDiem":"Khi hóa thành tiên hỏa có hỗn độn khí đi kèm.","congNang":["Hóa thành gương soi sáng hàm nghĩa đạo tắc.","Hóa thành tiên hỏa mang hỗn độn khí để nung đốt và phá hủy Đạo chi kén."],"chuSoHuu":[],"capNhatToi":"@c1251","tabs":{"tienTrinh":[{"chuong":"@c1251","loai":"dùng","importance":"normal","giaiDoan":"Nung đốt Đạo chi kén","phamCap":"Chưa xác định","text":"Đoàn hỏa hóa thành gương soi đạo tắc rồi biến thành tiên hỏa mang hỗn độn khí, nung chiếc kén đến cháy đen và phá diệt.","anchor":"đầu tiên là hóa thành một chiếc gương, rọi sáng ra vô tận đạo tắc hàm nghĩa, sau đó lại hóa thành tiên hỏa"}]},"nguon":["@c1251"]},{"id":"doan-hoa-than-bi","name":"Đoàn hỏa thần bí","cn":"","category":"khac","categoryLabel":"Dị hỏa","phamCap":"Không rõ","soHuu":[],"trangThai":"Hoạt động","blurb":"Dị hỏa được tiên khí cùng Hỗn Độn quang bao phủ, có thể thiêu xuyên quy tắc, chiếu rọi đại đạo và chủ động giao tiếp.","detail":"Đoàn hỏa đứng ngoài quan sát Thạch Hạo chống lại chư thiên vạn đạo hỏa rồi lên tiếng về giới hạn mở các cánh cửa trong cơ thể. Khi nhìn sâu vào hỏa quang, Thạch Hạo thấy vô số thân ảnh chiến đấu, huyết quang, tiếng kêu rên và hồn ảnh xung kích nhưng chưa thể xác định bản chất của nó.","phanLoaiPhu":"Dị hỏa có ý thức","hinhDang":"Một đoàn hỏa cao cỡ nắm đấm","dacDiem":"Được tiên khí cùng Hỗn Độn quang bao phủ, có thể giao tiếp và chứa những dị tượng khó giải thích.","uyLuc":"Có thể thiêu xuyên đạo kén do quy tắc tạo thành.","congNang":["Thiêu xuyên quy tắc.","Hóa thành tấm gương chiếu rọi đại đạo.","Giao tiếp và chỉ rõ giới hạn khai mở các cánh cửa trong cơ thể."],"tabs":{"tienTrinh":[{"chuong":"@c1252","loai":"xuất hiện","importance":"normal","giaiDoan":"Lộ tiếng nói và dị tượng","text":"Đoàn hỏa thần bí lên tiếng về giới hạn mở môn của Thạch Hạo, đồng thời để lộ vô số thân ảnh, huyết quang và hồn ảnh trong hỏa quang.","anchor":"Nắm đấm cao hỏa, hay là như vậy một đoàn, không có lớn lên, thế nhưng hắn rõ ràng nhìn thấy vô số thân ảnh"}]},"capNhatToi":"@c1252","nguon":["@c1252"]},{"id":"hat-giong-tu-than-cua-thach-hao","name":"Hạt giống tự thân của Thạch Hạo","cn":"","category":"khac","categoryLabel":"Đạo chủng","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đã dung hợp với cơ thể Thạch Hạo","blurb":"Hạt giống tự thân của Thạch Hạo là đạo chủng do thanh quang từ các cánh cửa trong cơ thể hắn đan xen, ngưng tụ rồi dung hợp với chính hắn. Nó hội tụ Nội Đạo và tiềm năng của Thạch Hạo, đặt nền tảng cho con đường lấy thân làm chủng.","detail":"Sau khi các cánh cửa trong cơ thể Thạch Hạo khép lại, phần thanh quang còn sót lại đan xen thành một hạt giống rồi dung hợp với hắn @c1252. Hạt giống này không phải đạo chủng do đại Càn Khôn thai nghén mà chính là biểu hiện của bản thân Thạch Hạo, ngưng tụ từ Nội Đạo cùng tiềm năng của hắn và đánh dấu bước khởi đầu của con đường lấy thân làm chủng.","nguonGoc":"Thanh quang từ các cánh cửa trong cơ thể Thạch Hạo đan xen và ngưng tụ.","chuHienThoi":"Thạch Hạo","dacDiem":"Chính là bản thân Thạch Hạo, không phải đạo chủng do đại Càn Khôn thai nghén.","congNang":["Ngưng tụ Nội Đạo và tiềm năng của Thạch Hạo @c1252.","Làm nền tảng cho con đường lấy thân làm chủng @c1252."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1252","denChuong":"","cachCoDuoc":"Tự ngưng tụ từ thanh quang Nội Đạo trong cơ thể","trangThai":"Đã dung hợp"}],"tabs":{"tienTrinh":[{"chuong":"@c1252","loai":"xuất hiện","importance":"major","giaiDoan":"Ngưng tụ và dung hợp","text":"Thanh quang từ các cánh cửa trong cơ thể đan xen thành một hạt giống rồi dung hợp với Thạch Hạo.","anchor":"Cuối cùng, những này thanh quang đan xen vào nhau, tổ hợp thành một viên hạt giống, ngưng ở hắn thể nội","phamCap":"Không rõ"}]},"capNhatToi":"@c1252","nguon":["@c1252"]},{"id":"hat-giong-lay-than-lam-chung","name":"Hạt giống lấy thân làm chủng","cn":"","category":"khac","categoryLabel":"Đạo chủng","phamCap":"Chưa xác định","soHuu":["Thạch Hạo"],"trangThai":"Đã dung hợp với thân thể và tinh thần","blurb":"Đạo chủng do thanh quang từ nhiều cánh cửa trong cơ thể Thạch Hạo hội tụ thành, là thành quả bước đầu của con đường lấy thân làm chủng.","detail":"Hạt giống dung hợp với thân thể và tinh thần của Thạch Hạo, có thể điều động nội đạo và hóa thanh quang thành kiếm. Khi thiên địa tuyệt sát đánh nổ thân thể hắn, nó bao bọc tinh huyết cùng Nguyên Thần để che giấu khỏi thiên uy, tạo điều kiện cho hắn niết bàn tái sinh rồi dung hợp trở lại với thân thể.","nguon":["@c1253"]},{"id":"hong-mong-tu-khi-loai","name":"Hồng Mông tử khí loại","cn":"","aliases":[],"category":"khac","categoryLabel":"Hạt giống hoàn mỹ","phamCap":"Hoàn mỹ hạt giống","soHuu":["Tử Nhật Thiên Quân"],"trangThai":"Đã dung hợp nhưng chưa được khống chế thuần thục","blurb":"Hạt giống hoàn mỹ đã được Tử Nhật Thiên Quân dung hợp để hiển hóa Hồng Mông tử khí. Do mới dung hợp, hắn cần nhiều thời gian ngưng tụ và chưa thể vận dụng tùy tâm.","detail":"Tử Nhật Thiên Quân cố ngưng kết Hồng Mông tử khí trong trận chiến nhưng quá trình diễn ra chậm. Hắn phải dừng việc ngưng tụ để chớp thời cơ tấn công Thạch Hạo.","phanLoaiPhu":"Đạo chủng","uyLuc":"Có thể hiển hóa Hồng Mông tử khí sau khi được ngưng tụ.","dacDiem":"Người mới dung hợp cần thời gian dài để ngưng tụ và chưa thể điều khiển tùy ý.","chuHienThoi":"Tử Nhật Thiên Quân","congNang":["Hiển hóa Hồng Mông tử khí cho người dung hợp."],"chuSoHuu":[{"ten":"Tử Nhật Thiên Quân","tuChuong":"@c1254","denChuong":"","cachCoDuoc":"Đã dung hợp hạt giống","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1254","loai":"dùng","importance":"normal","giaiDoan":"Ngưng tụ chưa hoàn chỉnh","text":"Tử Nhật Thiên Quân chưa thể nhanh chóng ngưng tụ và tùy ý vận dụng Hồng Mông tử khí vì mới dung hợp hạt giống.","anchor":"hoàn mỹ hạt giống lộ ra hóa, cần tiêu hao thời gian rất lâu, dù sao hắn mới dung hợp mà thôi","phamCap":"Hoàn mỹ hạt giống"}]},"capNhatToi":"@c1254","nguon":["@c1254"]},{"id":"hong-mong-tu-khi-chung","name":"Hồng Mông Tử Khí chủng","aliases":["Hồng Mông tử khí loại","Hạt giống màu tím của Tử Nhật Thiên Quân"],"cn":"","category":"khac","categoryLabel":"Vô địch cổ chủng","phanLoaiPhu":"Đại đạo hạt giống","phamCap":"Vô địch chủng","soHuu":["Tử Nhật Thiên Quân"],"trangThai":"Hình thể ngưng tụ bị xuyên thủng","blurb":"Vô địch cổ chủng được Tử Nhật Thiên Quân dung hợp, có khả năng câu thông đại đạo và tiếp nhận quy tắc thiên địa.","detail":"Tử Nhật Thiên Quân mới điều động được một phần sức mạnh của hạt giống nên chưa thể phát huy trạng thái hoàn mỹ. Khi hiện hình, nó khiến hư không tan vỡ và núi thần rạn nứt, nhưng hình thể đang ngưng tụ cuối cùng bị nắm đấm của Thạch Hạo xuyên thủng.","uyLuc":"Uy thế đại đạo làm hư không tan vỡ, núi thần rạn nứt và áp chế những người phản kháng.","dacDiem":"Sức mạnh hiện thời chưa được Tử Nhật Thiên Quân khống chế và phát huy hoàn chỉnh.","chuHienThoi":"Tử Nhật Thiên Quân","congNang":["Câu thông đại đạo và tiếp nhận quy tắc thiên địa từ vực ngoại @c1255","Ngưng tụ Hồng Mông khí thành hình thể vô địch chủng để áp chế đối thủ @c1255"],"chuSoHuu":[{"ten":"Tử Nhật Thiên Quân","tuChuong":"@c1255","denChuong":"","cachCoDuoc":"Đã dung hợp với Hồng Mông Tử Khí chủng","trangThai":"Đang dung hợp nhưng chưa khống chế hoàn chỉnh"}],"capNhatToi":"@c1255","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1255","loai":"dùng","importance":"normal","giaiDoan":"Kích hoạt chưa hoàn chỉnh","phamCap":"Vô địch chủng","text":"Tử Nhật Thiên Quân gọi ra hình thể Hồng Mông Tử Khí chủng và điều động một phần sức mạnh của nó, nhưng hình thể đang ngưng tụ bị nắm đấm Thạch Hạo xuyên thủng.","anchor":"Một cái nắm đấm mang theo hào quang màu vàng kim nhạt, trực tiếp xuyên thấu cái kia viên vô địch chủng"}]},"nguon":["@c1255"]},{"id":"giap-tru-va-binh-khi-hac-am-tien-kim","name":"Giáp trụ và binh khí Hắc Ám Tiên Kim","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Trang bị chiến đấu","phamCap":"Không rõ","soHuu":["Các sinh linh thủ thành mặc giáp đen"],"trangThai":"Nguyên vẹn","blurb":"Giáp trụ, chiến kích và thiên mâu của những sinh linh canh giữ Tiên Thành đều được pha Hắc Ám Tiên Kim.","detail":"Các trang bị vẫn sắc bén sau thời gian dài, mang sát khí hung lệ do từng được dùng chém giết cường địch.","phanLoaiPhu":"Giáp trụ và binh khí","vatLieu":"Pha Hắc Ám Tiên Kim","dacDiem":"Hung lệ, sắc bén và được bảo dưỡng nguyên vẹn.","chuHienThoi":"Các sinh linh thủ thành mặc giáp đen","capNhatToi":"@c1258","congNang":["Được dùng làm trang bị phòng thủ và chiến đấu của lực lượng canh giữ Tiên Thành."],"chuSoHuu":[{"ten":"Các sinh linh thủ thành mặc giáp đen","tuChuong":"@c1258","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1258","loai":"xuất hiện","importance":"normal","giaiDoan":"Trang bị của người thủ thành","text":"Giáp trụ cùng binh khí pha Hắc Ám Tiên Kim xuất hiện trên những sinh linh canh giữ Tiên Thành.","anchor":"Những kia giáp trụ, những binh khí kia, đều lẫn lộn Hắc Ám Tiên Kim"}]},"nguon":["@c1258"]},{"id":"nguyen-mau-dinh","name":"Nguyên Mẫu Đỉnh","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Trọng khí","phamCap":"Đệ nhất trọng khí thời Tiên Cổ","soHuu":["Thiên Giác Nghĩ"],"trangThai":"Được đặt trong động phủ","blurb":"Binh khí của Thiên Giác Nghĩ và là trọng khí đứng đầu thời Tiên Cổ. Nó được dùng làm thử thách lựa chọn người ngoài hai huyết thống Vương giả Tiên Cổ có tư cách tranh truyền thừa.","detail":"Chiếc đỉnh cao khoảng ba thước và cực kỳ nặng. Người bình thường không thể di chuyển nó, thậm chí chạm vào cũng có thể bị đánh bay.","phanLoaiPhu":"Trọng khí","hinhDang":"Đỉnh cao ba thước","nguonGoc":"Binh khí của Thiên Giác Nghĩ thời Tiên Cổ","uyLuc":"Sức nặng đủ khiến người bình thường bị đánh bay khi chạm vào.","dacDiem":"Cực kỳ nặng và gần như không thể lay chuyển.","congNang":["Dùng để thử sức người muốn được công nhận và tranh truyền thừa hạch tâm."],"chuSoHuu":[{"ten":"Thiên Giác Nghĩ","tuChuong":"@c1259","denChuong":"","cachCoDuoc":"Binh khí vốn có thời Tiên Cổ","trangThai":"Chủ nhân nguyên thủy"}],"capNhatToi":"@c1259","tabs":{"tienTrinh":[{"chuong":"@c1259","loai":"dùng","importance":"normal","giaiDoan":"Thử thách tranh truyền thừa","text":"Các lão binh dùng Nguyên Mẫu Đỉnh làm thử thách để công nhận người ngoài hai hậu duệ Vương giả Tiên Cổ.","anchor":"người bình thường đừng nói huy động, chính là liền chuyển đều chuyển không đứng lên","phamCap":"Đệ nhất trọng khí thời Tiên Cổ"}]},"nguon":["@c1259"]},{"id":"luc-cuc-diem-huyet","name":"Lực cực điểm huyết","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Bảo huyết","phamCap":"Bảo huyết Thiên Giác Nghĩ","soHuu":["Kim Triển","Tiểu Thánh","Thích Cố"],"trangThai":"Còn một lượng nhỏ tại Thánh Viện","blurb":"Máu quý của Thiên Giác Nghĩ, có thể hỗ trợ luyện thể giả lột xác và niết bàn. Một lượng nhỏ bảo huyết này tại Thánh Viện đang do Kim Triển, Tiểu Thánh và Thích Cố chiếm giữ.","detail":"Lực cực điểm huyết có thể cải biến thể chất và giúp người sử dụng đạt sức mạnh kinh người. Tài nguyên này rất khan hiếm tại Thánh Viện nên những người khác khó lấy được dù chỉ một giọt.","phanLoaiPhu":"Bảo huyết luyện thể","nguonGoc":"Thiên Giác Nghĩ","uyLuc":"Có thể tạo ra biến hóa lớn về sức mạnh và thể chất.","dacDiem":"Khan hiếm và thích hợp cho luyện thể.","congNang":["Hỗ trợ luyện thể giả lột xác và niết bàn.","Cải biến thể chất và tăng cường sức mạnh."],"chuSoHuu":[{"ten":"Kim Triển","tuChuong":"@c1259","denChuong":"","cachCoDuoc":"Chiếm giữ lượng bảo huyết tại Thánh Viện","trangThai":"Đang có"},{"ten":"Tiểu Thánh","tuChuong":"@c1259","denChuong":"","cachCoDuoc":"Chiếm giữ lượng bảo huyết tại Thánh Viện","trangThai":"Đang có"},{"ten":"Thích Cố","tuChuong":"@c1259","denChuong":"","cachCoDuoc":"Chiếm giữ lượng bảo huyết tại Thánh Viện","trangThai":"Đang có"}],"capNhatToi":"@c1259","tabs":{"tienTrinh":[{"chuong":"@c1259","loai":"xuất hiện","importance":"normal","giaiDoan":"Lộ công dụng luyện thể","text":"Lực cực điểm huyết được tiết lộ có thể giúp người sử dụng cải biến thể chất và đạt sức mạnh kinh người.","anchor":"có thể để người ta sức lực vô cùng, lấy biến hoá kinh người nhất thay đổi thể chất","phamCap":"Bảo huyết Thiên Giác Nghĩ"}]},"nguon":["@c1259"]},{"id":"co-giac-cua-trich-tien","name":"Cổ giác của Trích Tiên","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Không rõ","soHuu":["Trích Tiên"],"trangThai":"Nghi do Trích Tiên nắm giữ","blurb":"Một chiếc cổ giác thần bí có uy lực cực mạnh, được Thạch Hạo liên hệ với truyền thừa Thiên Giác Nghĩ. Trích Tiên bị nghi đang nắm giữ binh khí này.","detail":"Thạch Hạo cho rằng cổ giác từng đủ sức dễ dàng giết mình nếu không có Vạn Linh Đồ bảo vệ. Quan hệ chính xác giữa cổ giác và sào huyệt Thiên Giác Nghĩ chưa được xác nhận.","phanLoaiPhu":"Cổ giác","hinhDang":"Một chiếc giác cổ xưa","uyLuc":"Từng có khả năng dễ dàng giết Thạch Hạo nếu hắn không được Vạn Linh Đồ bảo vệ.","dacDiem":"Thần bí và có thể liên quan tới truyền thừa Thiên Giác Nghĩ.","congNang":["Phát ra sức sát thương đủ đe dọa tính mạng Thạch Hạo."],"chuSoHuu":[{"ten":"Trích Tiên","tuChuong":"@c1259","denChuong":"","cachCoDuoc":"Nghi nhận được từ sào huyệt Thiên Giác Nghĩ","trangThai":"Chưa xác nhận"}],"capNhatToi":"@c1259","tabs":{"tienTrinh":[{"chuong":"@c1259","loai":"nhắc tới","importance":"normal","giaiDoan":"Nghi thuộc về Trích Tiên","text":"Thạch Hạo suy đoán Trích Tiên có thể nắm giữ một chiếc cổ giác thần bí liên quan tới Thiên Giác Nghĩ.","anchor":"mà khả năng có nắm giữ một con cổ giác","phamCap":"Không rõ"}]},"nguon":["@c1259"]},{"id":"lop-lot-xac-dau-lau-cua-thien-giac-nghi","name":"Lớp lột xác đầu lâu của Thiên Giác Nghĩ","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Di vật","phanLoaiPhu":"Xác lột của Thiên Giác Nghĩ","phamCap":"Di vật Tiên đạo","soHuu":["Thiên Giác Nghĩ"],"trangThai":"Đã thức tỉnh dấu vết ý chí","blurb":"Đầu lâu vàng khổng lồ thực chất là lớp xác Thiên Giác Nghĩ từng lột bỏ. Khi được huyết mạch của Tiểu Thiên Giác Nghĩ kích thích, lớp xác thức tỉnh, giải phóng sóng vàng và làm hiện ra dấu vết ý chí của Thiên Giác Nghĩ.","detail":"Lớp lột xác này lưu giữ khí tức cùng dấu vết ý chí của Thiên Giác Nghĩ. Tại @c1263, khí tức huyết mạch từ Tiểu Thiên Giác Nghĩ khiến nó thức tỉnh, phát ra sóng vàng làm các hài cốt, máu và lông của sinh linh Tiên đạo chung quanh nổ vỡ, sau đó hiện lên hình dáng một nam tử trung niên tóc vàng.","hinhDang":"Đầu lâu vàng khổng lồ","nguonGoc":"Lớp xác Thiên Giác Nghĩ từng lột bỏ","uyLuc":"Sóng vàng do lớp lột xác phát ra có thể khiến nhiều di vật Tiên đạo chung quanh, gồm hài cốt, máu và lông, nổ vỡ.","dacDiem":"Là lớp xác đầu lâu màu vàng khổng lồ từng được Thiên Giác Nghĩ lột bỏ, bên trong còn lưu giữ khí tức và dấu vết ý chí có thể hiện thành hình người của Thiên Giác Nghĩ.","chuHienThoi":"Thiên Giác Nghĩ","congNang":["Lưu giữ và làm hiện ra dấu vết ý chí của Thiên Giác Nghĩ dưới hình dáng một nam tử trung niên tóc vàng khi được huyết mạch hậu duệ kích thích. @c1263","Phát ra sóng vàng, phá vỡ các di vật Tiên đạo chung quanh. @c1263"],"chuSoHuu":[{"ten":"Thiên Giác Nghĩ","tuChuong":"@c1263","denChuong":"","cachCoDuoc":"Lớp xác do chính ông lột bỏ","trangThai":"Lưu lại sau khi bản thể qua đời"}],"tabs":{"tienTrinh":[{"chuong":"@c1263","loai":"khai phong","importance":"major","giaiDoan":"Thức tỉnh dấu vết ý chí","text":"Khí tức của Tiểu Thiên Giác Nghĩ khiến lớp lột xác phát ra sóng vàng, phá vỡ các di vật chung quanh và hiện lên hình người của Thiên Giác Nghĩ.","anchor":"Thiên Giác Nghĩ lột xác phát sinh màu vàng sóng gợn các loại","phamCap":"Di vật Tiên đạo"}]},"capNhatToi":"@c1263","nguon":["@c1263"]},{"id":"long-chim-mau-xam","name":"Lông chim màu xám","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Di vật luyện khí","phanLoaiPhu":"Lông chim của sinh linh Tiên đạo","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang được Thạch Hạo giữ","blurb":"Lông chim màu xám là di vật duy nhất trên chiến trường không còn sát khí và có thể chạm vào. Thạch Hạo thu lấy, dự định dùng nó làm nguyên liệu thử luyện Ngũ Cầm Phiến.","detail":"Chiếc lông chim màu xám được Thạch Hạo phát hiện trên chiến trường và thu giữ tại @c1263. Nó nhẹ như không có trọng lượng, không hiện phù văn khi được truyền thần lực, đồng thời đã mất hết sát khí; Thạch Hạo giữ nó để phục vụ kế hoạch thử luyện Ngũ Cầm Phiến.","hinhDang":"Một chiếc lông chim màu xám","dacDiem":"Nhẹ như không có trọng lượng, không hiện phù văn khi truyền thần lực và không còn sát khí.","chuHienThoi":"Thạch Hạo","congNang":["Có thể được dùng làm nguyên liệu thử luyện Ngũ Cầm Phiến @c1263."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1263","denChuong":"","cachCoDuoc":"Thu lấy trên chiến trường Thiên Giác Nghĩ","trangThai":"Đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c1263","loai":"đổi chủ","importance":"major","giaiDoan":"Được Thạch Hạo thu lấy","text":"Thạch Hạo phát hiện chiếc lông chim không còn sát khí, thu lấy và dự định dùng nó để thử luyện Ngũ Cầm Phiến.","anchor":"phát hiện nó là duy nhất không có sát khí, có thể đụng vào đồ vật","phamCap":"Không rõ"}]},"capNhatToi":"@c1263","nguon":["@c1263"]},{"id":"thanh-truong-kiem-cua-tuyet-the-cao-thu-di-vuc","name":"Thanh trường kiếm của tuyệt thế cao thủ dị vực","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Không rõ","soHuu":["Cường giả cầm thanh kiếm xanh"],"chuSoHuu":[{"ten":"Cường giả cầm thanh kiếm xanh","tuChuong":"@c1264","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"trangThai":"Còn tồn tại","hinhDang":"Trường kiếm màu xanh không có ánh sáng bóng.","uyLuc":"Có thể xuyên thủng vũ trụ và mi tâm của Thiên Giác Nghĩ.","congNang":["Xuyên thủng vũ trụ và gây thương tổn cho thân thể Thiên Giác Nghĩ."],"blurb":"Thanh kiếm màu xanh thuộc về một tuyệt thế cao thủ dị vực. Trong ký ức trận chiến cuối Tiên Cổ, nó xuyên thủng vũ trụ rồi đâm qua mi tâm Thiên Giác Nghĩ.","detail":"Binh khí xuất hiện trong ký ức chiến đấu do Thiên Giác Nghĩ truyền cho Thạch Hạo. Thanh kiếm không có ánh sáng bóng nhưng sở hữu uy lực đủ xuyên thủng vũ trụ và làm bị thương thân thể được xưng đứng đầu vũ nội.","capNhatToi":"@c1264","tabs":{"tienTrinh":[{"chuong":"@c1264","loai":"dùng","importance":"normal","giaiDoan":"Trận chiến cuối Tiên Cổ","text":"Thanh trường kiếm màu xanh được dùng để xuyên thủng vũ trụ và mi tâm Thiên Giác Nghĩ.","anchor":"màu xanh, không có sáng bóng, nhưng là lại lập tức xuyên thủng vũ trụ"}]},"nguon":["@c1264"]},{"id":"kim-sac-truong-thuong-cua-tuyet-the-cao-thu-di-vuc","name":"Kim sắc trường thương của tuyệt thế cao thủ dị vực","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Không rõ","soHuu":["Cường giả cầm trường thương vàng"],"chuSoHuu":[{"ten":"Cường giả cầm trường thương vàng","tuChuong":"@c1264","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"trangThai":"Còn tồn tại","hinhDang":"Trường thương màu vàng.","uyLuc":"Mang sức hủy diệt đại thế giới, có thể phá nát xương cốt, kinh mạch và uy hiếp linh hồn Thiên Giác Nghĩ.","congNang":["Phá hủy thân thể và kinh mạch của mục tiêu.","Mang sát khí xâm nhập tới linh hồn mục tiêu."],"blurb":"Trường thương vàng của một tuyệt thế cao thủ dị vực, mang tốc độ và sức hủy diệt cực lớn. Binh khí này từng trọng thương toàn diện thân thể Thiên Giác Nghĩ.","detail":"Trong ký ức trận chiến cuối Tiên Cổ, mũi thương vàng phá nát xương cốt và kinh mạch của Thiên Giác Nghĩ, đồng thời cuốn sát khí tới linh hồn ông. Đòn đánh được mô tả là một thương có thể làm tan biến đại thế giới.","capNhatToi":"@c1264","tabs":{"tienTrinh":[{"chuong":"@c1264","loai":"dùng","importance":"normal","giaiDoan":"Trận chiến cuối Tiên Cổ","text":"Trường thương vàng được dùng trong một đòn có sức tan biến đại thế giới và trọng thương Thiên Giác Nghĩ.","anchor":"Đây là tan biến đại thế giới nhất thương"}]},"nguon":["@c1264"]},{"id":"khac-dau-chi-duong-toi-bat-diet-kinh","name":"Khắc dấu chỉ đường tới Bất Diệt kinh","cn":"","aliases":[],"category":"khac","categoryLabel":"Truyền thừa chỉ dẫn","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1264","denChuong":"","cachCoDuoc":"Được Thiên Giác Nghĩ truyền thẳng vào mi tâm.","trangThai":"đang sở hữu"}],"trangThai":"Đã truyền vào mi tâm Thạch Hạo","nguonGoc":"Do tàn hồn Thiên Giác Nghĩ truyền lại.","congNang":["Chỉ dẫn đường tới nơi lưu giữ toàn bộ Bất Diệt kinh. @c1264"],"blurb":"Khắc dấu chỉ đường tới Bất Diệt kinh là dấu ấn do tàn hồn Thiên Giác Nghĩ truyền vào mi tâm Thạch Hạo. Nó chỉ dẫn đường tới nơi lưu giữ toàn bộ Bất Diệt kinh.","detail":"Tàn hồn Thiên Giác Nghĩ tạo ra khắc dấu bằng một ngón tay rồi trực tiếp truyền vào mi tâm Thạch Hạo. Dấu ấn này trở thành chỉ dẫn giúp Thạch Hạo tìm đến nơi lưu giữ cổ kinh, nhằm mang toàn bộ Bất Diệt kinh ra ngoài. @c1264","capNhatToi":"@c1264","tabs":{"tienTrinh":[{"chuong":"@c1264","loai":"đổi chủ","importance":"major","giaiDoan":"Trao chỉ dẫn truyền thừa","text":"Thiên Giác Nghĩ truyền khắc dấu vào mi tâm Thạch Hạo để chỉ đường tới nơi lưu giữ toàn bộ Bất Diệt kinh.","anchor":"một mảnh khắc dấu, theo tinh thần ngã xuống cảnh tượng, trực tiếp vọt vào Thạch Hạo mi tâm bên trong"}]},"nguon":["@c1264"],"dacDiem":"Được truyền trực tiếp vào mi tâm Thạch Hạo dưới dạng khắc dấu."},{"id":"vung-bun-than-duoc","name":"Vũng bùn thần dược","cn":"","aliases":[],"category":"khac","categoryLabel":"Linh vật đặc thù","phamCap":"Hình thành từ vườn Trường Sinh dược và thần dược","soHuu":[],"trangThai":"Còn tồn tại gần thần hồ","blurb":"Vũng bùn hình thành khi vườn thuốc cổ mục nát và dược tính thấm vào thổ nhưỡng. Nó có thể giúp sinh linh thoát thai hoán cốt, lột da cũ và tái sinh huyết nhục.","detail":"Nơi này từng trồng Trường Sinh dược cùng nhiều loại thần dược. Sau khi dược thảo mục nát, đất bùn tích tụ dược tính mạnh đến mức nhiều người tại chỗ lột da cũ và sinh ra huyết nhục mới; hiệu quả đối với Thạch Hạo không lớn vì thân thể hắn đã trải qua ba năm lột xác.","phanLoaiPhu":"Dược thổ","nguonGoc":"Vườn thuốc cổ từng trồng Trường Sinh dược và nhiều thần dược.","congNang":["Giúp sinh linh thoát thai hoán cốt, lột da cũ và tái sinh huyết nhục."],"dacDiem":"Dược tính đã hòa vào bùn đất sau khi vườn thuốc mục nát.","capNhatToi":"@c1265","tabs":{"tienTrinh":[{"chuong":"@c1265","loai":"xuất hiện","importance":"normal","giaiDoan":"Được phát hiện gần thần hồ","text":"Nhiều chí tôn trẻ tuổi tiến vào vũng bùn để hấp thu dược tính và lột xác thân thể.","anchor":"nơi này có kinh người thần hiệu, rất nhiều người tại chỗ lão bì bóc ra"}]},"nguon":["@c1265"]},{"id":"than-cong-bao-dien-cua-truong-sinh-hoang-trieu","name":"Thần công bảo điển của Trường Sinh Hoàng Triều","cn":"","aliases":[],"category":"khac","categoryLabel":"Điển tịch truyền thừa","phamCap":"Không rõ","soHuu":["Trường Sinh Hoàng Triều của Từ gia"],"trangThai":"khong-ro","blurb":"Các thần công bảo điển thuộc nội tình truyền thừa của Trường Sinh Hoàng Triều. Đám đông cho rằng người trở thành phò mã có thể được tiếp cận kho tàng này.","detail":"Điển tịch được nhắc tới khi mọi người bàn luận lợi ích dành cho đạo lữ tương lai của Yêu Nguyệt.","nguon":["@c1267"]},{"id":"chiec-nhanh-xanh-den-cua-dai-truong-lao","name":"Chiếc nhẫn xanh đen của Đại trưởng lão","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm bí ẩn","phanLoaiPhu":"Nhẫn","phamCap":"Chưa rõ","soHuu":["Thạch Hạo"],"chuHienThoi":"Thạch Hạo","trangThai":"Nguyên vẹn","hinhDang":"Chiếc nhẫn xanh đen, cổ điển và thô ráp.","vatLieu":"Chưa rõ","blurb":"Chiếc nhẫn xanh đen được Đại trưởng lão trao cho Thạch Hạo và dặn phải đeo trên tay vì có thể sẽ cần dùng đến trong tương lai. Công dụng cụ thể của chiếc nhẫn vẫn chưa lộ rõ.","detail":"Tại mốc @c1268, Đại trưởng lão giao chiếc nhẫn xanh đen cho Thạch Hạo, khiến pháp bảo này đổi chủ. Ông căn dặn Thạch Hạo đeo nó trên tay vì một ngày nào đó có thể cần dùng tới; ngoài lời dặn ấy, nguồn gốc, chất liệu và năng lực thực tế của chiếc nhẫn chưa được làm rõ.","dacDiem":"Không phát sáng, có màu xanh đen và bề mặt thô ráp.","congNang":["Công dụng chưa lộ rõ; Đại trưởng lão cho biết Thạch Hạo có thể cần dùng tới nó trong tương lai."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1268","denChuong":"","cachCoDuoc":"Được Đại trưởng lão bí mật giao","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1268","loai":"đổi chủ","importance":"major","giaiDoan":"Được giao cho Thạch Hạo","phamCap":"Chưa rõ","text":"Đại trưởng lão trao chiếc nhẫn xanh đen cho Thạch Hạo và dặn hắn đeo trên tay vì có thể cần dùng vào một ngày nào đó.","anchor":"Mang ở trên tay, có thể sẽ có một ngày sẽ dùng đến"}]},"capNhatToi":"@c1268","nguon":["@c1268"]},{"id":"minh-thuyen-bang-xuong","name":"Minh thuyền bằng xương","cn":"","aliases":["Minh Thuyền"],"category":"phap-bao","categoryLabel":"Cổ thuyền Tiên cổ","phanLoaiPhu":"Minh thuyền","phamCap":"Chưa rõ","soHuu":[],"trangThai":"đang hoạt động","hinhDang":"Một cổ thuyền có hình dáng giống hệt thuyền giấy.","vatLieu":"Xương chưa rõ nguồn gốc","nguonGoc":"Cổ thuyền còn sót lại từ Tiên cổ.","blurb":"Minh thuyền bằng xương tự chở người đi sâu vào Bắc Hải. Khi chở Thạch Hạo, vách thuyền bất ngờ rỉ ra máu đen đỏ và bộc lộ liên hệ kỳ lạ với những thuyền giấy gần Côn Bằng sào.","detail":"Thân thuyền được mài từ xương, kiên cố và không chìm giữa Bắc Hải phủ sương đen. Nó có thể tự định hướng trên biển; trong chuyến đi của Thạch Hạo, vách thuyền đột nhiên chảy chất lỏng đen đỏ, một hiện tượng những người đi trước chưa từng gặp.","uyLuc":"Có thể tự vượt qua vùng biển Bắc Hải nguy hiểm mà không cần người điều khiển.","dacDiem":"Làm từ xương, không chìm, có hình dáng giống thuyền giấy và từng chảy máu đen đỏ.","congNang":["Tự định hướng và chở người tiến vào vùng sâu của Bắc Hải.","Tự động vượt qua các hải vực tại @c1269."],"tabs":{"tienTrinh":[{"chuong":"@c1268","loai":"xuất hiện","importance":"normal","giaiDoan":"Dị biến chảy máu","phamCap":"Chưa rõ","text":"Minh thuyền bằng xương tự chở Thạch Hạo vào Bắc Hải, sau đó vách thuyền bất ngờ rỉ ra máu đen đỏ.","anchor":"Thuyền trên vách, có một ít vết máu, đột ngột chảy ra"},{"chuong":"@c1269","loai":"dùng","importance":"normal","giaiDoan":"Vượt biển và chảy máu","text":"Minh Thuyền tự đưa Thạch Hạo và Thiên Giác Nghĩ nhỏ qua nhiều địa vực dị thường, đồng thời xuất hiện máu rỉ ra từ vách thuyền.","anchor":"Minh Thuyền tràn huyết, quả nhiên có cổ quái","phamCap":"Không rõ"}]},"capNhatToi":"@c1268","nguon":["@c1268","@c1269"]},{"id":"dong-dinh-cua-kim-sac-con-kien-nho","name":"Đồng đỉnh của Kim sắc con kiến nhỏ","cn":"","category":"phap-bao","categoryLabel":"Đỉnh luyện hóa","phamCap":"Không rõ","soHuu":["Thiên Giác Nghĩ nhỏ"],"trangThai":"đang được sử dụng","blurb":"Một chiếc đồng đỉnh được Thiên Giác Nghĩ nhỏ lấy ra để luyện hóa máu cổ trên Minh Thuyền.","detail":"Khi được Đại Lực Tiên Diễm nung nóng, đồng đỉnh chuyển từ màu xanh đồng sang đỏ rực rồi trong suốt như lưu ly, để lộ kết cấu bên trong do phù văn đại đạo Tiên Cổ tạo thành.","phanLoaiPhu":"Đỉnh luyện hóa","hinhDang":"Đồng đỉnh màu xanh đồng, có thể trở nên trong suốt khi nung nóng.","vatLieu":"Đồng","dacDiem":"Kết cấu bên trong được xây dựng bằng phù văn đại đạo Tiên Cổ.","chuHienThoi":"Thiên Giác Nghĩ nhỏ","congNang":["Chứa và luyện hóa máu cổ tại @c1269."],"chuSoHuu":[{"ten":"Thiên Giác Nghĩ nhỏ","tuChuong":"@c1269","denChuong":"","cachCoDuoc":"Đã mang trong cơ thể khi xuất hiện","trangThai":"đang sở hữu"}],"capNhatToi":"@c1269","tabs":{"tienTrinh":[{"chuong":"@c1269","loai":"dùng","importance":"normal","giaiDoan":"Luyện hóa bảo huyết","text":"Thiên Giác Nghĩ nhỏ dùng đồng đỉnh phối hợp với Đại Lực Tiên Diễm để luyện hóa các giọt máu lấy từ Minh Thuyền.","anchor":"Đó là Tiên Cổ Đại Đạo phù văn, xây dựng thành này đỉnh bên trong kết cấu","phamCap":"Không rõ"}]},"nguon":["@c1269"]},{"id":"bao-huyet-tren-minh-thuyen","name":"Bảo huyết trên Minh Thuyền","cn":"","category":"nguyen-lieu","categoryLabel":"Máu cổ","phamCap":"Không rõ","soHuu":[],"trangThai":"đã được luyện hóa một phần","blurb":"Máu cổ rỉ ra từ vách Minh Thuyền, bên trong còn lưu dấu ấn của một trận chiến có sức hủy diệt tinh không.","detail":"Khi được luyện hóa, các giọt máu thải ra khói đen tanh hôi có sức ăn mòn và năng lượng làm nứt hư không. Giọt bảo huyết còn lại đã mất gần hết tinh hoa nhưng vẫn tái hiện cảnh chủ nhân bị trường thương vàng đâm xuyên, máu bắn ra phá hủy nhiều ngôi sao.","phanLoaiPhu":"Bảo huyết cổ","nguonGoc":"Rỉ ra từ vách Minh Thuyền.","uyLuc":"Tàn lực trong máu có thể làm nứt hư không, còn dấu ấn chiến tranh cho thấy máu của chủ nhân từng xuyên phá nhiều ngôi sao.","dacDiem":"Tinh hoa gần cạn sau thời gian cực dài nhưng vẫn còn linh tính và dấu ấn chiến tranh.","congNang":["Lưu giữ dấu ấn chiến tranh của chủ nhân giọt máu tại @c1269."],"capNhatToi":"@c1269","tabs":{"tienTrinh":[{"chuong":"@c1269","loai":"khai phong","importance":"normal","giaiDoan":"Hiện dấu ấn chiến tranh","text":"Sau khi được luyện hóa, bảo huyết hiện ra dấu ấn về một sinh linh bị trường thương vàng đâm xuyên và những giọt máu phá hủy hàng loạt tinh cầu.","anchor":"Một giọt huyết có thể hủy hoại Tinh Không, chém rụng hạ hơn mấy trăm ngàn khỏa","phamCap":"Không rõ"}]},"nguon":["@c1269"]},{"id":"mat-troi-kim-o-co","name":"Mặt trời Kim Ô cổ","cn":"","category":"khac","categoryLabel":"Thiên thể luyện chế","phamCap":"Không rõ","soHuu":[],"trangThai":"đang tồn tại","blurb":"Một vầng mặt trời cổ nằm sát mặt biển trong thế giới đảo ngược, được luyện chế từ thi thể của một cổ Kim Ô.","detail":"Thiên thể này không tỏa tử khí mà phát ra ánh sáng nóng bỏng cùng khí tức tường hòa. Nó từng là thi thể của một con Kim Ô tung hoành thiên địa trước khi được luyện thành mặt trời.","phanLoaiPhu":"Mặt trời luyện chế","hinhDang":"Vầng kim nhật nằm sát mặt biển.","vatLieu":"Thi thể cổ Kim Ô","nguonGoc":"Được luyện chế từ thi thể của một cổ Kim Ô.","dacDiem":"Không có tử khí, chỉ tỏa sức nóng và khí tức tường hòa.","congNang":["Phát ra ánh sáng nóng bỏng và khí tức tường hòa tại @c1269."],"capNhatToi":"@c1269","tabs":{"tienTrinh":[{"chuong":"@c1269","loai":"xuất hiện","importance":"normal","giaiDoan":"Hiện diện trong thế giới đảo ngược","text":"Mặt trời Kim Ô cổ xuất hiện sát mặt biển khi Minh Thuyền tiến vào thế giới đảo ngược.","anchor":"Đây là một khỏa cổ xưa mặt trời, dùng một chỉ đã từng tung hoành trong trời đất cổ Kim Ô thi thể luyện chế thành","phamCap":"Không rõ"}]},"nguon":["@c1269"]},{"id":"loi-de-giap-tru","name":"Lôi Đế giáp trụ","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Giáp trụ","phanLoaiPhu":"Giáp trụ truyền thừa","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Rách nát, thủng lỗ và rỉ sét","blurb":"Bộ giáp trụ rách nát mang danh Lôi Đế, có thể thức tỉnh dưới ánh lôi đình và phóng thích Bất Hủ tiên quang.","detail":"Thạch Hạo lấy giáp trụ ra để kiểm tra phản ứng với lôi đình và đường nối thời gian. Nó bừng tỉnh dữ dội như một vị cổ Tiên sống lại nhưng nhanh chóng yên tĩnh, không cho thấy sự cộng hưởng với đường nối.","hinhDang":"Bộ áo giáp rách nát, thủng lỗ và phủ rỉ sét.","uyLuc":"Khi được lôi đình kích thích, giáp trụ phóng thích Bất Hủ tiên quang cuồng bạo.","dacDiem":"Có phản ứng rõ rệt với ánh lôi đình nhưng không cộng hưởng với đường nối thời gian.","chuHienThoi":"Thạch Hạo","congNang":["Thức tỉnh và phóng thích Bất Hủ tiên quang dưới sự kích thích của lôi đình."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1270","denChuong":"","cachCoDuoc":"Không nêu trong chương","trangThai":"Đang giữ"}],"capNhatToi":"@c1270","tabs":{"tienTrinh":[{"chuong":"@c1270","loai":"dùng","importance":"normal","giaiDoan":"Dò xét đường nối thời gian","text":"Thạch Hạo lấy Lôi Đế giáp trụ ra thử phản ứng với lôi đình; bộ giáp phóng thích Bất Hủ tiên quang rồi yên tĩnh trở lại.","anchor":"phảng phất một vị cổ Tiên thức tỉnh, cuồng bạo vô cùng, phóng thích Bất Hủ tiên quang","phamCap":"Không rõ"}]},"nguon":["@c1270"]},{"id":"vay-mang-long-uy-tu-co-thuyen-den","name":"Vảy mang long uy từ cổ thuyền đen","cn":"","aliases":[],"category":"khac","categoryLabel":"Vảy bí ẩn","phanLoaiPhu":"Vảy mang long uy","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Nguyên vẹn","blurb":"Tấm vảy dài hơn một thước mang theo long uy, được Thạch Hạo lấy từ một cổ thuyền đen nhuốm máu trong hư không.","detail":"Thạch Hạo lấy tấm vảy ra khi tìm kiếm vật phẩm có thể đã kích hoạt đường nối thời gian. Vảy tỏa long khí nhưng không thể dẹp sức mạnh năm tháng và không được xác nhận là nguồn gây dị biến.","hinhDang":"Tấm vảy dài hơn một thước.","nguonGoc":"Cổ thuyền đen nhuốm máu trong hư không.","dacDiem":"Mang theo long uy nhưng không cộng hưởng với đường nối thời gian.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1270","denChuong":"","cachCoDuoc":"Lấy từ cổ thuyền đen nhuốm máu trong hư không","trangThai":"Đang giữ"}],"capNhatToi":"@c1270","tabs":{"tienTrinh":[{"chuong":"@c1270","loai":"dùng","importance":"normal","giaiDoan":"Dò xét nguồn dị biến","text":"Thạch Hạo lấy tấm vảy mang long uy ra thử đối kháng sức mạnh thời gian nhưng không thu được phản ứng hữu hiệu.","anchor":"hắn lại lấy ra một tấm vảy, dài hơn một thước, mang theo long uy","phamCap":"Không rõ"}]},"nguon":["@c1270"]},{"id":"thuyen-giay-nhuom-mau","name":"Thuyền giấy nhuốm máu","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm bí ẩn","phanLoaiPhu":"Thuyền giấy","phamCap":"Không rõ","soHuu":[],"trangThai":"Trôi trong đường nối thời gian","blurb":"Những chiếc thuyền giấy dính máu và mang hàng chữ quen thuộc, lần lượt trôi qua quang đạo trước mắt Thạch Hạo.","detail":"Nhiều thuyền giấy nhuốm máu xuất hiện từ xa rồi trôi lại gần trong đường nối thời gian. Hàng chữ trên thuyền giống dấu tích Thạch Hạo từng thấy năm xưa, nhưng nguồn gốc và người tạo ra chúng chưa được xác nhận.","hinhDang":"Những chiếc thuyền giấy nhỏ dính máu và có viết chữ.","dacDiem":"Xuất hiện thành nhiều chiếc trong quang đạo và mang hàng chữ quen thuộc với Thạch Hạo.","congNang":["Trôi xuyên qua quang đạo trong đường nối thời gian."],"capNhatToi":"@c1270","tabs":{"tienTrinh":[{"chuong":"@c1270","loai":"xuất hiện","importance":"normal","giaiDoan":"Tái hiện trong quang đạo","text":"Nhiều thuyền giấy nhuốm máu mang chữ viết lần lượt trôi từ xa đến gần trước mắt Thạch Hạo.","anchor":"hắn nhìn thấy mấy cái tiểu thuyền giấy, trước sau từ xa đến gần, đều nhuộm huyết, viết tự","phamCap":"Không rõ"}]},"nguon":["@c1270"]},{"id":"thuyen-giay-den-nhuom-mau","name":"Thuyền giấy đen nhuốm máu","cn":"","category":"khac","categoryLabel":"Vật phẩm","phamCap":"Không rõ","soHuu":["Bạch y nữ Đế"],"trangThai":"Nguyên vẹn","blurb":"Những chiếc thuyền giấy đen nhuốm máu có khả năng trấn áp thời gian và hư không.","detail":"Vài chiếc thuyền giấy đi qua loạn lưu, khiến thời gian ngưng đọng và hư không ổn định, qua đó cứu Thạch Hạo cùng Thiên Giác Nghĩ nhỏ và bảo vệ đường nối.","phanLoaiPhu":"Thuyền giấy","hinhDang":"Những chiếc thuyền giấy nhỏ màu đen nhuốm máu.","uyLuc":"Có thể hóa giải nguy cơ sụp đổ của đường nối thời gian.","dacDiem":"Có thể tiến qua loạn lưu và đồng thời ổn định thời gian lẫn hư không.","chuHienThoi":"Bạch y nữ Đế","congNang":["Trấn áp thời gian và hư không.","Bảo vệ đường nối thời gian khỏi sụp đổ."],"chuSoHuu":[{"ten":"Bạch y nữ Đế","tuChuong":"@c1271","denChuong":"","cachCoDuoc":"Xuất hiện theo Bạch y nữ Đế trong đường nối thời gian.","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1271","tabs":{"tienTrinh":[{"chuong":"@c1271","loai":"dùng","importance":"normal","giaiDoan":"Trấn áp đường nối","text":"Vài chiếc thuyền giấy trấn áp thời gian và hư không, cứu Thạch Hạo cùng Thiên Giác Nghĩ nhỏ khỏi đường nối đang tan vỡ.","anchor":"Vài con tiểu thuyền giấy mà thôi, hóa giải tình thế nguy cấp, cứu Thạch Hạo còn có màu vàng con kiến nhỏ, trấn áp Càn Khôn, bảo vệ đường nối."}]},"nguon":["@c1271"]},{"id":"phap-khi-bien-hoa-cua-bach-y-nu-de","name":"Pháp khí biến hóa của Bạch y nữ Đế","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Không rõ","soHuu":["Bạch y nữ Đế"],"trangThai":"Nguyên vẹn","blurb":"Pháp khí có thể liên tục biến đổi giữa nhiều hình thái khác nhau.","detail":"Pháp khí lần lượt hóa thành tiên kiếm, mặt nạ, nhẫn và ma bình trước khi dừng ở hình thái mặt nạ đồng xanh che khuất dung mạo Bạch y nữ Đế.","phanLoaiPhu":"Pháp khí biến hóa","hinhDang":"Có thể hóa thành tiên kiếm, mặt nạ, nhẫn hoặc ma bình.","uyLuc":"Chưa thể hiện đầy đủ uy lực trong lần xuất hiện này.","dacDiem":"Hình thái mặt nạ đồng xanh mang nét khóc và cười đan xen.","chuHienThoi":"Bạch y nữ Đế","congNang":["Biến đổi giữa nhiều hình thái pháp khí.","Che khuất dung mạo Bạch y nữ Đế dưới hình thái mặt nạ đồng xanh."],"chuSoHuu":[{"ten":"Bạch y nữ Đế","tuChuong":"@c1271","denChuong":"","cachCoDuoc":"Mang theo khi xuất hiện trong đường nối thời gian.","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1271","tabs":{"tienTrinh":[{"chuong":"@c1271","loai":"dùng","importance":"normal","giaiDoan":"Biến thành mặt nạ","text":"Pháp khí liên tục thay đổi hình thái rồi hóa thành mặt nạ đồng xanh che trước mặt Bạch y nữ Đế.","anchor":"một cái pháp khí hóa thành tiên kiếm, hóa thành mặt nạ, hóa thành chiếc nhẫn, đổi thành ma bình, không ngừng chuyển biến, chặn ở trước người."}]},"nguon":["@c1271"]},{"id":"giot-mau-trong-nguoi-thach-hao","name":"Giọt máu trong người Thạch Hạo","cn":"","category":"khac","categoryLabel":"Dị vật","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Nằm trong cơ thể Thạch Hạo","blurb":"Giọt máu bí ẩn là vật dẫn đưa Thạch Hạo vào đường nối thời gian.","detail":"Giọt máu do một chiếc đỉnh bí ẩn lưu lại trong cơ thể Thạch Hạo hiện ra giữa tiếng sấm và sát khí, khiến Thiên Giác Nghĩ nhỏ nhận ra nguyên nhân cả hai bị cuốn vào đường nối thời gian.","phanLoaiPhu":"Dị vật huyết dịch","nguonGoc":"Được một chiếc đỉnh bí ẩn lưu lại trong cơ thể Thạch Hạo.","uyLuc":"Khi hiện ra mang theo tiếng sấm và sát phạt kinh động Cửu Thiên.","dacDiem":"Ẩn trong cơ thể Thạch Hạo và có liên hệ với đường nối thời gian.","chuHienThoi":"Thạch Hạo","congNang":["Dẫn Thạch Hạo cùng Thiên Giác Nghĩ nhỏ vào đường nối thời gian."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1271","denChuong":"","cachCoDuoc":"Được chiếc đỉnh bí ẩn lưu lại trong cơ thể.","trangThai":"Đang mang theo"}],"capNhatToi":"@c1271","tabs":{"tienTrinh":[{"chuong":"@c1271","loai":"xuất hiện","importance":"normal","giaiDoan":"Hiện ra làm vật dẫn","text":"Giọt máu hiện ra trong cơ thể Thạch Hạo và được nhận định là nguyên nhân kéo hắn cùng Thiên Giác Nghĩ nhỏ vào đường nối thời gian.","anchor":"cuối cùng trong thân thể của hắn hiện lên một giọt máu, ở bên trong tiếng sấm ầm ầm, sát phạt kinh Cửu Thiên!"}]},"nguon":["@c1271"]},{"id":"thuyen-giay","name":"Thuyền giấy","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm","phamCap":"Không rõ","soHuu":[],"trangThai":"không rõ","blurb":"Một con thuyền giấy xuất hiện bên cạnh Thạch Hạo trên đường nối thời gian và tỏa ánh sáng bảo vệ hắn.","detail":"Khi Thạch Hạo thử tiến về phía Bạch y nữ Đế và bị sức mạnh thời gian bào mòn, thuyền giấy xuất hiện bên người, tỏa ra những điểm sáng lộng lẫy giúp hắn tránh khỏi kết cục thân thể nứt vỡ.","phanLoaiPhu":"Vật phẩm bảo hộ","congNang":["Tỏa ánh sáng bảo vệ Thạch Hạo khỏi sức mạnh thời gian trên đường nối thời gian."],"uyLuc":"Có thể che chở Thạch Hạo trước sự bào mòn mãnh liệt của thời gian.","capNhatToi":"@c1272","tabs":{"tienTrinh":[{"chuong":"@c1272","loai":"dùng","importance":"normal","giaiDoan":"Bảo vệ trên đường nối thời gian","text":"Thuyền giấy xuất hiện bên cạnh Thạch Hạo và tỏa ánh sáng giúp hắn không bị sức mạnh thời gian làm nứt vỡ.","anchor":"nếu không có một con thuyền giấy xuất hiện ở bên người, điểm điểm ánh sáng lộng lẫy tràn ra, hắn tuyệt đối nứt ra rồi"}]},"nguon":["@c1272"]},{"id":"mat-na-bang-dong-xanh-cua-nu-de","name":"Mặt nạ bằng đồng xanh của nữ Đế","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm","phamCap":"Không rõ","soHuu":["Bạch y nữ Đế"],"trangThai":"vỡ đôi","blurb":"Mặt nạ bằng đồng xanh của nữ Đế đã nứt thành hai mảnh khi đường nối thời gian tan vỡ. Từ chỗ nứt, một đạo tiên quang bay tới và chạm vào Thạch Hạo.","detail":"Trong khoảnh khắc cuối của cuộc gặp vượt kỷ nguyên, mặt nạ bằng đồng xanh của nữ Đế nứt đôi giữa tinh không. Từ khe nứt, một đạo tiên quang bay tới, chạm vào Thạch Hạo; sau khi tỉnh lại, hắn không tìm thấy dấu vết của đạo tiên quang ấy. @c1272","hinhDang":"Mặt nạ bằng đồng xanh","chuHienThoi":"Bạch y nữ Đế","congNang":["Phát ra một đạo tiên quang từ khe nứt, bay tới và chạm vào Thạch Hạo. @c1272"],"dacDiem":"Nứt thành hai mảnh và rơi xuống tinh không trong lúc đường nối thời gian tan vỡ. @c1272","chuSoHuu":[{"ten":"Bạch y nữ Đế","tuChuong":"@c1272","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu khi xuất hiện"}],"capNhatToi":"@c1272","tabs":{"tienTrinh":[{"chuong":"@c1272","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Nứt vỡ giữa tinh không","text":"Mặt nạ đồng xanh nứt thành hai mảnh và phát ra một đạo tiên quang bay tới Thạch Hạo.","anchor":"cái kia mặt nạ bằng đồng xanh khách một tiếng nứt thành hai nửa, sau đó rơi xuống ở trong tinh không"}]},"nguon":["@c1272"]},{"id":"thi-the-co-kim-o","name":"Thi thể cổ Kim ô","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Di hài","phamCap":"Không rõ","soHuu":[],"trangThai":"nằm trên siêu tuyệt phong","blurb":"Di hài của một con Kim ô cổ nằm ngang trên siêu tuyệt phong tại Bắc Hải bãi đá.","detail":"Thi thể cổ Kim ô có thể hóa thành Thái Dương, tỏa ra hỏa tinh và khiến khu vực quanh ngọn núi trở thành một tiểu cấm địa mà người bình thường khó tới gần.","phanLoaiPhu":"Di hài cổ sinh linh","congNang":["Có thể hóa thành Thái Dương và tỏa hỏa tinh quanh siêu tuyệt phong."],"uyLuc":"Biến khu vực phụ cận thành tiểu cấm địa mà người bình thường không thể tới gần.","dacDiem":"Nằm ngang trên một siêu tuyệt phong cao xuyên mây tại Bắc Hải bãi đá.","capNhatToi":"@c1272","tabs":{"tienTrinh":[{"chuong":"@c1272","loai":"xuất hiện","importance":"normal","giaiDoan":"Hiện diện trên siêu tuyệt phong","text":"Thi thể cổ Kim ô được phát hiện nằm trên một siêu tuyệt phong và có thể hóa thành Thái Dương.","anchor":"Đó là một con cổ Kim ô thi thể, có thể hóa thành Thái Dương, nhưng cũng nằm ngang ở một toà siêu tuyệt phong trên"}]},"nguon":["@c1272"]},{"id":"quan-tai-co-tren-doan-nhai","name":"Quan tài cổ trên đoạn nhai","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm cổ","phamCap":"Không rõ","soHuu":[],"trangThai":"Nắp quan tài đã mở","blurb":"Quan tài cổ nằm ngang trên đoạn nhai của một cổ sơn. Khi các ngọn núi rung chuyển, nắp quan tài mở ra và một tấm da người rơi xuống.","detail":"Quan tài nằm trên vách núi sâu trong vùng cấm, giữa khu vực có những cổ sơn hơn triệu năm không người đăng lâm. Dị biến xảy ra khi Thạch Hạo bước vào đường mòn và khiến các cổ sơn đồng loạt rung chuyển.","phanLoaiPhu":"Quan tài","hinhDang":"Nằm ngang trên đoạn nhai","dacDiem":"Nắp quan tài tự mở khi cổ sơn rung chuyển, sau đó một tấm da người rơi xuống.","congNang":[],"capNhatToi":"@c1274","tabs":{"tienTrinh":[{"chuong":"@c1274","loai":"xuất hiện","importance":"normal","giaiDoan":"Dị biến trên cổ sơn","text":"Nắp quan tài cổ mở ra khi sáu cổ sơn rung chuyển và một tấm da người rơi xuống.","anchor":"có một cái quan tài cổ ngang dọc, lúc này nắp quan tài càng ở mở ra","phamCap":"Không rõ"}]},"nguon":["@c1274"]},{"id":"da-nguoi-trong-quan-tai-co","name":"Da người trong quan tài cổ","cn":"","category":"khac","categoryLabel":"Di hài","phamCap":"Không rõ","soHuu":[],"trangThai":"Được đưa trở lại quan tài cổ","blurb":"Tấm da người cổ bay ra từ quan tài treo trên vách núi, phồng thành hình sinh linh và lao về phía Thạch Hạo cùng Thiên Giác Nghĩ nhỏ.","detail":"Tấm da có thể phồng lên, khô quắt và phát tiếng rít. Nó chịu một chớp giật quyền của Thạch Hạo mà không hư hại, sau đó được sinh vật lông đỏ nâng trở lại quan tài.","phanLoaiPhu":"Di hài","hinhDang":"Tấm da người có thể phồng thành hình sinh linh rồi khô quắt.","uyLuc":"Chịu được chớp giật quyền của Thạch Hạo mà da không tổn hại.","dacDiem":"Cứng cỏi, có thể phồng lên, phát tiếng rít và tự lao vào mục tiêu.","congNang":["Phồng thành hình sinh linh và lao về phía mục tiêu.","Chịu được chớp giật quyền của Thạch Hạo mà không bị phá hủy."],"capNhatToi":"@c1275","tabs":{"tienTrinh":[{"chuong":"@c1275","loai":"dùng","importance":"normal","giaiDoan":"Bay khỏi quan tài","text":"Tấm da người bay khỏi quan tài, phồng lên rồi lao vào Thạch Hạo và Thiên Giác Nghĩ nhỏ. Nó không bị tổn hại sau khi trúng chớp giật quyền và được sinh vật lông đỏ đưa trở lại quan tài.","anchor":"Ở điện quang bên trong, ở sóng khí bên trong, sinh linh kia bị đánh trúng, kịch liệt bốc lên, thế nhưng da không tổn hại","phamCap":"Không rõ"}]},"nguon":["@c1275"]},{"id":"quan-tai-co-treo-tren-vach-da","name":"Quan tài cổ treo trên vách đá","cn":"","category":"khac","categoryLabel":"Quan tài","phamCap":"Không rõ","soHuu":[],"trangThai":"Đã đóng nắp","blurb":"Một chiếc quan tài cổ treo lơ lửng trên vách đá tại Siêu Tuyệt Phong. Quan tài mở ra để tấm da người bay xuống rồi được sinh vật lông đỏ đóng lại.","detail":"Quan tài lưu giữ tấm da người cổ và được sinh vật lông đỏ quỳ lạy sau khi thu hồi tấm da. Chủ nhân cùng nguồn gốc của quan tài chưa được xác nhận.","phanLoaiPhu":"Quan tài cổ","hinhDang":"Treo lơ lửng trên vách đá Siêu Tuyệt Phong.","dacDiem":"Lưu giữ tấm da người và được sinh vật lông đỏ bảo vệ, quỳ lạy.","congNang":["Lưu giữ tấm da người cổ."],"capNhatToi":"@c1275","tabs":{"tienTrinh":[{"chuong":"@c1275","loai":"xuất hiện","importance":"normal","giaiDoan":"Mở rồi đóng lại","text":"Quan tài cổ mở ra để tấm da người bay xuống, sau đó được sinh vật lông đỏ đưa tấm da trở vào và đóng nắp.","anchor":"Sau đó, cái tay kia nâng da người, đưa nó đưa vào chiếc kia treo lơ lửng ở trên vách đá trong quan tài cổ, lại sẽ nắp quan tài hợp lại.","phamCap":"Không rõ"}]},"nguon":["@c1275"]},{"id":"luyen-tien-ho","name":"Luyện Tiên Hồ","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí","phanLoaiPhu":"Pháp khí dạng ấm","phamCap":"Không rõ","soHuu":["Hạc Vô Song"],"trangThai":"Còn tồn tại","hinhDang":"Chiếc ấm dài hơn nửa xích, toàn thân đen như mực.","uyLuc":"Uy thế phát ra có thể cầm cố Thạch Hạo và Thiên Giác Nghĩ ở ngoài khu vực tinh lực.","dacDiem":"Treo giữa trời như một mặt trời đen ảm đạm.","congNang":["Quấy nhiễu và hút những luồng tinh lực phóng lên từ chiến trường.","Thu thập tinh huyết của Chí Cường giả @c1289","Được rèn đúc để luyện chết Chân Tiên @c1289","Phối hợp đại pháp lực đánh gãy Bất Diệt phong @c1289"],"chuSoHuu":[{"ten":"Hạc Vô Song","tuChuong":"@c1289","denChuong":"","cachCoDuoc":"","trangThai":"Đã từng sử dụng"}],"blurb":"Chiếc ấm đen xuất hiện sau khi hắc phong cuốn lấy những cột tinh lực trên chiến trường. Thiên Giác Nghĩ dựa theo truyền thuyết để dè dặt nhận dạng nó là Luyện Tiên Hồ. (+) Pháp khí của Dị vực được dùng để bảo vệ đoàn người và thu luyện Tiên huyết tại cửa cổ giới. [CAN-SOAT-GOP]","detail":"Luyện Tiên Hồ dài hơn nửa xích, có hình dạng một chiếc ấm và toàn thân đen như mực. Nó xuất hiện sau khi cơn lốc đen quấy nhiễu rồi nuốt các luồng tinh lực đủ sức xé vực ngoại, đồng thời tỏa uy thế khiến Thạch Hạo và Thiên Giác Nghĩ không thể cử động. Người điều khiển và trạng thái thực sự của pháp khí này chưa được hé lộ.","capNhatToi":"@c1277","tabs":{"tienTrinh":[{"chuong":"@c1277","loai":"xuất hiện","importance":"normal","giaiDoan":"Hiện thế trên chiến trường","phamCap":"Không rõ","text":"Luyện Tiên Hồ xuất hiện sau khi hắc phong cuốn lấy những cột tinh lực và tỏa uy thế cầm cố Thạch Hạo cùng Thiên Giác Nghĩ.","anchor":"màu vàng con kiến nhỏ khàn giọng nói: \"Luyện Tiên Hồ.\""},{"chuong":"@c1289","loai":"dùng","importance":"normal","giaiDoan":"Phá Bất Diệt phong","phamCap":"Pháp bảo luyện tiên","text":"Luyện Tiên Hồ được hé lộ từng do Hạc Vô Song sử dụng để thu tinh huyết cường giả và được các Bất Hủ vận dụng khi đánh gãy Bất Diệt phong.","anchor":"chuyên môn vì là luyện chết Chân Tiên mà rèn đúc Luyện Tiên Hồ"}]},"nguon":["@c1277","@c1289","@c1336","@c1342"]},{"id":"trang-giay-da-thu-mau-vang","name":"Trang giấy da thú màu vàng","cn":"","category":"khac","categoryLabel":"Vật phẩm truyền kinh","phamCap":"Không rõ","soHuu":[],"trangThai":"Nằm trên Hoành Đại Sơn phong","blurb":"Một trang giấy bằng da thú màu vàng phát hào quang, phù hiệu và tự ngâm tụng cổ kinh.","detail":"Trang giấy chuyển động phía trên ngọn núi thần thánh, phát ra hào quang lớn lao cùng vô số phù hiệu. Vật phẩm tự ngâm tụng kinh văn được mô tả là mạnh nhất từ xưa đến nay.","phanLoaiPhu":"Vật phẩm truyền kinh","hinhDang":"Trang giấy bằng da thú màu vàng","dacDiem":"Chuyển động trên đỉnh núi, phát hào quang và vô số phù hiệu.","congNang":["Phát phù hiệu và tự ngâm tụng cổ kinh.","Dùng làm vật mang Bất Diệt Kinh."],"capNhatToi":"@c1279","tabs":{"tienTrinh":[{"chuong":"@c1279","loai":"xuất hiện","importance":"normal","giaiDoan":"Ngâm tụng cổ kinh","text":"Trang giấy da thú màu vàng xoay trên ngọn núi thần thánh, phát hào quang, phù hiệu và ngâm tụng kinh văn.","anchor":"Màu vàng da thú trang giấy, ở phát sinh hào quang lớn lao phía trên ngọn núi không ngừng chuyển động","phamCap":"Không rõ"},{"chuong":"@c1282","loai":"nhắc tới","importance":"normal","giaiDoan":"Trở thành mục tiêu tranh đoạt","text":"Các trang da thú màu vàng trên Hoành Đại Sơn phong được xác nhận có liên quan trực tiếp tới Bất Diệt Kinh.","anchor":"Sau đó, hắn nhìn về phía Hoành Đại Sơn phong trên vài tờ màu vàng da thú trang giấy."}]},"nguon":["@c1279","@c1282"],"aliases":["Vài tờ da thú màu vàng"]},{"id":"bon-kiem-thai-trong-thap-tu-con-nguoi","name":"Bốn kiếm thai trong thập tự con ngươi","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Kiếm thai","phanLoaiPhu":"Binh khí do đồng thuật giải phóng","phamCap":"Không rõ","soHuu":["Hạc Vô Song"],"trangThai":"Đã trở về thập tự con ngươi","blurb":"Bốn kiếm thai được giải phóng từ dấu thập tự trong đôi mắt Hạc Vô Song để thi triển Tru Tiên.","detail":"Bốn kiếm thai rơi vào hư không và đồng loạt đánh giết Thạch Hạo. Khi Đại La kiếm thai xuất hiện, chúng phản bản hoàn nguyên thành dấu thập tự rồi trở lại đôi mắt Hạc Vô Song.","hinhDang":"Bốn thanh kiếm thai có thể hoàn nguyên thành dấu thập tự màu vàng.","uyLuc":"Mang sát phạt khí ngập trời và có thể cắt nát thiên địa.","dacDiem":"Có thể chuyển đổi giữa hình thái bốn kiếm thai và dấu thập tự trong đôi mắt.","chuHienThoi":"Hạc Vô Song","congNang":["Làm phương tiện để Hạc Vô Song thi triển Tru Tiên.","Đồng loạt chém giết đối thủ."],"chuSoHuu":[{"ten":"Hạc Vô Song","tuChuong":"@c1284","denChuong":"","cachCoDuoc":"Được giải phóng từ thập tự con ngươi.","trangThai":"đang sở hữu"}],"capNhatToi":"@c1284","tabs":{"tienTrinh":[{"chuong":"@c1284","loai":"dùng","importance":"normal","giaiDoan":"Thi triển Tru Tiên","text":"Hạc Vô Song giải phóng bốn kiếm thai để thi triển Tru Tiên, sau đó thu chúng về mắt khi Đại La kiếm thai xuất hiện.","anchor":"bốn chiếc kiếm “phản bản hoàn nguyên”, hóa thành màu vàng thập tự","phamCap":"Không rõ"}]},"nguon":["@c1284"]},{"id":"nhuom-mau-hac-sac-co-thuyen","name":"Nhuốm máu hắc sắc cổ thuyền","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Cổ thuyền quỷ dị","phamCap":"","soHuu":[],"trangThai":"khong-ro","blurb":"Cổ thuyền nhuốm máu xuất hiện trong hư không, đại diện cho quỷ dị và điềm xấu.","detail":"Đây là một trong ba cảnh tượng đáng sợ nhất có thể gặp khi du hành trong hư không. Thạch Hạo từng lên con thuyền này, mang Đại La kiếm thai ra ngoài và biết được bí mật về Biên Hoang Thất Vương.","phanLoaiPhu":"Cổ thuyền quỷ dị","hinhDang":"Cổ thuyền màu đen nhuốm máu","dacDiem":"Sự xuất hiện của cổ thuyền trong hư không gắn với quỷ dị và điềm xấu.","congNang":["Mang theo quỷ dị và điềm xấu khi xuất hiện trong hư không."],"tabs":{"tienTrinh":[{"chuong":"@c1285","loai":"nhắc tới","importance":"normal","giaiDoan":"Cảnh tượng nguy hiểm trong hư không","text":"Cổ thuyền được xác nhận là một trong ba cảnh tượng đáng sợ nhất khi du hành trong hư không.","anchor":"một trong số đó là gặp phải nhuốm máu hắc sắc cổ thuyền, đại biểu quỷ dị còn có điềm xấu"}]},"capNhatToi":"@c1285","nguon":["@c1285"]},{"id":"hon-don-cung-dien-co-dien","name":"Hỗn Độn Cung Điện","cn":"","category":"phap-bao","categoryLabel":"Cổ điện","phamCap":"Không rõ","soHuu":[],"trangThai":"Trôi trong loạn lưu không gian","blurb":"Cổ điện có năng lực áp súc không gian và trấn áp những binh khí xao động bên trong.","detail":"Hỗn Độn Cung Điện chìm nổi giữa loạn lưu không gian, mảnh vỡ thời gian và sương mù hỗn độn. Khi Đại la kiếm thai đối đầu Luyện Tiên Hồ, cổ điện phát sáng và đồng thời áp chế cả hai.","phanLoaiPhu":"Cổ điện","congNang":["Áp súc không gian và trấn áp đồng thời hai cổ binh."],"dacDiem":"Chìm nổi trong loạn lưu không gian và sương mù hỗn độn.","tabs":{"tienTrinh":[{"chuong":"@c1286","loai":"dùng","importance":"normal","giaiDoan":"Trấn áp cổ binh","text":"Cung điện phát sáng, áp súc không gian và trấn áp Đại la kiếm thai cùng Luyện Tiên Hồ.","anchor":"nó phát sáng, không gian áp súc, lại muốn đồng thời đối phó hai cái cổ Binh"}]},"capNhatToi":"@c1286","nguon":["@c1286"]},{"id":"cuu-chuyen-tien-dan-vo-nat-sau-duoc-tra","name":"Cửu Chuyển Tiên Đan vỡ nát sau dược tra","cn":"","category":"dan-duoc","categoryLabel":"Dược tra tiên đan","phamCap":"Tiên đan đã vỡ","soHuu":["Hạc Vô Song"],"trangThai":"Đã dùng","blurb":"Phần dược tra còn lại của Cửu Chuyển Tiên Đan được Hạc Vô Song dùng để chữa thương.","detail":"Dược tra được cất trong Tử Kim hồ lô và vẫn chứa dược lực Trường Sinh, giúp Hạc Vô Song thúc đẩy quá trình phục hồi sau trọng thương.","congNang":["Thúc đẩy thân thể trọng thương hồi phục."],"dacDiem":"Là phần còn lại của tiên đan đã vỡ, có vị thuốc chính liên quan tới Trường Sinh dịch.","chuSoHuu":[{"ten":"Hạc Vô Song","tuChuong":"@c1286","denChuong":"@c1286","cachCoDuoc":"Cất giữ trong Tử Kim hồ lô","trangThai":"Đã dùng"}],"tabs":{"tienTrinh":[{"chuong":"@c1286","loai":"dùng","importance":"normal","giaiDoan":"Chữa thương","text":"Hạc Vô Song lấy dược tra từ Tử Kim hồ lô và nuốt để khôi phục sau trọng thương.","anchor":"Cửu Chuyển Tiên Đan vỡ nát sau dược tra","phamCap":"Tiên đan đã vỡ"}]},"capNhatToi":"@c1286","nguon":["@c1286"]},{"id":"tuyet-the-bao-dan-cua-hac-vo-song","name":"Tuyệt thế bảo đan của Hạc Vô Song","cn":"","category":"dan-duoc","categoryLabel":"Đan dược","phamCap":"Tuyệt thế bảo đan","soHuu":["Hạc Vô Song"],"trangThai":"Đã dùng","blurb":"Bảo đan luyện từ thần dược hiếm có, được Hạc Vô Song uống sau khi nối lại đầu với thân thể.","detail":"Đan dược có dược lực khiến người chết sống lại và được Hạc Vô Song dùng để phục hồi sau khi sống sót với đầu lâu bị xuyên thủng.","congNang":["Có thể làm người chết sống lại."],"dacDiem":"Được luyện từ thần dược hiếm có.","chuSoHuu":[{"ten":"Hạc Vô Song","tuChuong":"@c1286","denChuong":"@c1286","cachCoDuoc":"Mang theo bên mình","trangThai":"Đã dùng"}],"tabs":{"tienTrinh":[{"chuong":"@c1286","loai":"dùng","importance":"normal","giaiDoan":"Phục hồi thân thể","text":"Hạc Vô Song uống bảo đan ngay sau khi nối lại đầu với thân thể.","anchor":"Thứ này có thể làm người chết sống lại, là lấy thế hiếm có thần dược luyện thành","phamCap":"Tuyệt thế bảo đan"}]},"capNhatToi":"@c1286","nguon":["@c1286"]},{"id":"tu-kim-ho-lo","name":"Tử Kim hồ lô","cn":"","category":"khac","categoryLabel":"Vật chứa","phamCap":"Không rõ","soHuu":["Hạc Vô Song"],"trangThai":"Đang được sử dụng","blurb":"Hồ lô dùng để cất giữ dược tra Cửu Chuyển Tiên Đan.","detail":"Hạc Vô Song lấy Tử Kim hồ lô ra khi cần dùng phần dược tra tiên đan để chữa thương.","nguon":["@c1286"]},{"id":"bat-diet-kinh","name":"Bất Diệt Kinh","cn":"","aliases":[],"category":"khac","categoryLabel":"Kinh văn","phamCap":"Không rõ","soHuu":[],"trangThai":"Biến mất khỏi ngọn núi","blurb":"Bất Diệt Kinh là kinh văn được ghi trên những trang da thú màu vàng, từng lơ lửng trên một ngọn núi giữa chiến trường. Nó trở thành mục tiêu tranh đoạt khiến Thạch Hạo và Hạc Vô Song bước vào trận tử chiến, rồi biến mất khỏi ngọn núi sau biến cố. @c1287","detail":"Bất Diệt Kinh xuất hiện dưới dạng những trang kinh bằng da thú màu vàng, lơ lửng trên một ngọn núi giữa chiến trường. Cuộc tranh đoạt kinh văn đã khiến Thạch Hạo và Hạc Vô Song chuyển sang tử chiến; sau quãng thời gian dài như một kỷ nguyên, những trang kinh biến mất khỏi ngọn núi. @c1287","phanLoaiPhu":"Kinh văn trên da thú màu vàng","hinhDang":"Nhiều trang da thú màu vàng","dacDiem":"Kinh văn được ghi trên những trang da thú màu vàng, từng lơ lửng trên ngọn núi giữa chiến trường rồi biến mất sau biến cố. @c1287","congNang":[],"chuSoHuu":[],"capNhatToi":"@c1287","tabs":{"tienTrinh":[{"chuong":"@c1287","loai":"nhắc tới","importance":"major","giaiDoan":"Tranh đoạt rồi biến mất","text":"Bất Diệt Kinh trở thành mục tiêu khiến Thạch Hạo và Hạc Vô Song tử chiến, rồi biến mất khỏi ngọn núi sau biến thiên thời gian.","phamCap":"Không rõ","anchor":"từng với trên ngọn núi lơ lững vài tờ màu vàng da thú trang giấy, đó là bất diệt kinh."}]},"nguon":["@c1287"]},{"id":"chien-phu-cua-hac-vo-song","name":"Chiến phủ của Hạc Vô Song","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Không rõ","soHuu":["Hạc Vô Song"],"trangThai":"Không rõ","blurb":"Chiến phủ cán dài khoảng một trượng được Hạc Vô Song lấy ra từ mi tâm để giao chiến với Thạch Hạo.","detail":"Binh khí có hàn quang chói mắt, lưỡi sắc bén và cán dài như chiến mâu. Hạc Vô Song liên tục dùng nó chém đối thủ, nhưng thần lực của chiến phủ bị các vòng xoáy vàng của Kim Tuyền Ba Văn Công nuốt giảm.","hinhDang":"Chiến phủ cán dài khoảng một trượng, cán dài như chiến mâu.","chuHienThoi":"Hạc Vô Song","congNang":["Chém phá trong cuộc quyết chiến với Thạch Hạo."],"chuSoHuu":[{"ten":"Hạc Vô Song","tuChuong":"@c1287","denChuong":"","cachCoDuoc":"Được lấy ra từ mi tâm","trangThai":"đang sở hữu"}],"capNhatToi":"@c1287","tabs":{"tienTrinh":[{"chuong":"@c1287","loai":"dùng","importance":"normal","giaiDoan":"Đưa ra quyết chiến","text":"Hạc Vô Song lấy chiến phủ từ mi tâm và dùng nó liên tục chém Thạch Hạo.","phamCap":"Không rõ","anchor":"Mi tâm của hắn nứt ra, hạ xuống một cây chiến phủ (búa), hàn quang chói mắt"}]},"nguon":["@c1287"]},{"id":"kinh-thuoc","name":"Kinh thược","cn":"","aliases":["Bạch cốt chìa khóa"],"category":"khac","categoryLabel":"Chìa khóa truyền thừa","phamCap":"Bất hủ không hỏng","soHuu":["Thạch Hạo"],"trangThai":"Đang ở trong tay Thạch Hạo","blurb":"Kinh thược là chiếc chìa khóa bằng bạch cốt trắng như tuyết, ôn hòa như dương chi bạch ngọc và bất hủ không hỏng. Vật này được Thạch Hạo tìm thấy trong động phủ dưới lòng đất tại tiên gia cổ chiến trường, đồng thời là chìa khóa cần thiết để tiếp cận truyền thừa Bất Diệt Kinh trên Bất Diệt phong.","detail":"Thạch Hạo tìm được Kinh thược trong một động phủ dưới lòng đất tại tiên gia cổ chiến trường. Thiên Giác Nghĩ đời trước biết hắn sở hữu vật này nên chỉ dẫn hắn đến nơi truyền thừa; sau khi Thạch Hạo vượt qua thử thách của Bất Diệt phong, lão quạ đen xác nhận chiếc chìa khóa bạch cốt ấy chính là Kinh thược cần thiết để tiếp cận Bất Diệt Kinh @c1289.","phanLoaiPhu":"Chìa khóa mở truyền thừa","hinhDang":"Chìa khóa bằng bạch cốt trắng như tuyết","vatLieu":"Bạch cốt","nguonGoc":"Được Thạch Hạo tìm thấy trong động phủ dưới lòng đất tại tiên gia cổ chiến trường.","uyLuc":"Mở con đường tiếp cận Bất Diệt Kinh trên Bất Diệt phong.","dacDiem":"Chìa khóa bằng bạch cốt trắng như tuyết, ôn hòa như dương chi bạch ngọc và bất hủ không hỏng.","chuHienThoi":"Thạch Hạo","congNang":["Mở con đường tiếp cận truyền thừa Bất Diệt Kinh trên Bất Diệt phong @c1289"],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1289","denChuong":"","cachCoDuoc":"Tìm thấy trong động phủ dưới lòng đất tại tiên gia cổ chiến trường.","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1289","tabs":{"tienTrinh":[{"chuong":"@c1289","loai":"khai phong","importance":"major","giaiDoan":"Xác nhận chìa khóa truyền thừa","phamCap":"Bất hủ không hỏng","text":"Bạch cốt chìa khóa của Thạch Hạo được lão quạ đen xác nhận là Kinh thược cần thiết để tiếp cận Bất Diệt Kinh.","anchor":"Có kinh thược cái kia liền có thể đến Bất Diệt Kinh!"}]},"nguon":["@c1289"]},{"id":"duong-tien-ngoc","name":"Dưỡng Tiên ngọc","cn":"","category":"nguyen-lieu","categoryLabel":"Bảo liệu dưỡng hồn","phamCap":"Cấp báu vật","soHuu":["Thạch Hạo"],"trangThai":"Đã bị bóp nát","blurb":"Dưỡng Tiên ngọc là bảo liệu có khả năng dưỡng hồn, bảo vệ Nguyên Thần và che giấu linh thân khỏi sự cảm ứng của ngoại giới. Linh thân Mạnh Thiên Chính từng được phân giải, ẩn giấu trong ngọc và tái tổ hợp hiện ra khi Thạch Hạo bóp nát nó.","detail":"Dưỡng Tiên ngọc được dùng để dung chứa linh thân Mạnh Thiên Chính sau khi linh thân này phân giải, đồng thời che giấu khí tức khiến ngoại giới không thể nhận biết. Tới chương 1293, Thạch Hạo bóp nát ngọc, giải phóng sức mạnh linh hồn bên trong; phần linh hồn ấy đan xen, tái tổ hợp và hiện thành linh thân Mạnh Thiên Chính.","phanLoaiPhu":"Bảo liệu dưỡng hồn","vatLieu":"Cổ ngọc","congNang":["Dưỡng hồn và bảo vệ Nguyên Thần.","Cho phép linh thân phân giải, ẩn giấu bên trong và tránh sự cảm ứng của ngoại giới.","Khi ngọc bị bóp nát, linh thân được giải phóng, đan xen và tái tổ hợp để hiện ra. @c1293"],"dacDiem":"Có thể che giấu linh thân khiến ngoại giới không thể nhận biết.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1293","denChuong":"@c1293","cachCoDuoc":"Không nêu trong chương","trangThai":"Đã sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1293","loai":"dùng","importance":"major","giaiDoan":"Giải phóng linh thân","text":"Thạch Hạo bóp nát Dưỡng Tiên ngọc, khiến linh thân Mạnh Thiên Chính tái tổ hợp và hiện ra.","anchor":"linh thân có thể phân giải ở bên trong, ẩn náu ở trong, ngoại giới không cách nào nhận biết","phamCap":"Cấp báu vật"}]},"capNhatToi":"@c1293","nguon":["@c1293"]},{"id":"kim-sac-dao-bao-co-dong-tinh-than","name":"Kim sắc đạo bào cô đọng tinh thần","cn":"","category":"phap-bao","categoryLabel":"Pháp y","phamCap":"Không rõ","soHuu":["Vương Nhị"],"trangThai":"Đang được Vương Nhị sử dụng","blurb":"Kim sắc đạo bào của Vương Nhị được thêu nhật nguyệt tinh thần. Khi chủ nhân vận lực, các đại tinh trên áo có thể chuyển động, phát tiếng oanh minh và phóng ra tinh quang.","detail":"Pháp y có bề mặt thêu hình nhật nguyệt và tinh thần. Những đại tinh hiển hóa trên đạo bào vận chuyển theo lực lượng của Vương Nhị, tạo tiếng oanh minh và tinh quang.","phanLoaiPhu":"Pháp y","hinhDang":"Kim sắc đạo bào thêu nhật nguyệt tinh thần","dacDiem":"Các đại tinh trên áo có thể chuyển động và phóng tinh quang khi chủ nhân vận lực.","chuHienThoi":"Vương Nhị","congNang":["Hiển hóa và vận chuyển tinh thần trên bề mặt đạo bào. @c1296"],"chuSoHuu":[{"ten":"Vương Nhị","tuChuong":"@c1296","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1296","loai":"xuất hiện","importance":"normal","giaiDoan":"Vương Nhị chặn đường","text":"Kim sắc đạo bào xuất hiện trên người Vương Nhị với hình nhật nguyệt tinh thần thêu trên bề mặt.","anchor":"Hơn nữa, hắn Kim sắc pháp bào bên trên thêu lên nhật nguyệt tinh thần.","phamCap":"Không rõ"}]},"capNhatToi":"@c1296","nguon":["@c1296"]},{"id":"to-truyen-chien-kich-vuong-gia","name":"Tổ truyền chiến kích Vương gia","cn":"","aliases":["Tổ truyền tiên kích Vương gia"],"category":"phap-bao","categoryLabel":"Tiên binh","phamCap":"Tiên binh","soHuu":["Vương Trường Sinh","Vương gia"],"trangThai":"Đang được Vương Trường Sinh gọi ra","blurb":"Tổ binh Vương gia hiện ra từng đoạn từ mi tâm Vương Trường Sinh, mang tiên khí nhưng tỏa sát ý lạnh lẽo.","detail":"Một chùm sáng từ chiến kích xuyên thủng trời cao và phá hủy nhiều đại tinh ngoài vực. Vương Trường Sinh dùng nó để cân bằng uy thế của Thập Giới Đồ và từ chối cho Vương Cửu mượn vì không muốn xảy ra sai sót.","phanLoaiPhu":"Tru Thần lợi khí","nguonGoc":"Tổ truyền của Vương gia.","uyLuc":"Chùm sáng có thể xuyên thủng đại tinh ngoài vực.","dacDiem":"Mang tiên khí và Tiên huy nhưng tỏa sát ý lạnh lẽo.","congNang":["Phóng chùm sáng xuyên thủng trời cao và đại tinh ngoài vực."],"chuHienThoi":"Vương Trường Sinh","chuSoHuu":[{"ten":"Vương gia","tuChuong":"@c1299","denChuong":"","cachCoDuoc":"Tổ truyền","trangThai":"Tổ binh của gia tộc"},{"ten":"Vương Trường Sinh","tuChuong":"@c1299","denChuong":"","cachCoDuoc":"Gọi ra từ mi tâm","trangThai":"Đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1299","loai":"dùng","importance":"normal","giaiDoan":"Đối chọi Thập Giới Đồ","phamCap":"Tiên binh","text":"Vương Trường Sinh gọi chiến kích từ mi tâm và dùng chùm sáng của nó xuyên thủng các đại tinh ngoài vực để chấn nhiếp Mạnh Thiên Chính.","anchor":"nó mang theo tiên khí, lượn lờ Tiên huy, là một cây Tiên Binh"}]},"capNhatToi":"@c1299","nguon":["@c1299"]},{"id":"tien-vuong-quan-vai-liem","name":"Tiên Vương quấn vải liệm","cn":"","aliases":["Trận kỳ Từ gia","Chiến trận kỳ Từ gia"],"category":"phap-bao","categoryLabel":"Trận kỳ","phamCap":"Bảo vật gắn với vận mệnh Từ gia","soHuu":["Trường Sinh hoàng triều Từ gia","Mạnh Thiên Chính"],"trangThai":"Được Mạnh Thiên Chính mang theo","blurb":"Tiên Vương quấn vải liệm, còn được gọi là Thiết Huyết Chiến Kỳ, là trận kỳ của Trường Sinh hoàng triều Từ gia, mang sát phạt lực lớn và gắn với một quá khứ đẫm máu chưa được hé lộ. Bảo vật từng hóa giải thế công của tiên trận Vương gia, che chở mọi người, ngăn huyết linh và hấp thu Tiên huyết để tự tu bổ, tăng cường.","detail":"Mạnh Thiên Chính gọi Tiên Vương quấn vải liệm ra khi tiên trận một vạn ngọn núi của Vương gia phát động; mảnh vải rách nhuốm máu đã chặn và hóa giải toàn bộ ánh sáng công kích, khiến Vương Trường Sinh cùng Vương Đại nhận ra Từ gia cho đối phương mượn bảo vật liên quan đến vận mệnh gia tộc. Về sau, dưới tên Thiết Huyết Chiến Kỳ, bảo vật được dựng lên như một lá đại kỳ che kín bầu trời để bảo vệ mọi người trước nghi thức tế. Nó tiếp tục chặn huyết linh, hấp thu một phần Tiên huyết và nhờ đó bắt đầu tự tu bổ, tăng cường; khi bị bắt và giương động giữa không trung, chiến kỳ còn tạo nên cương phong.","hinhDang":"Một mảnh vải rách nhuốm máu.","nguonGoc":"Trận kỳ của Trường Sinh hoàng triều Từ gia.","uyLuc":"Có thể trấn áp và hóa giải toàn bộ ánh sáng công kích từ tiên trận một vạn ngọn núi của Vương gia.","dacDiem":"Là mảnh vải rách nhuốm máu đồng thời mang hình thái chiến kỳ, có sát phạt lực lớn, liên quan đến vận mệnh Từ gia và một quá khứ đẫm máu chưa được hé lộ.","congNang":["Hóa giải toàn bộ ánh sáng công kích của tiên trận Vương gia. @c1299","Dựng thành đại kỳ che kín bầu trời để bảo vệ mọi người trước nghi thức tế. @c1332","Chặn huyết linh. @c1336","Hấp thu một phần Tiên huyết để tự tu bổ và tăng cường. @c1336","Khi giương động giữa không trung có thể tạo nên cương phong. @c1342"],"chuHienThoi":"Mạnh Thiên Chính","chuSoHuu":[{"ten":"Trường Sinh hoàng triều Từ gia","tuChuong":"@c1299","denChuong":"","cachCoDuoc":"Bảo vật của gia tộc","trangThai":"Cho mượn"},{"ten":"Mạnh Thiên Chính","tuChuong":"@c1299","denChuong":"","cachCoDuoc":"Được Từ gia cho mượn","trangThai":"Đang mang theo"}],"tabs":{"tienTrinh":[{"chuong":"@c1299","loai":"dùng","importance":"normal","giaiDoan":"Hóa giải tiên trận","phamCap":"Bảo vật gắn với vận mệnh Từ gia","text":"Mạnh Thiên Chính gọi Tiên Vương quấn vải liệm ra, khiến toàn bộ ánh sáng công kích của tiên trận Vương gia bị hóa giải trước khi tới gần.","anchor":"cái kia xông tới ánh sáng toàn bộ bị vải rách hóa giải mất, không thể tới gần"}]},"capNhatToi":"@c1299","nguon":["@c1299"]},{"id":"tien-co-chien-ky","name":"Tiên Cổ Chiến Kỳ","cn":"","aliases":["Thiết Huyết Chiến Kỳ","Quấn vải liệm"],"category":"phap-bao","categoryLabel":"Chiến kỳ kiêm binh khí và trận pháp","phamCap":"Chí bảo Từ gia","soHuu":["Trường Sinh hoàng triều Từ gia","Mạnh Thiên Chính"],"trangThai":"Được Mạnh Thiên Chính mượn sử dụng @c1300","blurb":"Tiên Cổ Chiến Kỳ là hiệu kỳ từng xuất hiện trong trận chiến cuối thời Tiên Cổ, do một vị Chân Tiên cầm để dẫn các tộc nghênh chiến quân đội dị vực. Sau khi lần lượt bọc di thể tan nát của hai Tiên vương và hấp thu tinh huyết bản nguyên của họ, chiến kỳ được Từ gia tế luyện, khắc trận pháp Tiên đạo thành chí bảo. (+) Chiến kỳ cổ từng bao bọc thi thể của hai Tiên Vương, thấm máu và ý chí của những chiến giả Tiên cổ. [CAN-SOAT-GOP]","detail":"Sau trận chiến cuối thời Tiên Cổ, Tiên Cổ Chiến Kỳ từng được dùng để bọc di thể của hai Tiên vương tử trận, nhờ đó thấm tinh huyết bản nguyên của họ và thông linh. Về sau, chiến kỳ thuộc về Từ gia, được khắc trận pháp Tiên đạo và trở thành một hiện vật nằm giữa binh khí với trận pháp. Khi Mạnh Thiên Chính mang chiến kỳ tới cổ địa Vương gia, nó có thể mở đường qua trận pháp Tiên đạo tại đây, đồng thời phối hợp với Thập Giới Đồ để uy hiếp và gây thiệt hại lớn cho cổ địa Vương gia. @c1300","phanLoaiPhu":"Chiến kỳ kiêm binh khí và trận pháp","hinhDang":"Một lá cờ rách","nguonGoc":"Hiệu kỳ từng xuất hiện trong trận chiến cuối thời Tiên Cổ và sau đó thuộc về Từ gia.","uyLuc":"Khi phối hợp với sức mạnh của Mạnh Thiên Chính và Thập Giới Đồ, Tiên Cổ Chiến Kỳ có thể gây thiệt hại lớn cho cổ địa Vương gia. @c1300","dacDiem":"Từng bọc di thể tan nát của hai Tiên vương, thấm tinh huyết bản nguyên của họ, sau đó thông linh và được Từ gia khắc trận pháp Tiên đạo.","congNang":["Mở đường qua trận pháp Tiên đạo của Vương gia. @c1300","Phối hợp với Thập Giới Đồ để uy hiếp cổ địa Vương gia. @c1300"],"chuHienThoi":"Trường Sinh hoàng triều Từ gia","chuSoHuu":[{"ten":"Trường Sinh hoàng triều Từ gia","tuChuong":"@c1300","denChuong":"","cachCoDuoc":"Tế luyện chiến kỳ và khắc trận pháp Tiên đạo","trangThai":"chủ sở hữu"},{"ten":"Mạnh Thiên Chính","tuChuong":"@c1300","denChuong":"","cachCoDuoc":"Được Từ gia cho mượn","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1300","loai":"khai phong","importance":"major","giaiDoan":"Lộ rõ lai lịch và năng lực","text":"Tiên Cổ Chiến Kỳ được hé lộ từng bọc di thể tan nát của hai Tiên vương, hấp thu tinh huyết của họ và có thể mở đường qua trận pháp Tiên đạo của Vương gia.","anchor":"đã từng mang về hai cái Tiên vương phá nát di thể","phamCap":"Chí bảo Từ gia"}]},"dinhDanh":"goc","capNhatToi":"@c1300","nguon":["@c1300","@c1301","@c1303"]}]};
